window.AT={"mavzular":[{"k":"umumiy","n":"Umumiy qoidalar va atamalar","ic":"📘"},{"k":"belgilar","n":"Yo'l belgilari","ic":"🛑"},{"k":"chiziq","n":"Yo'l chiziqlari","ic":"〰️"},{"k":"ishora","n":"Svetofor va tartibga soluvchi ishoralari","ic":"🚦"},{"k":"manevr","n":"Harakatni boshlash va manevr","ic":"↪️"},{"k":"tezlik","n":"Tezlik, quvib o'tish, oraliq","ic":"🏎️"},{"k":"toxtash","n":"To'xtash va to'xtab turish","ic":"🅿️"},{"k":"chorraha","n":"Chorrahalar","ic":"✖️"},{"k":"maxsus","n":"Piyodalar, bekatlar, temir yo'l, avtomagistral","ic":"🚸"},{"k":"yoritish","n":"Yoritish asboblari va signallar","ic":"💡"},{"k":"tashish","n":"Shatakka olish, odam va yuk tashish","ic":"🚛"},{"k":"texnik","n":"Texnik holat va jihozlar","ic":"🔧"},{"k":"tibbiy","n":"Birinchi tibbiy yordam","ic":"🩺"}],"savollar":[{"id":1,"m":"belgilar","s":"Rasmdagi belgi nima haqida ogohlantiradi?","v":["Oldinda asosiy yo'l bilan kesishuv bor","Oldinda ikkinchi darajali yo'l bilan kesishuv bor","Oldinda teng ahamiyatli yo'llar chorrahasi bor","Oldinda tibbiy yordam ko'rsatish joyi bor"],"j":2,"i":"Bu – \"Teng ahamiyatli yo'llar kesishuvi\" belgisi. Bunday chorrahada relssiz transport vositasi haydovchisi o'ngdan yaqinlashayotgan transport vositalariga yo'l beradi (1-ilova, 1.6-belgi; YHQ, 105-band).","r":{"b":"1.6"},"q":"Teng ahamiyatli yo'llar chorrahasida relssiz transport vositasi haydovchisi o'ngdan yaqinlashayotganlarga yo'l beradi.","e":"O'ngdan kelgan – mehmon: unga yo'l ber."},{"id":2,"m":"belgilar","s":"Aholi punktidan tashqarida rasmdagi belgi xavfli joydan qancha masofa oldin o'rnatiladi (7.1.1 qo'shimcha belgisi bo'lmasa)?","v":["10–15 m","50–100 m","150–300 m","300–500 m"],"j":2,"i":"Ogohlantiruvchi belgilar aholi punktlarida xavfli joydan 50–100 m, aholi punktidan tashqarida 150–300 m oldin o'rnatiladi. Boshqa masofada qo'yilsa, masofa 7.1.1 belgisi bilan ko'rsatiladi (1-ilova, 1-bo'lim).","r":{"b":"1.15"},"q":"Ogohlantiruvchi belgilar aholi punktida xavfli joydan 50–100 m, aholi punktidan tashqarida 150–300 m oldin o'rnatiladi.","e":"Tashqarida masofa uch baravar: 50–100 m o'rniga 150–300 m."},{"id":3,"m":"belgilar","s":"Rasmdagi belgi qayerda o'rnatiladi?","v":["Shlagbaumsiz bir izli temir yo'l kesishmasining bevosita oldida, eng yaqin relsdan kamida 20 m masofada","Shlagbaumli temir yo'l kesishmasidan 150–300 m oldin","Tramvay yo'li bilan kesishuvning bevosita oldida","Ko'p izli temir yo'l kesishmasidan keyin"],"j":0,"i":"\"Bir izli temir yo'l\" belgisi shlagbaumsiz kesishmaning bevosita oldida, eng yaqin relsdan kamida 20 m masofada o'rnatiladi; ikki va undan ortiq izli kesishmada 1.3.2 qo'yiladi (1-ilova, 1.3.1-belgi).","r":{"b":"1.3.1"},"q":"1.3.1 belgisi shlagbaumsiz bir izli temir yo'l kesishmasining bevosita oldida, eng yaqin relsdan kamida 20 m masofada turadi.","e":"Bitta iz – 1.3.1, ko'p iz – 1.3.2; ikkalasi ham shlagbaumsiz kesishmada."},{"id":4,"m":"belgilar","s":"Rasmdagi belgilar nimani bildiradi?","v":["Ta'mirlash ishlari olib borilayotgan qism uzunligi 150 m","Ta'mirlash ishlari olib borilayotgan joy belgidan 150 m masofada boshlanadi","Ta'mirlash ishlari tufayli 150 m davomida to'xtash taqiqlanadi"],"j":1,"i":"7.1.1 \"Obyektgacha bo'lgan masofa\" belgisi belgidan xavfli joy boshlanishigacha bo'lgan masofani ko'rsatadi. Xavfli qismning uzunligi esa 7.2.1 belgisi bilan ko'rsatiladi (1-ilova, 7.1.1 va 7.2.1-belgilar).","r":{"b":["1.23","7.1.1"]},"q":"7.1.1 belgisi xavfli joy boshlanishigacha bo'lgan masofani, 7.2.1 belgisi esa xavfli qismning uzunligini ko'rsatadi.","e":"7.1 – \"qancha qoldi\", 7.2 – \"qancha davom etadi\"."},{"id":5,"m":"belgilar","s":"Rasmdagi belgi o'rnatilgan yo'lda harakatlanayotgan haydovchi qanday huquqqa ega?","v":["Har qanday chorrahada, svetofor ishorasidan qat'i nazar, birinchi o'tish huquqiga","Quvib o'tish taqiqlangan joylarda ham quvib o'tish huquqiga","Qatnov qismining istalgan joyida to'xtab turish huquqiga","Tartibga solinmagan chorrahalarda ikkinchi darajali yo'ldan kelayotganlarga nisbatan oldin o'tish huquqiga"],"j":3,"i":"\"Asosiy yo'l\" belgisi tartibga solinmagan chorrahalarda imtiyoz beradi. Chorraha svetofor yoki tartibga soluvchi bilan boshqarilsa, ularning ishoralariga amal qilinadi (1-ilova, 2.1-belgi; YHQ, 98-band).","r":{"b":"2.1"},"q":"2.1 \"Asosiy yo'l\" belgisi tartibga solinmagan chorrahalarda imtiyoz beradi; svetofor yoki tartibga soluvchi bo'lsa, ularga amal qilinadi.","e":"Tuzoq: svetofor ishlab turgan chorrahada \"Asosiy yo'l\" belgisi imtiyoz bermaydi."},{"id":6,"m":"belgilar","s":"Aholi punktidan tashqarida rasmdagi belgi bilan belgilangan yo'lning qatnov qismida nima taqiqlanadi?","v":["Quvib o'tish","Chapga burilish","To'xtab turish","Tovushli ishora bilan quvib o'tishdan ogohlantirish"],"j":2,"i":"Aholi punktidan tashqarida 2.1 \"Asosiy yo'l\" belgisi bilan belgilangan yo'lning qatnov qismida to'xtab turish taqiqlanadi (YHQ, 92-band).","r":{"b":"2.1"},"q":"Aholi punktidan tashqarida 2.1 belgisi bilan belgilangan yo'lning qatnov qismida to'xtab turish taqiqlanadi.","e":"Tuzoq: bu yerda to'xtab turish taqiqlangan, to'xtash emas."},{"id":7,"m":"belgilar","s":"Chorraha oldida rasmdagi belgilar o'rnatilgan. Ular nimani bildiradi?","v":["Siz asosiy yo'ldasiz, asosiy yo'l chorrahada o'ngga buriladi","Siz ikkinchi darajali yo'ldasiz, asosiy yo'l chorrahada o'ngga buriladi","Siz asosiy yo'ldasiz, chorrahada faqat o'ngga burilish mumkin","Siz asosiy yo'ldasiz, asosiy yo'l to'g'riga davom etadi"],"j":0,"i":"2.1 belgisi asosiy yo'lda ekaningizni, 7.13 qo'shimcha belgisi esa chorrahada asosiy yo'lning yo'nalishini ko'rsatadi. 7.13 harakat yo'nalishini cheklamaydi (1-ilova, 2.1 va 7.13-belgilar).","r":{"b":["2.1","7.13"]},"q":"7.13 qo'shimcha belgisi chorrahada asosiy yo'lning yo'nalishini ko'rsatadi, harakat yo'nalishini esa cheklamaydi.","e":"7.13 – xarita, buyruq emas: asosiy yo'l qayoqqa ketishini chizadi, sizni u yoqqa majburlamaydi."},{"id":8,"m":"belgilar","s":"Rasmdagi belgi o'rnatilgan tartibga solinmagan chorrahaga yaqinlashyapsiz. Kesib o'tilayotgan yo'lda transport vositalari yo'q, ko'rinish yaxshi. Qanday harakatlanasiz?","v":["To'xtash chizig'i oldida albatta to'xtab, keyin harakatni davom ettiraman","Tovushli ishora berib, keyin o'taman","To'xtamasdan harakatni davom ettirishim mumkin"],"j":2,"i":"\"Yo'l bering!\" belgisi kesib o'tilayotgan yo'ldagi transport vositalariga yo'l berishni talab qiladi; yo'l beradigan hech kim bo'lmasa, to'xtash shart emas. Har doim to'xtash 2.5 belgisida talab qilinadi (1-ilova, 2.4 va 2.5-belgilar).","r":{"b":"2.4"},"q":"2.4 \"Yo'l bering!\" belgisida kesib o'tilayotgan yo'ldagilarga yo'l beriladi; yo'l beradigan hech kim bo'lmasa, to'xtash shart emas.","e":"2.4 – qara va yo'l ber; har doim to'xtash – faqat 2.5 da."},{"id":9,"m":"belgilar","s":"Rasmdagi belgi o'rnatilgan chorrahada to'xtash chizig'i yo'q, kesib o'tiladigan yo'l bo'm-bo'sh. Haydovchi nima qilishi kerak?","v":["Kesib o'tiladigan qatnov qismining chetida to'xtab, so'ng harakatni davom ettirishi","Yo'l bo'sh bo'lgani uchun to'xtamasdan o'tishi","Faqat tezlikni kamaytirib, to'xtamasdan o'tishi"],"j":0,"i":"\"To'xtamasdan harakatlanish taqiqlangan\" belgisi to'xtash chizig'i oldida, u bo'lmasa kesib o'tiladigan qatnov qismining chetida to'xtashni va 2.4 belgisidagidek yo'l berishni talab qiladi (1-ilova, 2.5-belgi).","r":{"b":"2.5"},"q":"2.5 belgisida to'xtash chizig'i oldida, u bo'lmasa kesib o'tiladigan qatnov qismi chetida har doim to'xtab, so'ng yo'l beriladi.","e":"STOP – yo'l bo'sh bo'lsa ham STOP: avval g'ildirak to'xtaydi, keyin ko'z qaraydi."},{"id":10,"m":"belgilar","s":"Yo'lning tor qismi oldida rasmdagi belgi o'rnatilgan. Qarama-qarshi tomondan yengil avtomobil tor qismga kirib kelmoqda. Siz nima qilasiz?","v":["Tor qismga birinchi kiraman, chunki men o'ng tomondaman","Faralarni o'chirib-yoqib ogohlantiraman va birinchi o'taman","Unga yo'l beraman va u o'tib ketgach tor qismga kiraman"],"j":2,"i":"\"Ro'para harakatlanishning ustunligi\" belgisi qarama-qarshi harakatni qiyinlashtiradigan bo'lsa, tor qismga kirishni taqiqlaydi: tor qismdagi yoki unga yaqinlashgan ro'paradagi transport vositasiga yo'l beriladi (1-ilova, 2.6-belgi).","r":{"b":"2.6"},"q":"2.6 belgisida qarama-qarshi harakatni qiyinlashtirsa, tor qismga kirish taqiqlanadi: ro'paradan kelayotganga yo'l beriladi.","e":"Tuzoq: o'ng tomonda ekaningiz tor qismda imtiyoz bermaydi – belgiga qarang."},{"id":11,"m":"belgilar","s":"Yo'lning tor qismida rasmdagi belgi o'rnatilgan. Bu belgi sizga nimani bildiradi?","v":["Qarama-qarshi yo'nalishdan kelayotgan transport vositalariga yo'l berishingiz kerak","Tor qismda ro'paradan kelayotgan transport vositalariga nisbatan imtiyozga egasiz","Bir tomonlama harakatli yo'l boshlanadi","Tor qismda quvib o'tishga ruxsat etiladi"],"j":1,"i":"\"Ro'paradagi harakatlanishga nisbatan imtiyoz\" belgisi yo'lning tor qismida ro'paradan kelayotgan transport vositalariga nisbatan imtiyoz beradi (1-ilova, 2.7-belgi).","r":{"b":"2.7"},"q":"2.7 belgisi yo'lning tor qismida ro'paradan kelayotgan transport vositalariga nisbatan imtiyoz beradi.","e":"Juftlik: 2.6 – avval ro'paradagi o'tadi, 2.7 – avval siz o'tasiz."},{"id":12,"m":"belgilar","s":"Rasmdagi belgi quyidagilardan qaysi biriga tatbiq etilmaydi?","v":["Yo'nalishli avtobusga","Yo'nalishsiz taksiga","Mototsiklga","Yengil avtomobilga"],"j":0,"i":"\"Kirish taqiqlangan\" belgisi barcha transport vositalarining kirishini taqiqlaydi, lekin 3.1–3.3, 3.18.1, 3.18.2, 3.19 va 3.27 belgilari yo'nalishli transport vositalariga tatbiq etilmaydi (1-ilova, 3-bo'lim).","r":{"b":"3.1"},"q":"3.1–3.3, 3.18.1, 3.18.2, 3.19 va 3.27 belgilari yo'nalishli transport vositalariga tatbiq etilmaydi.","e":"Tuzoq: \"Kirish taqiqlangan\" hammaga, lekin yo'nalishli avtobus o'z yo'nalishida o'taveradi."},{"id":13,"m":"belgilar","s":"Rasmdagi belgi o'rnatilgan ko'cha bo'ylab sizning uyingiz joylashgan. O'z yengil avtomobilingizda uyingizgacha borishingiz mumkinmi?","v":["Mumkin emas, belgi barcha transport vositalariga istisnosiz taalluqli","Faqat tungi vaqtda mumkin","Mumkin: belgi shu hududda yashovchi fuqarolarga tegishli transport vositalariga tatbiq etilmaydi"],"j":2,"i":"3.2–3.8 belgilari ta'sir oralig'idagi korxonalarga xizmat ko'rsatuvchi, shuningdek shu hududda yashovchi yoki ishlovchi fuqarolarga xizmat ko'rsatuvchi yoki ularga tegishli transport vositalariga tatbiq etilmaydi; ular hududga eng yaqin chorrahadan kirib chiqadi (1-ilova, 3-bo'lim).","r":{"b":"3.2"},"q":"3.2–3.8 belgilari shu hududda yashovchi, ishlovchi yoki unga xizmat ko'rsatuvchilarning transport vositalariga tatbiq etilmaydi.","e":"Uyingiz zona ichida bo'lsa, belgi uyga borishni to'smaydi – eng yaqin chorrahadan kirasiz."},{"id":14,"m":"belgilar","s":"Rasmdagi belgida vazn ko'rsatilmagan. Quyidagilardan qaysi biri bu yo'lga kirishi mumkin? (Ularning hech biri shu hududga xizmat ko'rsatmaydi.)","v":["Ruxsat etilgan to'liq vazni 5 t bo'lgan, hozir yuksiz yuk avtomobili","G'ildirakli traktor","Ruxsat etilgan to'liq vazni 12 t bo'lgan tirkamali yuk avtomobili","Odam tashishga mo'ljallangan, ruxsat etilgan to'liq vazni 7 t bo'lgan yuk avtomobili"],"j":3,"i":"Vazn ko'rsatilmagan 3.4 belgisi ruxsat etilgan to'liq vazni 3,5 t dan ortiq yuk avtomobillari, traktorlar va o'ziyurar mashinalarning harakatini taqiqlaydi. Bortiga qiya oq chiziq tortilgan yoki odam tashishga mo'ljallangan yuk avtomobillari bundan mustasno (1-ilova, 3.4-belgi).","r":{"b":"3.4"},"q":"Vazn yozilmagan 3.4 belgisi 3,5 t dan og'ir yuk avtomobili, traktor va o'ziyurar mashinaga taqiq; odam tashuvchi yuk avtomobili mustasno.","e":"3.4 – pasportdagi vazn (ruxsat etilgan to'liq), 3.11 – tarozidagi vazn (haqiqiy)."},{"id":15,"m":"belgilar","s":"Ko'prik oldida rasmdagi belgi o'rnatilgan. Ruxsat etilgan to'liq vazni 10 t bo'lgan yuk avtomobili hozir yuksiz, uning haqiqiy vazni 6 t. U ko'prikka kirishi mumkinmi?","v":["Mumkin emas, chunki uning ruxsat etilgan to'liq vazni belgida ko'rsatilganidan ko'p","Mumkin, chunki uning haqiqiy vazni belgida ko'rsatilganidan kam","Mumkin emas, bu belgi barcha yuk avtomobillariga taalluqli"],"j":1,"i":"\"Vazn cheklangan\" belgisi haqiqiy umumiy vazni belgida ko'rsatilganidan ortiq transport vositalarining harakatini taqiqlaydi. Bunda ruxsat etilgan to'liq vazn emas, haqiqiy vazn hisobga olinadi (1-ilova, 3.11-belgi).","r":{"b":"3.11"},"q":"3.11 \"Vazn cheklangan\" belgisida transport vositasining haqiqiy umumiy vazni belgidagidan oshmasligi kerak.","e":"3.11 – tarozi belgisi: pasportdagi emas, hozirgi haqiqiy vazn hisoblanadi."},{"id":16,"m":"belgilar","s":"Yo'l o'tkazgich ostida rasmdagi belgi o'rnatilgan. Yuk avtomobilining o'z balandligi 3,2 m, ortilgan yuk bilan birgalikda esa 3,8 m. U o'tishi mumkinmi?","v":["Mumkin emas, chunki yuk bilan birgalikdagi gabarit balandligi 3,5 m dan ortiq","Mumkin, chunki avtomobilning o'z balandligi 3,5 m dan kam","Mumkin, agar sekin harakatlansa"],"j":0,"i":"\"Cheklangan balandlik\" belgisi gabarit balandligi (yuk bilan yoki yuksiz) belgida ko'rsatilganidan ortiq transport vositalarining harakatini taqiqlaydi (1-ilova, 3.13-belgi).","r":{"b":"3.13"},"q":"3.13 belgisida gabarit balandlik yuk bilan birga hisoblanadi va belgida ko'rsatilganidan oshmasligi kerak.","e":"Ko'prikka mashina emas, eng baland nuqta uriladi – yuk ham hisobda."},{"id":17,"m":"belgilar","s":"Rasmdagi belgi o'rnatilgan chorrahada nima taqiqlanadi?","v":["Qayrilib olish","Chapga burilish","O'ngga burilish","To'g'riga harakatlanish"],"j":0,"i":"\"Qayrilish taqiqlangan\" belgisi faqat qayrilib olishni taqiqlaydi; burilish va to'g'riga harakatlanish belgida taqiqlanmagan (1-ilova, 3.19-belgi).","r":{"b":"3.19"},"q":"3.19 \"Qayrilish taqiqlangan\" belgisi faqat qayrilib olishni taqiqlaydi; burilish va to'g'riga yurish taqiqlanmaydi.","e":"Tuzoq: qayrilish taqiqi chapga burilishni taqiqlamaydi – chapga burilish taqiqi 3.18.2 belgisi."},{"id":18,"m":"belgilar","s":"Rasmdagi belgi ta'sir oralig'ida quyidagilardan qaysi birini quvib o'tish mumkin? Boshqa cheklovlar yo'q, chiziqlar quvib o'tishni taqiqlamaydi, qarama-qarshi tasma bo'sh.","v":["Soatiga 50 km tezlikda ketayotgan yengil avtomobilni","Ketma-ket soatiga 30 km tezlikda ketayotgan ikkita yuk avtomobilini","Soatiga 45 km tezlikda ketayotgan avtobusni","Soatiga 30 km tezlikda ketayotgan yakka traktorni"],"j":3,"i":"\"Quvib o'tish taqiqlangan\" belgisi soatiga 40 km dan kam tezlikda harakatlanayotgan yakka transport vositasidan boshqa barcha transport vositalarini quvib o'tishni taqiqlaydi (1-ilova, 3.20-belgi).","r":{"b":"3.20"},"q":"3.20 belgisi ta'sir oralig'ida faqat soatiga 40 km dan sekin ketayotgan yakka transport vositasini quvib o'tish mumkin.","e":"\"Yakka va 40 dan sekin\" – ikkala shart birga: ketma-ket ikkitasini ham, tez ketayotganni ham quvib bo'lmaydi."},{"id":19,"m":"belgilar","s":"Aholi punktida rasmdagi belgi o'rnatilgan, 7.2.1 qo'shimcha belgisi yo'q. Belgidan keyin avval o'ng tomonda avtomobil to'xtash joyidan chiqish joyi, undan keyin chorraha bor. Belgining ta'siri qayerda tugaydi?","v":["Avtomobil to'xtash joyidan chiqish joyida","Aholi punktining oxirida","Belgidan keyingi chorrahada","Belgidan 100 m keyin"],"j":2,"i":"3.16, 3.20, 3.22, 3.24, 3.26–3.30 belgilarining ta'siri belgidan keyingi eng yaqin chorrahagacha davom etadi. Yondosh hududdan (hovli, avtomobil to'xtash joyi) chiqish joylarida ta'sir to'xtamaydi (1-ilova, 3-bo'lim).","r":{"b":"3.20"},"q":"3.16, 3.20, 3.22, 3.24, 3.26–3.30 belgilari eng yaqin chorrahagacha, u bo'lmasa aholi punktining oxirigacha amal qiladi.","e":"Tuzoq: hovli yoki avtomobil to'xtash joyidan chiqish chorraha emas – belgi ta'siri davom etadi."},{"id":20,"m":"belgilar","s":"Aholi punktiga yaqinlashayotganda yo'l chetida rasmdagi belgi o'rnatilgan. Belgi bilan aholi punkti orasida chorraha yo'q. Belgining ta'siri qayergacha saqlanadi?","v":["Belgidan 300 m masofagacha","Aholi punktining boshlanishi (5.22) belgisigacha","Aholi punktining oxiri (5.23) belgisigacha"],"j":1,"i":"Aholi punktiga yetmasdan o'rnatilgan 3.24 \"Yuqori tezlik cheklangan\" belgisining ta'siri 5.22 belgisigacha saqlanadi (1-ilova, 3-bo'lim).","r":{"b":"3.24"},"q":"Aholi punktiga yetmasdan o'rnatilgan 3.24 belgisining ta'siri 5.22 \"Aholi punktining boshlanishi\" belgisigacha saqlanadi.","e":"5.22 – marra: shu yerda eski cheklov tugaydi, aholi punkti qoidalari boshlanadi."},{"id":21,"m":"belgilar","s":"Aholi punktidan tashqarida rasmdagi belgilar o'rnatilgan, boshqa cheklovlar yo'q. Tirkamasiz yengil avtomobil qanday eng yuqori tezlikda harakatlanishi mumkin?","v":["50 km/soat","70 km/soat","90 km/soat","100 km/soat"],"j":3,"i":"7.4.1 qo'shimcha belgisi asosiy belgining ta'sirini faqat to'liq vazni 3,5 t dan ortiq yuk avtomobillariga (tirkamalilari ham) tatbiq etadi. Yengil avtomobil uchun aholi punktidan tashqarida 100 km/soat amal qiladi (1-ilova, 7.4.1-belgi; YHQ, 79-band).","r":{"b":["3.24","7.4.1"]},"q":"7.4.1 qo'shimcha belgisi asosiy belgi ta'sirini faqat yuk avtomobillariga (tirkamalilariga ham) tatbiq etadi, yengil avtomobilga emas.","e":"Plastinkadagi rasm – manzil: yuk mashinasi chizilgan bo'lsa, cheklov faqat yuk mashinasiga."},{"id":22,"m":"belgilar","s":"Rasmdagi belgi ta'sir oralig'ida quyidagilardan qaysi biri to'xtashi mumkin?","v":["Yo'lovchini tushirayotgan shaxsiy yengil avtomobil","Yuk tushirayotgan yuk avtomobili","Yo'lovchilarni tushirayotgan yo'nalishsiz yengil taksi","Haydovchisi do'konga kirib chiqmoqchi bo'lgan yengil avtomobil"],"j":2,"i":"\"To'xtash taqiqlangan\" belgisi to'xtashni ham, to'xtab turishni ham taqiqlaydi. U yo'lovchilarni chiqarayotgan yoki tushirayotgan yo'nalishsiz yengil taksilarga hamda yo'nalishli transport vositalariga tatbiq etilmaydi (1-ilova, 3-bo'lim).","r":{"b":"3.27"},"q":"3.27 to'xtash va to'xtab turishni taqiqlaydi; yo'lovchi chiqarayotgan yoki tushirayotgan taksi va yo'nalishli transport mustasno.","e":"Tuzoq: shaxsiy avtomobil yo'lovchi tushirish uchun ham to'xtay olmaydi – bu imtiyoz taksiniki."},{"id":23,"m":"belgilar","s":"Rasmdagi belgilar nimani bildiradi?","v":["To'xtash taqiqlangan; bu joyda to'xtagan transport vositalari majburiy evakuatsiya qilinadi","Faqat evakuatorlar to'xtashi mumkin","To'xtab turish taqiqlangan, ammo 10 daqiqagacha to'xtash mumkin","Oldinda evakuator xizmati joylashgan"],"j":0,"i":"3.27 belgisi to'xtash va to'xtab turishni taqiqlaydi, 7.21 \"Evakuator ishlamoqda\" belgisi esa 3.27–3.30 belgilari ta'sir oralig'ida to'xtagan transport vositalari majburiy evakuatsiya qilinishini ko'rsatadi (1-ilova, 3.27 va 7.21-belgilar).","r":{"b":["3.27","7.21"]},"q":"3.27–3.30 belgilari 7.21 \"Evakuator ishlamoqda\" bilan bo'lsa, u yerda to'xtagan transport vositasi majburiy evakuatsiya qilinadi.","e":"Evakuator chizilgan plastinka – \"to'xtasang, olib ketaman\" degani."},{"id":24,"m":"belgilar","s":"Rasmdagi belgi ta'sir oralig'ida quyidagilardan qaysi biri to'xtab turishi mumkin?","v":["Taksometri o'chirilgan taksi","Avariya chirog'i yoqilgan shaxsiy yengil avtomobil","Ruxsat etilgan to'liq vazni 3 t bo'lgan yuk avtomobili","\"Nogiron\" belgisi o'rnatilgan, nogironligi bo'lgan haydovchi boshqarayotgan yengil avtomobil"],"j":3,"i":"\"Nogiron\" belgisi o'rnatilgan transport vositalarini boshqarayotgan nogironligi bo'lgan haydovchilar 3.2, 3.3 va 3.28 belgilari talablaridan chetga chiqishi mumkin. Taksilarga 3.28 faqat taksometri ishlab turganda tatbiq etilmaydi (1-ilova, 3-bo'lim).","r":{"b":"3.28"},"q":"\"Nogiron\" belgili transport vositasini boshqarayotgan nogironligi bo'lgan haydovchi 3.2, 3.3 va 3.28 talablaridan chetga chiqishi mumkin.","e":"Tuzoq: taksi 3.28 dan faqat taksometri ishlab turganda ozod; o'chiq taksometr – oddiy mashina."},{"id":25,"m":"belgilar","s":"Ko'chaning bir tomonida rasmdagi birinchi belgi, qarama-qarshi tomonida ikkinchi belgi o'rnatilgan. Qaysi vaqtda ikkala tomonda ham to'xtab turish mumkin?","v":["18:00 dan 20:00 gacha","19:00 dan 21:00 gacha","21:00 dan 07:00 gacha","08:00 dan 10:00 gacha"],"j":1,"i":"3.29 va 3.30 belgilari qatnov qismining qarama-qarshi tomonlarida o'rnatilgan bo'lsa, soat 19:00 dan 21:00 gacha (transport vositasini boshqa tomonga o'tkazish vaqti) ikkala tomonda ham to'xtab turish mumkin (1-ilova, 3.29 va 3.30-belgilar).","r":{"b":["3.29","3.30"]},"q":"3.29 va 3.30 belgilari qarama-qarshi tomonlarda bo'lsa, soat 19:00 dan 21:00 gacha ikkala tomonda ham to'xtab turish mumkin.","e":"19 dan 21 gacha – \"ko'chish soatlari\": mashinani narigi tomonga o'tkazish uchun ikki soat."},{"id":26,"m":"belgilar","s":"Rasmdagi belgi o'rnatilgan chorrahada qaysi yo'nalishlarda harakatlanish mumkin?","v":["Faqat chapga; qayrilib olish taqiqlanadi","Chapga va to'g'riga","Chapga va o'ngga","Chapga burilish va qayrilib olish"],"j":3,"i":"4.1.1–4.1.6 belgilari faqat ko'rsatilgan yo'nalishlarda harakatlanishga ruxsat beradi. Chapga burilishga ruxsat beruvchi belgi qayrilib olishga ham ruxsat beradi (1-ilova, 4-bo'lim).","r":{"b":"4.1.3"},"q":"4.1.1–4.1.6 belgilari faqat ko'rsatilgan yo'nalishlarga ruxsat beradi; chapga ruxsat beruvchi belgi qayrilishga ham ruxsat beradi.","e":"Chapga ruxsat bo'lsa – qayrilish ham ruxsat: chap strelka ikkalasini ochadi."},{"id":27,"m":"belgilar","s":"Rasmdagi belgi chorrahadan keyin, yo'l qismining boshida o'rnatilgan. Shu yo'l qismida o'ng tomondagi hovliga burilish mumkinmi?","v":["Mumkin, belgi o'ng tomondagi hovlilar va boshqa yondosh hududlarga burilishni taqiqlamaydi","Mumkin emas, faqat to'g'riga harakatlanish mumkin","Faqat yo'nalishli transport vositalariga mumkin"],"j":0,"i":"Yo'l qismining boshida o'rnatilgan \"Harakatlanish to'g'riga\" belgisi eng yaqin chorrahagacha amal qiladi va o'ng tomonda joylashgan hovlilarga hamda yondosh hududlarga burilishni taqiqlamaydi (1-ilova, 4-bo'lim).","r":{"b":"4.1.1"},"q":"Yo'l qismi boshidagi 4.1.1 belgisi eng yaqin chorrahagacha amal qiladi va o'ngdagi hovlilarga burilishni taqiqlamaydi.","e":"Tuzoq: \"faqat to'g'riga\" o'ng tomondagi hovliga kirishni to'smaydi."},{"id":28,"m":"belgilar","s":"Chorraha oldida rasmdagi belgi o'rnatilgan. Yo'nalishli avtobusning qatnov yo'nalishi bu chorrahadan to'g'riga davom etadi. Avtobus to'g'riga harakatlanishi mumkinmi?","v":["Mumkin emas, barcha transport vositalari faqat o'ngga burilishi shart","Faqat yo'lovchilarsiz harakatlanayotgan bo'lsa mumkin","Mumkin, chunki bu belgi yo'nalishli transport vositalariga tatbiq etilmaydi"],"j":2,"i":"4.1.1–4.1.6 belgilarining talablari yo'nalishli transport vositalariga tatbiq etilmaydi (1-ilova, 4-bo'lim).","r":{"b":"4.1.2"},"q":"4.1.1–4.1.6 belgilarining talablari yo'nalishli transport vositalariga tatbiq etilmaydi.","e":"Avtobus o'z yo'nalishi bo'ylab yuradi – yo'nalish strelkalari unga buyruq emas."},{"id":29,"m":"belgilar","s":"To'siq oldida rasmdagi belgi o'rnatilgan. To'siqni qanday aylanib o'tish mumkin?","v":["Faqat o'ng tomondan","Faqat chap tomondan","Istalgan tomondan","Aylanib o'tish taqiqlanadi"],"j":1,"i":"Bu belgi to'siqni faqat chap tomondan aylanib o'tishga ruxsat beradi. O'ngdan aylanib o'tish 4.2.2, ikkala tomondan aylanib o'tish 4.2.3 belgisi bilan ko'rsatiladi (1-ilova, 4.2.1-belgi).","r":{"b":"4.2.1"},"q":"4.2.1 to'siqni faqat chapdan, 4.2.2 faqat o'ngdan, 4.2.3 esa ikkala tomondan aylanib o'tishga ruxsat beradi.","e":"Oxirgi raqam: 1 – chap, 2 – o'ng, 3 – ikkalasi (1 + 2)."},{"id":30,"m":"belgilar","s":"Rasmdagi belgi o'rnatilgan yo'lda quyidagilardan qaysi birining harakatlanishi taqiqlanadi?","v":["Ruxsat etilgan to'liq vazni 6 t bo'lgan yuk avtomobili","Avtobus","Mototsikl","Ruxsat etilgan to'liq vazni 3 t bo'lgan yuk avtomobili"],"j":0,"i":"\"Yengil avtomobillar harakati\" belgisi faqat yengil avtomobillar, avtobuslar, mototsikllar, mopedlar, skuterlar, kichik hajmdagi mototransport, yo'nalishli transport vositalari va ruxsat etilgan to'liq vazni 3,5 t dan oshmaydigan yuk avtomobillariga ruxsat beradi (1-ilova, 4.4-belgi).","r":{"b":"4.4"},"q":"4.4 belgili yo'lda yengil avtomobil, avtobus, mototsikl, yo'nalishli transport va 3,5 t gacha yuk avtomobillari yura oladi.","e":"Tuzoq: belgi \"yengil\" deydi, lekin avtobus ham o'tadi – yo'l og'ir yuk mashinasiga yopiq."},{"id":31,"m":"belgilar","s":"Rasmdagi belgi nimani bildiradi?","v":["Tezlik soatiga 40 km dan oshmasligi kerak","Tavsiya etilgan tezlik – soatiga 40 km","Tezlik soatiga 40 km bilan cheklangan hududning oxiri","Faqat soatiga 40 km yoki undan yuqori tezlikda harakatlanishga ruxsat etiladi"],"j":3,"i":"\"Eng kam tezlik\" belgisi faqat belgida ko'rsatilgan yoki undan yuqori tezlikda harakatlanishga ruxsat beradi (1-ilova, 4.7-belgi).","r":{"b":"4.7"},"q":"4.7 \"Eng kam tezlik\" belgisi faqat belgida ko'rsatilgan yoki undan yuqori tezlikda harakatlanishga ruxsat beradi.","e":"Juftlik: 3.24 – ship (yuqoridan cheklaydi), 4.7 – pol (pastdan cheklaydi)."},{"id":32,"m":"belgilar","s":"Rasmdagi belgi bilan boshlanadigan yo'lda quyidagilardan qaysi biri taqiqlanadi?","v":["Chetki o'ng qatorda harakatlanish","Orqaga harakatlanish","6.11 \"Dam olish joyi\" belgisi bilan belgilangan maydonchada to'xtash","Yaqinni yorituvchi faralar yoqilgan holda harakatlanish"],"j":1,"i":"\"Avtomagistral\" belgisi bilan belgilangan yo'lda avtomagistral qoidalari amal qiladi: jumladan orqaga harakatlanish taqiqlanadi; to'xtash esa faqat 5.15 yoki 6.11 belgili maydonchalarda mumkin (1-ilova, 5.1-belgi; YHQ, 121-band).","r":{"b":"5.1"},"q":"5.1 \"Avtomagistral\" belgili yo'lda orqaga harakatlanish taqiqlanadi, to'xtash faqat 5.15 yoki 6.11 belgili maydonchalarda mumkin.","e":"Magistralda faqat oldinga: orqaga yurish, qayrilish va o'quv haydash yo'q."},{"id":33,"m":"belgilar","s":"Aholi punktida rasmdagi belgi o'rnatilgan yo'lda yengil avtomobilni qatnov qismining chap chetida to'xtatish mumkinmi? Boshqa taqiqlovchi belgi va chiziqlar yo'q.","v":["Mumkin: aholi punktlarida bunday yo'lda chap tomonda ham to'xtash va to'xtab turish mumkin","Mumkin emas, to'xtash faqat o'ng tomonda ruxsat etiladi","Faqat yo'lovchi tushirish uchun mumkin"],"j":0,"i":"Rasmdagi belgi – \"Bir tomonlama harakatli yo'l\". Aholi punktlarida bir tomonlama harakatli yo'llarda qatnov qismining chap tomonida ham to'xtash va to'xtab turishga ruxsat etiladi (YHQ, 88-band; 1-ilova, 5.5-belgi).","r":{"b":"5.5"},"q":"Aholi punktida bir tomonlama harakatli yo'lda qatnov qismining chap tomonida ham to'xtash va to'xtab turish mumkin.","e":"Bir tomonlama yo'lda ro'parada hech kim yo'q – aholi punktida chap chet ham ochiq."},{"id":34,"m":"belgilar","s":"Rasmdagi belgi o'rnatilgan joyda qaysi manyovr taqiqlanadi?","v":["Qayrilib olish","O'ngga burilish","Qayta tizilish","Chapga burilish"],"j":3,"i":"\"Qayrilib olish joyi\" belgisi qayrilib olish mumkin bo'lgan joyni ko'rsatadi; bu joyda chapga burilish taqiqlanadi (1-ilova, 5.11.1-belgi).","r":{"b":"5.11.1"},"q":"5.11.1 \"Qayrilib olish joyi\" belgisi o'rnatilgan joyda qayrilib olish mumkin, chapga burilish esa taqiqlanadi.","e":"Tuzoq: \"qayrilish joyi\" – faqat qayrilish uchun; chapga burilish bu yerda yo'q."},{"id":35,"m":"belgilar","s":"Rasmdagi belgi o'rnatilgan joyda bekat maydonchasi va 1.17 chizig'i yo'q. Haydovchi yo'lovchi chiqarish yoki tushirish uchun emas, tanishini kutish uchun to'xtamoqchi. Qayerda to'xtash taqiqlanadi?","v":["Faqat belgidan keyin 5 m dan kam masofada","Belgidan oldin va keyin 15 m dan kam masofada","Belgidan oldin va keyin 50 m dan kam masofada"],"j":1,"i":"Bekat maydonchasi va 1.17 chizig'i bo'lmasa, yo'nalishli transport vositalari to'xtash joyi belgisidan oldin va keyin 15 m dan kam masofada to'xtash taqiqlanadi; yo'nalishli transportga xalaqit bermasa, faqat yo'lovchi chiqarish-tushirish uchun to'xtash mumkin (YHQ, 91-band; 1-ilova, 5.12-belgi).","r":{"b":"5.12"},"q":"Bekat maydonchasi va 1.17 chizig'i bo'lmasa, bekat belgisidan oldin va keyin 15 m dan kam masofada to'xtash taqiqlanadi.","e":"Bekat atrofida \"15 + 15\": avtobusga joy qoldiring; xalaqit bermasa, faqat yo'lovchi chiqarish-tushirish."},{"id":36,"m":"belgilar","s":"Rasmdagi belgi nimani bildiradi va qayergacha amal qiladi?","v":["Eng kam tezlik; aholi punktining oxirigacha","Yuqori tezlik chegarasi; 5.22 belgisigacha","Tavsiya etilgan tezlik; aholi punktining oxirigacha","Tavsiya etilgan tezlik; eng yaqin chorrahagacha"],"j":3,"i":"\"Tavsiya etilgan tezlik\" belgisi yo'lning shu qismida tavsiya etilgan tezlikni bildiradi va eng yaqin chorrahagacha amal qiladi; ogohlantiruvchi belgi bilan qo'llansa, xavfli qismning uzunligigacha (1-ilova, 5.18-belgi).","r":{"b":"5.18"},"q":"5.18 \"Tavsiya etilgan tezlik\" belgisi eng yaqin chorrahagacha amal qiladi.","e":"Tuzoq: tavsiya etilgan tezlikni 3.24 cheklovi bilan adashtirmang; 5.18 chorrahagacha amal qiladi."},{"id":37,"m":"belgilar","s":"Shaharga kiraverishda rasmdagi belgi o'rnatilgan; undan keyin aholi punktida harakatlanish qoidalari amal qiladi. Boshqa yo'l belgilari yo'q. Yengil avtomobil qanday eng yuqori tezlikda harakatlanishi mumkin?","v":["50 km/soat","60 km/soat","70 km/soat","100 km/soat"],"j":1,"i":"Belgi Toshkent shahri boshlanganini bildiradi. Toshkent va Nukus shaharlarida, viloyat va tuman markazlarida hamda shaharlar hududida eng yuqori tezlik 70 emas, 60 km/soat (1-ilova, 5.22-belgi; YHQ, 78-band).","r":{"b":"5.22"},"q":"Toshkent va Nukusda, viloyat va tuman markazlarida, shaharlar hududida eng yuqori tezlik – 60, boshqa aholi punktlarida – 70 km/soat.","e":"Tuzoq: shaharlarda 70 emas, 60 km/soat; 70 – boshqa aholi punktlari uchun."},{"id":38,"m":"belgilar","s":"Rasmdagi belgi bilan belgilangan hududda quyidagilardan qaysi biri taqiqlanadi?","v":["Velosipedda harakatlanish","Transport vositasini boshqarishni o'rgatish (o'quv haydash)","Yo'lovchini tushirish uchun qisqa to'xtash","Soatiga 15 km tezlikda harakatlanish"],"j":1,"i":"\"Turar joy dahasi\" belgisi bilan belgilangan hududda tezlik 20 km/soatdan oshmasligi kerak; haydashni o'rgatish, dvigatel ishlab turgan holda to'xtab turish va 3,5 t dan og'ir yuk avtomobillarini maxsus joydan tashqarida qoldirish taqiqlanadi (YHQ, 78, 124-bandlar).","r":{"b":"5.38"},"q":"Turar joy dahasida tezlik 20 km/soatdan oshmaydi; haydashni o'rgatish va dvigatel ishlab turgan holda to'xtab turish taqiqlanadi.","e":"Hovli – bolalar maydoni: 20 dan tez yurma, o'quv haydash qilma, motorni o'chir."},{"id":39,"m":"belgilar","s":"Rasmdagi belgi nimani bildiradi?","v":["Avtomobillarga texnik xizmat ko'rsatish joyi","Ta'mirlash ishlari olib borilmoqda","Avtomobillarga yonilg'i quyish shoxobchasi","Telefon"],"j":0,"i":"Servis belgilari tegishli obyektlar qayerda joylashganini bildiradi; bu belgi – \"Avtomobillarga texnik xizmat ko'rsatish joyi\". Ta'mirlash ishlari ogohlantiruvchi 1.23 belgisi bilan ko'rsatiladi (1-ilova, 6.4-belgi).","r":{"b":"6.4"},"q":"Servis belgilari obyekt joyini bildiradi: 6.4 – texnik xizmat ko'rsatish joyi; ta'mirlash ishlari 1.23 belgisi bilan ko'rsatiladi.","e":"Tuzoq: 6.4 – mashinani tuzatish joyi, 1.23 – yo'lni tuzatish (xavf)."},{"id":40,"m":"belgilar","s":"Rasmdagi belgilar o'rnatilgan joyda to'xtab turish qachon taqiqlanadi?","v":["Har kuni soat 8:00 dan 18:00 gacha","Ish kunlari kun bo'yi","Ish kunlari soat 8:00 dan 18:00 gacha","Dam olish kunlari soat 8:00 dan 18:00 gacha"],"j":2,"i":"Qo'shimcha axborot belgilari asosiy belgining ta'sirini cheklaydi: 7.5.2 \"Ish kunlari\" belgisi kunlarni, 7.5.4 esa amal qilish vaqtini ko'rsatadi. Demak, to'xtab turish faqat ish kunlari 8:00–18:00 da taqiqlanadi (1-ilova, 7-bo'lim).","r":{"b":["3.28","7.5.2","7.5.4"]},"q":"Qo'shimcha belgilar asosiy belgi ta'sirini cheklaydi: 7.5.2 kunlarni, 7.5.4 vaqtni ko'rsatadi va ikkalasi birga amal qiladi.","e":"Kun VA soat: ikkala plastinka sharti bir vaqtda bajarilgandagina taqiq ishlaydi."},{"id":41,"m":"chiziq","s":"Ikki tasmali yo'lda qarama-qarshi oqimlar sidirg'a chiziq (1.1) bilan ajratilgan. Oldingizda soatiga 30 km tezlikda traktor ketmoqda, qarama-qarshi tasma bo'sh. Uni quvib o'tish uchun bu chiziqni bosib o'tish mumkinmi?","v":["Mumkin, chunki traktor soatiga 40 km dan sekin ketmoqda","Mumkin emas, 1.1 chizig'ini bosib o'tish taqiqlanadi","Mumkin, agar oldindan tovushli ishora berilsa"],"j":1,"i":"1.1 va 1.3 chiziqlarini bosib o'tish taqiqlanadi (qatnov qismi chetini bildiruvchi 1.1 bundan mustasno). Sekin yakka vositani quvib o'tishga ruxsat faqat 3.20 belgisi ta'siriga tegishli (2-ilova, 1.1-chiziq).","q":"1.1 sidirg'a chiziqni bosib o'tish taqiqlanadi (qatnov qismi chetini bildiruvchi 1.1 bundan mustasno).","e":"Sidirg'a chiziq – devor: sekin traktor uchun ham uni kesib o'tmaysiz."},{"id":42,"m":"chiziq","s":"Qatnov qismida qarama-qarshi oqimlarni ajratuvchi uzuq chiziq (1.5) chizilgan, yo'l chetida esa rasmdagi belgi o'rnatilgan. Soatiga 60 km tezlikda ketayotgan yengil avtomobilni quvib o'tish mumkinmi?","v":["Mumkin, chunki uzuq chiziqni bosib o'tishga ruxsat bor","Mumkin, agar qarama-qarshi tasma bo'sh bo'lsa","Mumkin emas: belgi va chiziq zid kelsa, belgiga amal qilinadi"],"j":2,"i":"Yo'l belgilari va yotiq chiziqlar bir-biriga zid kelsa, haydovchilar belgilarga amal qiladi. 3.20 belgisi ta'sir oralig'ida soatiga 40 km dan tez ketayotgan vositani quvib o'tish taqiqlanadi (2-ilova; 1-ilova, 3.20-belgi).","r":{"b":"3.20"},"q":"Yo'l belgilari va yotiq chiziqlar bir-biriga zid kelsa, haydovchi belgilarga amal qiladi.","e":"Belgi chiziqdan ustun: zid kelsa, belgi g'olib."},{"id":43,"m":"chiziq","s":"Uzuq chiziqning bo'laklari uzayib, ular orasidagi oraliq qisqardi (bo'lak uzunligi oraliqdan uch barobar katta). Bu chiziq (1.6) nimadan ogohlantiradi?","v":["Oldinda piyodalar o'tish joyi borligidan","Oldinda to'xtash chizig'i borligidan","Avtomagistral tugayotganidan","1.1 yoki 1.11 chizig'iga yaqinlashayotganingizdan"],"j":3,"i":"1.6 \"Yaqinlashish chizig'i\" qarama-qarshi yoki bir yo'nalishdagi oqimlarni ajratuvchi 1.1 yoki 1.11 chizig'iga yaqinlashayotganlik haqida ogohlantiradi (2-ilova, 1.6-chiziq).","q":"1.6 yaqinlashish chizig'i (bo'laklari oraliqdan uzun) 1.1 yoki 1.11 chizig'iga yaqinlashayotganlikni bildiradi.","e":"Bo'laklar uzayadi, oraliqlar qisqaradi – oldinda sidirg'a chiziq."},{"id":44,"m":"chiziq","s":"Yo'lda yonma-yon sidirg'a va uzuq chiziqdan iborat 1.11 chizig'i bor, sizga yaqin tomonida sidirg'a chiziq. Uni qachon bosib o'tishingiz mumkin?","v":["Faqat quvib o'tish yoki aylanib o'tishni tugatayotganda","Istalgan vaqtda, qarama-qarshi tasma bo'sh bo'lsa","Hech qachon","Faqat chapga burilish uchun"],"j":0,"i":"1.11 chizig'ini uzuq chiziq tomonidan bosib o'tish mumkin, sidirg'a chiziq tomonidan esa faqat quvib o'tish yoki aylanib o'tishni tugatayotganda (2-ilova, 1.11-chiziq).","q":"1.11 chizig'ini uzuq chiziq tomonidan bosib o'tish mumkin, sidirg'a tomondan faqat quvib yoki aylanib o'tishni tugatayotganda.","e":"Sidirg'a tomonda – faqat \"uyga qaytish\": quvib o'tishdan keyin o'z tasmangizga."},{"id":45,"m":"chiziq","s":"Keng sidirg'a chiziq (1.2) nimani bildiradi?","v":["To'rt va undan ortiq tasmali yo'lda qarama-qarshi oqimlarni ajratishni","Svetofor oldida to'xtash joyini","Avtomagistralda qatnov qismining chetini"],"j":2,"i":"1.2 chizig'i avtomagistrallarda qatnov qismining chetini bildiradi; uni istalgan tomondan bosib o'tish mumkin (2-ilova, 1.2-chiziq).","q":"1.2 keng sidirg'a chiziq avtomagistralda qatnov qismi chetini bildiradi; uni istalgan tomondan bosib o'tish mumkin.","e":"Tuzoq: keng chiziq – \"qalin devor\" emas, avtomagistral cheti; 1.2 ni bosib o'tish mumkin."},{"id":46,"m":"chiziq","s":"Qo'sh sidirg'a chiziq (1.3) qanday yo'llarda qarama-qarshi oqimlarni ajratadi va uni bosib o'tish mumkinmi?","v":["Ikki tasmali yo'llarda; quvib o'tish uchun bosib o'tish mumkin","To'rt va undan ortiq tasmali yo'llarda; bosib o'tish taqiqlanadi","Uch tasmali yo'llarda; faqat chapga burilish uchun bosib o'tish mumkin","Bir tomonlama yo'llarda; istalgan tomondan bosib o'tish mumkin"],"j":1,"i":"1.3 chizig'i to'rt va undan ortiq tasmali yo'llarda qarama-qarshi oqimlarni ajratadi. 1.1 va 1.3 chiziqlarini bosib o'tish taqiqlanadi (2-ilova, 1.3-chiziq).","q":"1.3 qo'sh sidirg'a chiziq to'rt va undan ortiq tasmali yo'llarda qarama-qarshi oqimlarni ajratadi; uni bosib o'tish taqiqlanadi.","e":"Qo'sh devor – katta yo'l: 4 va undan ortiq tasma, kesib o'tish yo'q."},{"id":47,"m":"chiziq","s":"To'xtash chizig'i (1.12) qanday hollarda haydovchi to'xtashi kerak bo'lgan joyni ko'rsatadi?","v":["Har doim, svetofor ishorasidan qat'i nazar","Faqat piyodalar o'tayotganda","Faqat 2.4 belgisi bo'lganda","2.5 belgisi bo'lganda yoki svetofor (tartibga soluvchi) taqiqlovchi ishora berganda"],"j":3,"i":"1.12 (to'xtash chizig'i) 2.5 belgisi bo'lganda yoki svetofor (tartibga soluvchi) taqiqlovchi ishora berganda haydovchi to'xtashi kerak bo'lgan joyni ko'rsatadi (2-ilova, 1.12-chiziq).","q":"1.12 to'xtash chizig'i 2.5 belgisi bo'lganda yoki svetofor (tartibga soluvchi) taqiqlovchi ishora berganda to'xtash joyini ko'rsatadi.","e":"Tuzoq: yashil yonib turgan va 2.5 yo'q bo'lsa, to'xtash chizig'ida to'xtash shart emas."},{"id":48,"m":"chiziq","s":"Oq rangli \"zebra\" (1.14.1) bilan belgilangan piyodalar o'tish joyi oldida qayerda to'xtash taqiqlanadi?","v":["O'tish joyida va undan oldin 10 m dan kam masofada","Faqat \"zebra\"ning ustida","O'tish joyidan oldin va keyin 30 m dan kam masofada","O'tish joyidan oldin 5 m dan kam masofada"],"j":0,"i":"1.14.1 chizig'i piyodalar o'tish joyini belgilaydi. Piyodalar o'tish joylarida va ulardan oldin 10 m dan kam masofada to'xtash taqiqlanadi (2-ilova, 1.14.1-chiziq; YHQ, 91-band).","q":"Piyodalar o'tish joyida va undan oldin 10 m dan kam masofada to'xtash taqiqlanadi.","e":"\"Zebra\" oldidagi 10 m – piyodani ko'rish uchun bo'sh oyna."},{"id":49,"m":"chiziq","s":"Qaysi yotiq yo'l chiziqlari sariq rangda bo'ladi?","v":["Qarama-qarshi oqimlarni ajratuvchi barcha chiziqlar","To'xtash chizig'i (1.12)","To'xtash taqiqlangan (1.4), to'xtab turish taqiqlangan (1.10) joylarni hamda bekat va taksilar to'xtab turish joylarini (1.17) bildiruvchi chiziqlar","Avtomagistralda qatnov qismi chetini bildiruvchi chiziq"],"j":2,"i":"Yotiq chiziqlar oq rangda bo'ladi, faqat 1.4, 1.10 va 1.17 chiziqlari sariq rangda bo'ladi (2-ilova).","q":"Yotiq chiziqlar oq rangda bo'ladi, faqat 1.4, 1.10 va 1.17 chiziqlari sariq rangda.","e":"Sariq – to'xtash mavzusi: 1.4 to'xtash yo'q, 1.10 to'xtab turish yo'q, 1.17 bekat va taksi joyi."},{"id":50,"m":"chiziq","s":"Ta'mirlanayotgan yo'l qismida vaqtinchalik yo'l chiziqlari doimiy chiziqlarga zid kelmoqda. Haydovchi qaysi chiziqlarga amal qilishi kerak?","v":["Doimiy chiziqlarga","Vaqtinchalik chiziqlarga","Hech biriga, faqat tezlikni kamaytirish kifoya"],"j":1,"i":"Vaqtinchalik va doimiy yo'l chiziqlari bir-biriga zid kelsa, haydovchilar vaqtinchalik chiziqlarga amal qilishi kerak (2-ilova).","q":"Vaqtinchalik va doimiy yo'l chiziqlari zid kelsa, haydovchi vaqtinchalik chiziqlarga amal qiladi.","e":"Yangi chizilgan – yangi buyruq: ta'mirda vaqtinchalik chiziq doimiysidan ustun."},{"id":51,"m":"yoritish","s":"Sutkaning qorong'i vaqtida yoritilmagan yo'lda uzoqni yorituvchi fara chiroqlari bilan ketyapsiz. Qarama-qarshi yo'nalishdan avtomobil kelmoqda. Unga kamida qancha masofa qolganda yaqinni yorituvchi fara chiroqlariga o'tish kerak?","v":["50 m","100 m","150 m","300 m"],"j":2,"i":"Qarama-qarshi yo'nalishdagi transport vositasiga kamida 150 m qolganda yaqinni yorituvchi faraga o'tiladi; u haydovchi faralarini o'chirib-yoqib ishora bersa, undan ham uzoqroq masofada (YHQ, 135-band).","q":"Uzoqni yorituvchi faradan yaqinni yorituvchiga qarama-qarshi transport vositasiga kamida 150 m qolganda o'tiladi.","e":"Tuzoq: 300 m – ko'rinish chegarasi, 150 m – faralarni almashtirish masofasi."},{"id":52,"m":"yoritish","s":"Sutkaning yorug' vaqtida quyidagi qaysi holatda yaqinni yorituvchi fara chiroqlari yoqilishi shart?","v":["Quruq, ochiq havoda shahar ko'chasida yengil avtomobilda ketayotganda","Boshqa avtomobilni egiluvchan ulagich bilan shatakka olib ketayotganda (shatakka olgan avtomobilda)","Aholi punktidan tashqarida bo'sh yuk avtomobilida ketayotganda","Yo'l yoqasida to'xtab turganda"],"j":1,"i":"Kunduzi yaqinni yorituvchi fara shatakka olib ketayotgan vositada, tashkiliy jamlanmada, yo'lovchi tashiyotgan avtobusda, kuchli yog'ingarchilikda va boshqa sanab o'tilgan hollarda yoqiladi; oddiy yengil avtomobil uchun bu majburiy emas (YHQ, 138-band).","q":"Kunduzi yaqinni yorituvchi fara shatakka olgan vositada, tashkiliy jamlanmada, yo'lovchili avtobusda va kuchli yog'ingarchilikda yoqiladi.","e":"Tuzoq: oddiy yengil avtomobilga kunduzi fara yoqish majburiy emas."},{"id":53,"m":"yoritish","s":"Kechasi qarama-qarshi kelayotgan avtomobil faralari ko'zingizni qamashtirdi. Qoidalarga ko'ra nima qilishingiz kerak?","v":["Uzoqni yorituvchi faralarni yoqib, javob ishorasi berish","Chapdagi bo'sh tasmaga o'tib, tezlikni saqlagan holda davom etish","Avariya ishorasini yoqish, harakatlanish bo'lagini o'zgartirmasdan tezlikni kamaytirish va to'xtash","Tovushli ishora berib, tezlikni oshirish"],"j":2,"i":"Ko'zi qamashgan haydovchi avariya ishorasini yoqishi, harakatlanish bo'lagini o'zgartirmasdan tezlikni kamaytirishi va to'xtashi kerak (YHQ, 135-band; 50-band).","q":"Ko'zi qamashgan haydovchi avariya ishorasini yoqib, harakatlanish bo'lagini o'zgartirmasdan tezlikni kamaytirishi va to'xtashi kerak.","e":"Ko'z qamashdi: avariya chirog'i – tasma o'zgarmaydi – sekinla – to'xta."},{"id":54,"m":"yoritish","s":"Sutkaning qorong'i vaqtida yo'lning yoritilmagan qismida avtomobilni yo'l chetida to'xtatib qo'ydingiz. Unda qaysi chiroqlar yoqilgan bo'lishi kerak?","v":["Gabarit fara chiroqlari","Hech qanday chiroq yoqish shart emas","Faqat uzoqni yorituvchi fara chiroqlari","Faqat salon chirog'i"],"j":0,"i":"Qorong'ida yo'lning yoritilmagan qismida, shuningdek yetarlicha ko'rinmaydigan sharoitda to'xtagan yoki to'xtab turgan transport vositasida gabarit fara chiroqlari yoqilgan bo'lishi kerak (YHQ, 136-band).","q":"Qorong'ida yo'lning yoritilmagan qismida to'xtagan yoki to'xtab turgan transport vositasida gabarit chiroqlar yoqiladi.","e":"Gabarit – \"men shu yerdaman\" chirog'i: turgan mashinani qorong'ida ko'rsatadi."},{"id":55,"m":"yoritish","s":"Tumanga qarshi orqa fara chiroqlarini qachon yoqish mumkin?","v":["Sutkaning qorong'i vaqtida har doim","Yo'l yoritilmagan bo'lsa, ob-havodan qat'i nazar","Orqadan kelayotgan avtomobil juda yaqin yursa","Faqat yetarlicha ko'rinmaydigan sharoitda (masalan, tuman tufayli ko'rinish 300 m dan kam bo'lganda)"],"j":3,"i":"Tumanga qarshi orqa fara chiroqlari faqat yetarlicha ko'rinmaydigan sharoitda qo'llanadi va ularni to'xtash chiroqlariga (stop-signalga) ulash taqiqlanadi (YHQ, 140-band; 6-band).","q":"Tumanga qarshi orqa chiroq faqat yetarlicha ko'rinmaydigan sharoitda yoqiladi va to'xtash chiroqlariga ulanmaydi.","e":"Tuzoq: qorong'ilikning o'zi sabab emas – faqat ko'rinish 300 m dan kam bo'lganda yoqiladi."},{"id":56,"m":"yoritish","s":"Quyidagi qaysi holatda avariya (xavf-xatar) ishorasini yoqish shart?","v":["Quvib o'tishni boshlashdan oldin","\"Bolalarni tashish\" taniqlik belgisi bor avtobusga bolalar chiqayotganda yoki undan tushayotganda","Yengil avtomobilda yo'lovchini tushirish uchun ruxsat etilgan joyda to'xtaganda","Tunnelga kirishda"],"j":1,"i":"Avariya ishorasi YTH sodir bo'lganda, to'xtash taqiqlangan joyda majburiy to'xtaganda, ko'z qamashganda, shatakka olishda (shatakka olingan vositada) va \"Bolalarni tashish\" belgili vositaga bolalar chiqayotganda yoki tushayotganda yoqiladi (YHQ, 50-band).","q":"\"Bolalarni tashish\" belgili transport vositasiga bolalar chiqayotganda yoki undan tushayotganda avariya ishorasi yoqiladi.","e":"Bolalar chiqyapti – miltillat: avariya chirog'i atrofdagilarga \"sekinla\" deydi."},{"id":57,"m":"yoritish","s":"Avariya sababli to'xtash belgisi transport vositasidan qanday masofada o'rnatilishi kerak?","v":["Har qanday yo'lda kamida 10 m","Aholi punktida kamida 30 m, aholi punktidan tashqarida kamida 50 m","Aholi punktida kamida 5 m, aholi punktidan tashqarida kamida 15 m","Aholi punktida kamida 15 m, aholi punktidan tashqarida kamida 30 m"],"j":3,"i":"Belgi boshqa haydovchilarni o'z vaqtida ogohlantiradigan masofada qo'yiladi: aholi punktlarida transport vositasidan kamida 15 m, aholi punktlaridan tashqarida kamida 30 m (YHQ, 51-band).","q":"Avariya sababli to'xtash belgisi aholi punktida transport vositasidan kamida 15 m, tashqarida kamida 30 m masofaga qo'yiladi.","e":"Tashqarida ikki baravar: 15 m o'rniga 30 m."},{"id":58,"m":"yoritish","s":"Aholi punktida tovushli ishoradan qaysi holatda foydalanish mumkin?","v":["Oldingi avtomobilni quvib o'tishdan oldin ogohlantirish uchun","Svetoforda yashil yonganda oldingi haydovchi joyidan qo'zg'almasa","Yo'l-transport hodisasining oldini olish uchun zarur bo'lganda","Piyodani o'tish joyidan tezroq o'tishga undash uchun"],"j":2,"i":"Tovushli ishora faqat aholi punktidan tashqarida quvib o'tishdan ogohlantirish va zarur hollarda YTHning oldini olish uchun beriladi; aholi punktida faqat ikkinchisi qoladi, boshqa hollarda taqiqlanadi (YHQ, 48-band).","q":"Tovushli ishora faqat YTHning oldini olish uchun va aholi punktidan tashqarida quvib o'tishdan ogohlantirish uchun beriladi.","e":"Shaharda signal – faqat xavf uchun: \"bib\" bilan shoshtirish taqiqlanadi."},{"id":59,"m":"yoritish","s":"Ko'k va qizil rangli yalt-yalt etuvchi mayoqchasi va maxsus tovushli ishorasi yoqilgan avtomobil orqadan yaqinlashmoqda. Siz nima qilishingiz shart?","v":["Unga yo'l berishingiz shart, uni quvib o'tish taqiqlanadi","Faqat chorrahada yo'l berasiz, boshqa joyda harakatni davom ettirasiz","Tezlikni oshirib, uning oldida ketishingiz kerak","Agar u sizdan sekin ketsa, uni quvib o'tishingiz mumkin"],"j":0,"i":"Mayoqchasi va maxsus tovushli ishorasi yoqilgan tezkor va maxsus xizmat transport vositasiga, shuningdek uning kuzatuvidagi vositalarga yo'l berish shart; bunday vositalarni quvib o'tish taqiqlanadi (YHQ, 26-band).","q":"Ko'k yoki qizil mayoqchasi va maxsus tovushli ishorasi yoqilgan transport vositasiga yo'l beriladi, uni quvib o'tish taqiqlanadi.","e":"Ikki shart birga: mayoqcha VA sirena – yo'l berasiz, quvib o'tmaysiz."},{"id":60,"m":"yoritish","s":"Qaysi holatda transport vositasida zarg'aldoq yoki sariq rangli yalt-yalt etuvchi mayoqcha yoqilgan bo'lishi kerak?","v":["Tez tibbiy yordam avtomobili chaqiruvga shoshilayotganda","Yo'lda ta'mirlash yoki tozalash ishlari olib borilayotganda","Taksi yo'lovchi kutib turganda","Yengil avtomobil kechasi yo'l chetida to'xtab turganda"],"j":1,"i":"Zarg'aldoq yoki sariq mayoqcha yo'lda qurilish, ta'mirlash, tozalash ishlarida, nosoz vositalarni ortib tashishda, katta o'lchamli yuk tashiyotgan vositalarni kuzatib borishda va xavfli yuklarni tashishda yoqiladi; tezkor va maxsus xizmatlar ko'k yoki qizil mayoqchadan foydalanadi (YHQ, 28-band; 25-band).","q":"Zarg'aldoq yoki sariq mayoqcha yo'l ishlari, xavfli yuk tashish kabi hollarda yoqiladi; u imtiyoz bermaydi, faqat ogohlantiradi.","e":"Sariq – \"ehtiyot bo'l\", ko'k yoki qizil – \"yo'l ber\"."},{"id":61,"m":"tashish","s":"Avtomobilni egiluvchan ulagich (tros) bilan shatakka olishda shatakka olgan va shatakka olingan transport vositalari orasidagi masofa qancha bo'lishi kerak?","v":["4–6 m","1–3 m","Ko'pi bilan 4 m","6–10 m"],"j":0,"i":"Egiluvchan ulagich bilan shatakka olishda vositalar orasidagi masofa 4–6 m oralig'ida bo'lishi kerak; ulagich ogohlantiruvchi belgilar bilan ko'rsatiladi (YHQ, 144-band; 177-band).","q":"Egiluvchan ulagich bilan shatakka olishda transport vositalari orasidagi masofa 4–6 m bo'lishi kerak.","e":"Juftlik: tros – 4–6 m, qattiq ulagich – ko'pi bilan 4 m."},{"id":62,"m":"tashish","s":"Qattiq ulagich bilan shatakka olishda transport vositalari orasidagi masofa qancha bo'lishi kerak?","v":["Kamida 4 m","4–6 m","Ko'pi bilan 6 m","Ko'pi bilan 4 m"],"j":3,"i":"Qattiq ulagich bilan shatakka olishda vositalar orasidagi masofa 4 m dan ko'p bo'lmasligi kerak; 4–6 m egiluvchan ulagich uchun (YHQ, 144-band).","q":"Qattiq ulagich bilan shatakka olishda transport vositalari orasidagi masofa 4 m dan oshmasligi kerak.","e":"Tuzoq: 4–6 m – tros uchun; qattiq ulagich yaqinroq: ko'pi bilan 4 m."},{"id":63,"m":"tashish","s":"Boshqa mexanik transport vositasini shatakka olib ketayotgan avtomobil har qanday yo'lda qanday tezlikdan oshmasdan harakatlanishi kerak?","v":["40 km/soat","50 km/soat","60 km/soat","70 km/soat"],"j":1,"i":"Mexanik transport vositasini shatakka olgan transport vositasi har qanday yo'lda 50 km/soatdan oshmaydigan tezlikda harakatlanadi (YHQ, 80-band).","q":"Mexanik transport vositasini shatakka olgan transport vositasi har qanday yo'lda 50 km/soatdan oshmasdan harakatlanadi.","e":"Shatakda shahar ham, trassa ham bir xil – 50 km/soat."},{"id":64,"m":"tashish","s":"Qaysi holatda egiluvchan ulagich bilan shatakka olish taqiqlanadi?","v":["Sutkaning qorong'i vaqtida","Shatakka olingan avtomobilning dvigateli ishlamasa","Yo'l yaxmalak yoki sirpanchiq bo'lsa","Aholi punktidan tashqarida"],"j":2,"i":"Yo'l yaxmalak yoki sirpanchiq bo'lgan hollarda egiluvchan ulagich bilan shatakka olish taqiqlanadi (YHQ, 145-band).","q":"Yo'l yaxmalak yoki sirpanchiq bo'lsa, egiluvchan ulagich bilan shatakka olish taqiqlanadi.","e":"Muz + tros = taqiq: sirpanchiq yo'lda tros bilan shatakka olinmaydi."},{"id":65,"m":"tashish","s":"Avtobus egiluvchan ulagich bilan shatakka olinmoqda. Shatakka olingan avtobusda kim bo'lishi mumkin?","v":["Haydovchi va o'rindiqlarda o'tirgan yo'lovchilar","Hech kim, avtobus haydovchisiz shatakka olinadi","Faqat rulni boshqaradigan haydovchi","Haydovchi va 8 nafargacha yo'lovchi"],"j":2,"i":"Shatakka olingan vositaning rulida haydovchi bo'lishi shart (142-band), qattiq yoki egiluvchan ulagich bilan shatakka olingan avtobusda esa odam tashish taqiqlanadi (YHQ, 143-band).","q":"Qattiq yoki egiluvchan ulagich bilan shatakka olingan avtobus, trolleybus va yuk avtomobili yukxonasida odam tashish taqiqlanadi.","e":"Shatakdagi avtobus – bo'sh avtobus: ichida faqat rul ortidagi haydovchi."},{"id":66,"m":"tashish","s":"Odam tashish uchun jihozlangan yuk avtomobilining yukxonasida bolalarni tashish mumkinmi?","v":["Taqiqlanadi","Mumkin, agar ularni katta yoshli kishi kuzatib borsa","Mumkin, agar tezlik 60 km/soatdan oshmasa","Faqat aholi punkti ichida mumkin"],"j":0,"i":"Bolalarni yuk avtomobillarining yukxonasida tashish taqiqlanadi, yukxona odam tashishga jihozlangan bo'lsa ham (YHQ, 159-band).","q":"Bolalarni yuk avtomobilining yukxonasida tashish taqiqlanadi, yukxona odam tashishga jihozlangan bo'lsa ham.","e":"Tuzoq: o'rindiq va bort bor bo'lsa ham – bolalar yukxonaga chiqmaydi."},{"id":67,"m":"tashish","s":"Quyidagilardan kimga xavfsizlik kamarini taqmaslikka ruxsat beriladi?","v":["Old o'rindiqda o'tirgan 15 yoshli o'smirga","Shahar ichida qisqa masofaga ketayotgan haydovchiga","Taksi haydovchisiga","Avtomobil orqa o'rindig'idagi 9 yoshli bolaga"],"j":3,"i":"Avtomobil orqa o'rindig'idagi 12 yoshgacha bo'lgan bolalarga kamar taqmaslikka ruxsat beriladi; haydovchi va old o'rindiqdagi yo'lovchilar harakatni boshlashdan oldin kamar taqishi shart (YHQ, 9-band).","q":"Haydovchi va old o'rindiqdagi yo'lovchilar kamar taqishi shart; orqa o'rindiqdagi 12 yoshgacha bolalar bundan mustasno.","e":"Orqada VA 12 dan kichik – ikkala shart birga bo'lsagina kamarsiz."},{"id":68,"m":"tashish","s":"Mototsikl haydovchisi orqa o'rindiqda 17 yoshli yo'lovchini olib ketmoqda. Motoshlem bo'yicha qaysi talab to'g'ri?","v":["Haydovchi ham, yo'lovchi ham motoshlem kiyib, uni qadab olishi shart","Faqat haydovchi motoshlem kiyishi shart","Motoshlem faqat aholi punktidan tashqarida majburiy","Yo'lovchi motoshlemni qadamasdan kiyib olsa yetarli"],"j":0,"i":"Mototsikl, elektromototsikl, moped, skuter va kichik hajmdagi mototransportda haydovchi hamda yo'lovchilar maxsus motoshlem kiyishi va uni qadab olishi shart (YHQ, 9-band).","q":"Mototsikl, moped, skuter va kichik hajmdagi mototransportda haydovchi ham, yo'lovchi ham motoshlem kiyib, uni qadab olishi shart.","e":"Qadalmagan shlem – shlem emas: kiyish VA qadash."},{"id":69,"m":"tashish","s":"Odamlar bortli yuk avtomobilining yukxonasida ketmoqda. Harakat paytida ularga nima taqiqlanadi?","v":["Bort sathidan pastdagi o'rindiqlarda o'tirish","Tik turish, bortlarda yoki yuk ustida o'tirish","Yukxonada o'z yukini kuzatib borish"],"j":1,"i":"Harakatlanayotgan bortli yuk avtomobilida tik turish, bortlarda yoki undan yuqoridagi yuk ustida o'tirish taqiqlanadi; buning bajarilishini haydovchi nazorat qiladi (YHQ, 24-band).","q":"Harakatlanayotgan bortli yuk avtomobilida tik turish, bortlarda yoki yuk ustida o'tirish taqiqlanadi.","e":"Kuzovda qoida: o'rindiqda o'tir, bortga ham, yuk ustiga ham chiqma."},{"id":70,"m":"tashish","s":"Quyidagi qaysi holatda yuk \"Katta o'lchamli yuk\" taniqlik belgisi bilan belgilanishi shart?","v":["Yuk avtomobil gabaritidan orqaga 0,8 m chiqib turibdi","Yuk gabaritdan oldinga 0,9 m chiqib turibdi","Yuk yon tomonga gabaritning chetki qismidan 0,5 m chiqib turibdi","Yuk yon tomonga gabaritning chetki qismidan 0,3 m chiqib turibdi"],"j":2,"i":"Gabaritdan oldi yoki orqa tomonga 1 m dan, yon tomonga 0,4 m dan ortiq chiqib turgan yuk \"Katta o'lchamli yuk\" taniqlik belgisi bilan belgilanadi (YHQ, 163-band).","q":"Yuk gabaritdan oldi yoki orqa tomonga 1 m dan, yon tomonga 0,4 m dan ortiq chiqsa, \"Katta o'lchamli yuk\" belgisi qo'yiladi.","e":"Tuzoq: yon tomonga chegara atigi 0,4 m – oldi-orqadagi 1 m bilan adashtirmang."},{"id":71,"m":"tashish","s":"Sutkaning qorong'i vaqtida yuk avtomobilidan orqaga 1,5 m chiqib turgan yuk qanday belgilanishi kerak?","v":["Faqat \"Katta o'lchamli yuk\" taniqlik belgisi bilan","Faqat oq rangli chiroq bilan","Sariq yalt-yalt etuvchi mayoqcha bilan","\"Katta o'lchamli yuk\" belgisi va qo'shimcha ravishda qizil rangli chiroq yoki yorug'lik qaytargich bilan"],"j":3,"i":"Qorong'ida va yetarlicha ko'rinmaydigan sharoitda chiqib turgan yuk taniqlik belgisiga qo'shimcha ravishda oldidan oq, orqasidan qizil rangli chiroq yoki yorug'lik qaytargich bilan belgilanadi (YHQ, 163-band).","q":"Qorong'ida chiqib turgan yukka taniqlik belgisidan tashqari oldidan oq, orqasidan qizil chiroq yoki yorug'lik qaytargich qo'yiladi.","e":"Avtomobil chiroqlari kabi: oldi – oq, orqasi – qizil."},{"id":72,"m":"tashish","s":"Yuk bilan birga transport vositasining eni qancha metrdan ortiq bo'lsa, uning harakatlanishi DYHXX bilan kelishilishi shart (refrijerator va izotermik kuzovli bo'lmagan vosita)?","v":["3,0 m","2,0 m","2,55 m","3,5 m"],"j":2,"i":"Eni 2,55 m dan (refrijerator va izotermik kuzovlar uchun 2,6 m dan) yoki balandligi yo'l sathidan 4 m dan ortiq bo'lgan transport vositalarining harakatlanishi DYHXX bilan kelishiladi (YHQ, 164-band).","q":"Eni 2,55 m dan (refrijerator va izotermik kuzovda 2,6 m dan) ortiq transport vositasining harakati DYHXX bilan kelishiladi.","e":"Tuzoq: chegara 3 m emas – atigi 2,55 m; refrijeratorga biroz ko'proq – 2,6 m."},{"id":73,"m":"texnik","s":"Yengil avtomobil (M1 toifasi) shinasi protektori naqshlarining qoldiq balandligi qanchadan kam bo'lsa, undan foydalanish taqiqlanadi?","v":["0,8 mm","1,0 mm","1,6 mm","2,0 mm"],"j":2,"i":"M1, N1, O1, O2 toifalari uchun protektor naqshlarining qoldiq balandligi 1,6 mm dan kam bo'lsa, transport vositasidan foydalanish taqiqlanadi (3-ilova, 5.1).","q":"M1, N1, O1, O2 toifalarida protektor naqshining qoldiq balandligi 1,6 mm dan kam bo'lsa, foydalanish taqiqlanadi.","e":"Shina zinapoyasi: mototsikl 0,8 – og'ir yuk 1,0 – yengil 1,6 – avtobus 2,0 mm."},{"id":74,"m":"texnik","s":"Avtobus (M2, M3 toifalari) shinasi protektori naqshlarining qoldiq balandligi qanchadan kam bo'lsa, undan foydalanish taqiqlanadi?","v":["2,0 mm","1,0 mm","1,6 mm","0,8 mm"],"j":0,"i":"M2, M3 toifalari uchun chegara 2,0 mm; N2, N3 yuk avtomobillari uchun 1,0 mm, yengil avtomobillar uchun 1,6 mm, mototsikl va mopedlar uchun 0,8 mm (3-ilova, 5.1).","q":"M2, M3 (avtobus) toifalarida protektor naqshining qoldiq balandligi 2,0 mm dan kam bo'lsa, foydalanish taqiqlanadi.","e":"Odam ko'p tashiydi – talab qattiq: avtobusda eng katta chegara, 2,0 mm."},{"id":75,"m":"texnik","s":"Yengil avtomobil (M1 toifasi) boshqaruv qurilmasining (rulining) lyuft yig'indisi necha gradusdan oshsa, undan foydalanish taqiqlanadi?","v":["5°","20°","25°","10°"],"j":3,"i":"Rul lyufti yig'indisi M1 uchun 10°, M2, M3, N1 uchun 20°, N2, N3 uchun 25° dan oshsa, transport vositasidan foydalanish taqiqlanadi (3-ilova, 2.1).","q":"Rul lyufti yig'indisi M1 uchun 10°, M2, M3, N1 uchun 20°, N2, N3 uchun 25° dan oshsa, foydalanish taqiqlanadi.","e":"Rul zinapoyasi: yengil – 10°, avtobus va N1 – 20°, og'ir yuk (N2, N3) – 25°."},{"id":76,"m":"texnik","s":"Avtomobilning old oynasi va old yon oynalarining yorug'lik o'tkazuvchanligi qanchadan kam bo'lsa, undan foydalanish taqiqlanadi (oynalarni qoraytirishga ruxsatnoma bo'lmasa)?","v":["50%","70%","60%","90%"],"j":1,"i":"Old va yon oynalarning yorug'lik o'tkazuvchanligi 70% dan kam bo'lsa, foydalanish taqiqlanadi; tom lyuki oynasi va ruxsatnoma asosida qoraytirilgan oynalar bundan mustasno (3-ilova, 7.4).","q":"Old oyna va old yon oynalarning yorug'lik o'tkazuvchanligi 70% dan kam bo'lsa, foydalanish taqiqlanadi (ruxsatnoma bo'lmasa).","e":"Tuzoq: 50% emas – oyna kamida 70% yorug'lik o'tkazishi kerak."},{"id":77,"m":"texnik","s":"Yengil avtomobil (M1 toifasi) uchun quyidagilardan qaysi biri majburiy jihozlar ro'yxatiga kirmaydi?","v":["O't o'chirgich","G'ildirak tirgaklari (kamida ikkita)","Tibbiyot qutichasi (aptechka)","Avariya sababli to'xtash belgisi"],"j":1,"i":"M1 avtomobilda tibbiyot qutichasi, o't o'chirgich, avariya sababli to'xtash belgisi (yoki miltillovchi qizil chiroq) va nur qaytargichli kamzul bo'lishi shart; g'ildirak tirgaklari M3, N2, N3 toifalari uchun talab qilinadi (3-ilova, 7.10).","q":"M1 avtomobilda tibbiyot qutichasi, o't o'chirgich, avariya sababli to'xtash belgisi va nur qaytargichli kamzul bo'lishi shart.","e":"Yengil mashina to'rtligi: aptechka, o't o'chirgich, uchburchak, kamzul; g'ildirak tirgagi – og'ir mashinalarga."},{"id":78,"m":"texnik","s":"Yo'lda ketayotganingizda gidravlik tormoz yuritmasidan tormoz suyuqligi oqa boshladi va nosozlikni joyida bartaraf etib bo'lmaydi. Qoidalarga ko'ra qanday yo'l tutasiz?","v":["Avariya ishorasini yoqib, ta'mirlash joyiga o'zingiz haydab borasiz","Manzilga yetib olguncha past tezlikda davom etasiz","Zarur ehtiyot choralarini ko'rib, avtomobilni evakuator yoki shatakka olish orqali ta'mirlash yoki to'xtab turish joyiga olib borasiz","Avtomobilni qatnov qismida qoldirib, ertasi kuni qaytib kelasiz"],"j":2,"i":"Gidravlik tormoz yuritmasi germetikligining buzilishi foydalanishni taqiqlaydi (3-ilova, 1.3); bunday nosozlikni joyida bartaraf etib bo'lmasa, vosita ehtiyot choralari bilan evakuator yoki shatakka olish orqali ta'mirlash yoki to'xtab turish joyiga olib boriladi (YHQ, 12-band).","q":"Tormoz yuritmasi nosoz bo'lib, uni joyida tuzatib bo'lmasa, avtomobil evakuator yoki shatakka olish orqali olib boriladi.","e":"Tuzoq: \"sekin-sekin o'zim yetib olaman\" – tormoz nosoz bo'lsa, o'zingiz haydamaysiz."},{"id":79,"m":"texnik","s":"Quyidagi qaysi holatda transport vositasini boshqarish taqiqlanadi?","v":["Avtomagnitola ishlamay qolgan","Yomg'ir yog'ayotganda oyna tozalagich ishlamaydi","Salondagi soat noto'g'ri vaqtni ko'rsatmoqda","Kuzov bo'yog'ida kichik tirnalgan joy bor"],"j":1,"i":"Yomg'ir yoki qor yog'ayotganda oyna tozalagich ishlamaydigan transport vositasini boshqarish taqiqlanadi (YHQ, 12-band; 3-ilova, 4.1).","q":"Yomg'ir yoki qor yog'ayotganda oyna tozalagich ishlamaydigan transport vositasini boshqarish taqiqlanadi.","e":"Tuzoq: magnitola yoki soat – mayda gap; yomg'irda oyna tozalagich – xavfsizlik."},{"id":80,"m":"texnik","s":"Yengil avtomobilda quyidagi qaysi nosozlik bo'lsa, undan foydalanish taqiqlanadi?","v":["Faralar nurining yo'nalishi buzilgan (rostlanmagan)","Bort kompyuterida yoqilg'i sarfi ko'rsatkichi ishlamaydi","Bagajnikdagi gilamcha yirtilgan","Eshik ichki qoplamasida dog' bor"],"j":0,"i":"Tashqi yoritish asboblarining nur yo'nalishi buzilgan bo'lsa, ular boshqa haydovchilarning ko'zini qamashtirishi yoki yo'lni yetarli yoritmasligi mumkin, shuning uchun transport vositasidan foydalanish taqiqlanadi (3-ilova, 3.2).","q":"Tashqi yoritish asboblarining nur yo'nalishi buzilgan bo'lsa, transport vositasidan foydalanish taqiqlanadi.","e":"Qiyshiq fara – ikki xavf: ro'paradagining ko'zini qamashtiradi yoki yo'lni yoritmaydi."},{"id":81,"m":"tibbiy","s":"Siz ishtirok etgan yo'l-transport hodisasida jabrlangan bor. Birinchi navbatda nima qilishingiz kerak?","v":["Jabrlanganni darhol o'z avtomobilingizga o'tqazib, shifoxonaga olib ketish","Avtomobilni to'xtatib, avariya ishorasini yoqish va avariya sababli to'xtash belgisini qo'yish, so'ng jabrlanganga yordam berib, tez yordam chaqirish","Avval avtomobillarni yo'l chetiga surib, harakatni tiklash","Avval sug'urta kompaniyasiga qo'ng'iroq qilish"],"j":1,"i":"Avval o'zingiz va boshqalar xavfsizligini ta'minlaysiz (to'xtash, avariya ishorasi, belgi), so'ng birinchi yordam ko'rsatib, tez tibbiy yordam chaqirasiz; transport vositasini joyidan qo'zg'atmaysiz (YHQ, 13-band; birinchi yordam asoslari).","q":"YTHda haydovchi darhol to'xtab, avariya chirog'ini yoqadi va belgi qo'yadi, so'ng jabrlanganga yordam berib, tez yordam chaqiradi.","e":"Avval o'zingni va yo'lni himoya qil, keyin jabrlanganni – qutqaruvchi ikkinchi jabrlanuvchiga aylanmasin."},{"id":82,"m":"tibbiy","s":"YTH joyidan tez tibbiy yordamga (103 yoki 112) qo'ng'iroq qilganda nimani albatta aytish kerak?","v":["Faqat ismingiz va telefon raqamingizni","Avtomobillarning markasi va rangini","Hodisada kim aybdor ekanini","Voqea joyining aniq manzilini (ko'cha, mo'ljal yoki yo'l kilometri), jabrlanganlar soni va ahvolini"],"j":3,"i":"Brigada tez va adashmasdan yetib kelishi uchun aniq joy hamda jabrlanganlar soni va ahvoli aytiladi; dispetcher aytmaguncha aloqani uzmang (YHQ, 13-band; birinchi yordam asoslari).","q":"Tez yordamga qo'ng'iroq qilganda voqea joyining aniq manzili, jabrlanganlar soni va ahvoli aytiladi.","e":"\"Qayerda, nechta, qanday\" – uchta javob bering, aloqani birinchi bo'lib uzmang."},{"id":83,"m":"tibbiy","s":"Jabrlangan hushsiz, lekin siz uning normal nafas olayotganini aniqladingiz. Umurtqa shikasti belgilari yo'q. Tez yordam kelguncha uni qanday holatda qoldirgan ma'qul?","v":["Barqaror yon holatga (yonboshlatib) yotqizib, nafasini kuzatib turish","Chalqancha yotqizib, boshi ostiga baland yostiq qo'yish","O'tqazib, orqasini avtomobilga suyab qo'yish","Oyog'iga turg'izib, yurgizib ko'rish"],"j":0,"i":"Hushsiz, lekin nafas olayotgan jabrlangan barqaror yon holatga yotqiziladi, shunda til yoki qusuq nafas yo'lini to'smaydi; nafasi to'xtamaganini doim kuzatib turish kerak (birinchi yordam asoslari).","q":"Hushsiz, lekin normal nafas olayotgan jabrlangan (umurtqa shikasti belgisi bo'lmasa) barqaror yon holatga yotqiziladi.","e":"Nafas bor – yonga: yonboshda til va qusuq nafas yo'lini to'smaydi."},{"id":84,"m":"tibbiy","s":"Jabrlanganning bilagidagi yaradan qon oqmoqda. Qon ketishini to'xtatish uchun birinchi navbatda nima qilinadi?","v":["Darhol yelkaga jgut (turniket) qo'yiladi","Yaraga toza bint yoki mato qo'yib, qattiq bosib turiladi","Yara qon oqishi o'zi to'xtaguncha ochiq qoldiriladi","Yaraga tuproq yoki kul sepiladi"],"j":1,"i":"Ko'pchilik qon ketishlari yaraga toza mato qo'yib, to'g'ridan-to'g'ri qattiq bosish bilan to'xtatiladi; jgut faqat bosish yordam bermaydigan, hayot uchun xavfli qon ketishida qo'llanadi (birinchi yordam asoslari).","q":"Ko'pchilik qon ketishlarida birinchi chora – yaraga toza bint yoki mato qo'yib, qattiq bosib turish.","e":"Qon oqsa – avval bos: jgut emas, kaft birinchi."},{"id":85,"m":"tibbiy","s":"Qaysi holatda jgut (turniket) qo'yiladi va bunda nima qilish shart?","v":["Har qanday kesilgan yarada; qo'yilgan vaqtni yozish shart emas","Bo'yindagi jarohatda, bo'yin atrofiga","Qo'l yoki oyoqdan hayot uchun xavfli kuchli qon ketayotganda va bosib turish yordam bermasa; qo'yilgan vaqt yozib qo'yiladi","Kuygan joyga, og'riqni kamaytirish uchun"],"j":2,"i":"Jgut faqat qo'l-oyoqdan hayot uchun xavfli qon ketishida, to'g'ridan-to'g'ri bosish yetarli bo'lmaganda qo'yiladi; qo'yilgan vaqt yozib qo'yiladi va tez yordam xodimlariga aytiladi (birinchi yordam asoslari).","q":"Jgut faqat qo'l yoki oyoqdan hayot uchun xavfli qon ketishida, bosish yordam bermaganda qo'yiladi; qo'yilgan vaqt yoziladi.","e":"Jgut – oxirgi chora va soat: vaqtni yozmasangiz, shifokor bilmaydi."},{"id":86,"m":"tibbiy","s":"Jabrlanganning umurtqa pog'onasi (bo'yni yoki beli) shikastlangan bo'lishi mumkin. Tez tibbiy yordam chaqirilgan, joyida yong'in yoki boshqa xavf yo'q. To'g'ri harakat qaysi?","v":["Uni avtomobilga o'tqazib, tezda shifoxonaga olib borish","Uni turg'izib, yura olishini tekshirish","Boshi ostiga baland yostiq qo'yib, oyoqlarini ko'tarib qo'yish","Uni joyidan qo'zg'atmaslik, boshini harakatsiz ushlab, tez yordam kelishini kutish"],"j":3,"i":"Umurtqa shikasti gumon qilinganda, xavf (yong'in, kelayotgan transport va h.k.) bo'lmasa, jabrlanganni qo'zg'atmaslik kerak: noto'g'ri harakat orqa miyani shikastlashi mumkin (birinchi yordam asoslari).","q":"Umurtqa shikasti gumon qilinsa va xavf bo'lmasa, jabrlangan joyidan qo'zg'atilmaydi, boshi harakatsiz ushlab turiladi.","e":"Bo'yin yoki bel shikastida: \"qimirlatma – kut\" (yong'in kabi xavf bo'lmasa)."},{"id":87,"m":"tibbiy","s":"YTHdan keyin avtomobil yonib, jabrlanganning qo'li kuydi. Kuygan joyga birinchi yordam qanday ko'rsatiladi?","v":["Kuygan joyga yog' yoki krem surtiladi","Hosil bo'lgan pufakchalar yoriladi","Kuygan joy toza, salqin suv bilan sovutiladi","Kuyib terisiga yopishgan kiyim yulib olinadi"],"j":2,"i":"Kuygan joy toza, salqin suv bilan sovutiladi, so'ng toza bog'lam bilan yopiladi; yog' surtish, pufakchalarni yorish va yopishgan kiyimni yulib olish mumkin emas (birinchi yordam asoslari).","q":"Kuygan joy toza, salqin suv bilan sovutiladi va toza bog'lam bilan yopiladi; yog' surtilmaydi, pufakcha yorilmaydi.","e":"Kuyishga faqat suv: yog' – yo'q, pufak yorish – yo'q, yopishgan kiyimni yulish – yo'q."},{"id":88,"m":"tibbiy","s":"Mototsiklchi YTHdan keyin yerda yotibdi, u motoshlem kiygan va normal nafas olmoqda. Motoshlem bilan nima qilish kerak?","v":["Darhol yechib olish kerak, aks holda u bo'g'iladi","Zarurat bo'lmasa yechmaslik, boshini harakatsiz holda saqlash kerak","Shlemni burab, kuch bilan tortib olish kerak","Shlemni yechib, boshini balandroq qo'yish kerak"],"j":1,"i":"Nafas olayotgan jabrlanganning motoshlemi keraksiz yechilmaydi, chunki bu bo'yin shikastini og'irlashtirishi mumkin; u faqat nafas yo'lini ochish zarur bo'lganda ehtiyotkorlik bilan yechiladi (birinchi yordam asoslari).","q":"Nafas olayotgan mototsiklchining motoshlemi keraksiz yechilmaydi; faqat nafas yo'lini ochish zarur bo'lsa ehtiyotkorlik bilan yechiladi.","e":"Nafas bor – shlem joyida: shlemni yechish bo'yinni qimirlatadi."},{"id":89,"m":"chorraha","s":"Tartibga solinmagan teng ahamiyatli yo'llar chorrahasi (imtiyoz belgilari yo'q, qoplama bir xil). A va B to'g'riga harakatlanmoqda. Qaysi biri birinchi o'tadi?","v":["A","B","Ikkalasi bir vaqtda"],"j":1,"i":"Teng ahamiyatli yo'llar chorrahasida relssiz transport vositasi haydovchisi o'ngdan yaqinlashayotgan transport vositasiga yo'l beradi. B avtomobili A ga nisbatan o'ng tomonda (YHQ, 105-band).","r":{"sahna":{"tur":"X","avto":[{"id":"A","joy":"S","y":"togri"},{"id":"B","joy":"E","y":"togri"}]}},"q":"Teng ahamiyatli yo'llar chorrahasida relssiz transport vositasi haydovchisi o'ngdan yaqinlashayotgan transport vositasiga yo'l beradi.","e":"O'ngdan kelgan — mehmon: unga yo'l ber."},{"id":90,"m":"chorraha","s":"Tartibga solinmagan teng ahamiyatli yo'llar chorrahasi (imtiyoz belgilari yo'q, qoplama bir xil). Avtomobillar qanday tartibda o'tadi?","v":["Avval B, keyin A","Avval A, keyin B","A va B bir vaqtda"],"j":0,"i":"Chapga burilayotgan A haydovchisi qarama-qarshi yo'nalishdan to'g'riga ketayotgan B ga yo'l beradi (YHQ, 107-band).","r":{"sahna":{"tur":"X","avto":[{"id":"A","joy":"S","y":"chap"},{"id":"B","joy":"N","y":"togri"}]}},"q":"Chapga burilayotgan yoki qayrilib olayotgan haydovchi qarama-qarshidan to'g'riga yoki o'ngga ketayotganlarga yo'l beradi.","e":"Chapga burilsang — qarshidagi oqimni kesasan: avval ular o'tadi."},{"id":91,"m":"chorraha","s":"Tartibga solinmagan teng ahamiyatli yo'llar chorrahasi (imtiyoz belgilari yo'q, qoplama bir xil). Avtomobillar qanday tartibda o'tadi?","v":["A, B, C","B, A, C","C, A, B","A, C, B"],"j":2,"i":"C ning o'ngida hech kim yo'q, u birinchi o'tadi. A uchun C o'ng tomonda. B uchun A o'ng tomonda, bundan tashqari chapga burilayotgan B qarama-qarshidan to'g'riga ketayotgan C ga ham yo'l beradi. Tartib: C, A, B (YHQ, 105 va 107-bandlar).","r":{"sahna":{"tur":"X","avto":[{"id":"A","joy":"S","y":"togri"},{"id":"B","joy":"W","y":"chap"},{"id":"C","joy":"E","y":"togri","tur":"yuk"}]}},"q":"Teng ahamiyatli chorrahada o'ngdan kelganga yo'l beriladi; chapga buriluvchi qarama-qarshidan to'g'riga ketayotganga ham yo'l beradi.","e":"Avval o'ngni tekshir, keyin chapga burilishni: ikkala qoida birga ishlaydi."},{"id":92,"m":"chorraha","s":"Tartibga solinmagan chorraha. Qaysi avtomobil birinchi o'tadi?","v":["A, chunki B chapga burilmoqda","A, chunki B unga nisbatan chap tomondan yaqinlashmoqda","B, chunki u asosiy yo'lda harakatlanmoqda"],"j":2,"i":"A ikkinchi darajali yo'lda (\"Yo'l bering!\" belgisi), shuning uchun u asosiy yo'ldagi B ga, B ning keyingi yo'nalishidan qat'i nazar, yo'l beradi (YHQ, 104-band; 1-ilova, 2.4-belgi).","r":{"sahna":{"tur":"X","asosiy":["N","S"],"belgi":[{"kod":"2.1","joy":"N"},{"kod":"2.1","joy":"S"},{"kod":"2.4","joy":"E"},{"kod":"2.4","joy":"W"}],"avto":[{"id":"A","joy":"E","y":"togri"},{"id":"B","joy":"S","y":"chap"}]}},"q":"Ikkinchi darajali yo'ldagi haydovchi asosiy yo'ldagilarga, ular qayerga burilishidan qat'i nazar, yo'l beradi.","e":"2.4 belgisi ko'rdingmi — o'ng-chap hisobini unut: asosiy yo'ldagi, qayerga burilmasin, birinchi."},{"id":93,"m":"chorraha","s":"Tartibga solinmagan chorraha. Avtomobillar qanday tartibda o'tadi?","v":["B, A, C","A, B, C","B, C, A","C, B, A"],"j":0,"i":"C ikkinchi darajali yo'lda, u asosiy yo'ldagi A va B ga yo'l beradi. Asosiy yo'lda chapga burilayotgan A qarama-qarshidan to'g'riga ketayotgan B ga yo'l beradi (YHQ, 104 va 107-bandlar).","r":{"sahna":{"tur":"X","asosiy":["N","S"],"belgi":[{"kod":"2.1","joy":"N"},{"kod":"2.1","joy":"S"},{"kod":"2.4","joy":"E"},{"kod":"2.4","joy":"W"}],"avto":[{"id":"A","joy":"S","y":"chap"},{"id":"B","joy":"N","y":"togri"},{"id":"C","joy":"E","y":"togri"}]}},"q":"Avval asosiy yo'ldagilar o'tadi; ular o'zaro: chapga buriluvchi qarama-qarshidan to'g'riga va o'ngga ketayotganga yo'l beradi.","e":"Ikki qadam: 1) asosiy yo'l oldin; 2) asosiy yo'l ichida chapga buriluvchi kutadi."},{"id":94,"m":"chorraha","s":"Tartibga solinmagan T-simon chorraha, yo'llar teng ahamiyatli (imtiyoz belgilari yo'q, qoplama bir xil). Qaysi avtomobil birinchi o'tadi?","v":["B, chunki u to'g'ri davom etadigan yo'lda","A","B, chunki chapga burilayotgan A unga yo'l beradi"],"j":1,"i":"T-simon chorrahada ham teng ahamiyatli yo'llar qoidasi amal qiladi: A avtomobili B ga nisbatan o'ngdan yaqinlashmoqda, shuning uchun B yo'l beradi. Chapga burilishdagi yo'l berish qoidasi faqat qarama-qarshi yo'nalishdagilarga tegishli (YHQ, 105 va 107-bandlar).","r":{"sahna":{"tur":"T","yoq":"N","avto":[{"id":"A","joy":"S","y":"chap"},{"id":"B","joy":"W","y":"togri"}]}},"q":"T-simon chorrahada ham, yo'llar teng ahamiyatli bo'lsa, o'ngdan yaqinlashayotgan transport vositasiga yo'l beriladi.","e":"Tuzoq: T-chorrahada 'to'g'ri davom etuvchi yo'l' asosiy emas — teng yo'llarda o'ngdagi o'tadi."},{"id":95,"m":"chorraha","s":"Tartibga solinmagan chorraha. Avtomobillar qanday tartibda o'tadi?","v":["Avval C, keyin B, keyin A","Avval A, keyin B va C","Avval B, keyin A, keyin C","B va C bir vaqtda, keyin A"],"j":3,"i":"A ikkinchi darajali yo'lda, u asosiy yo'ldagi B va C ga yo'l beradi. B va C qarama-qarshi yo'nalishda to'g'riga ketmoqda, ularning yo'li kesishmaydi, shuning uchun ular bir vaqtda o'tadi (YHQ, 104-band).","r":{"sahna":{"tur":"T","yoq":"N","asosiy":["W","E"],"belgi":[{"kod":"2.1","joy":"W"},{"kod":"2.1","joy":"E"},{"kod":"2.4","joy":"S"}],"avto":[{"id":"A","joy":"S","y":"chap"},{"id":"B","joy":"E","y":"togri"},{"id":"C","joy":"W","y":"togri","tur":"avtobus"}]}},"q":"Qarama-qarshi yo'nalishda to'g'riga ketayotganlarning yo'li kesishmaydi, ular bir vaqtda o'tadi; ikkinchi darajali yo'ldagi kutadi.","e":"Yo'llar kesishmasa — navbat ham yo'q: qarama-qarshi to'g'rilar birga o'tadi."},{"id":96,"m":"chorraha","s":"Tartibga solinmagan teng ahamiyatli yo'llar chorrahasi (imtiyoz belgilari yo'q, qoplama bir xil). Kim birinchi o'tadi?","v":["A, chunki tramvay unga nisbatan chap tomondan yaqinlashmoqda","Tramvay (T)","Chorrahaga kim birinchi yetib kelsa"],"j":1,"i":"Teng ahamiyatli yo'llar chorrahasida tramvay harakat yo'nalishidan qat'i nazar relssiz transport vositalariga nisbatan imtiyozga ega (YHQ, 105-band).","r":{"sahna":{"tur":"X","tramvay":"EW","avto":[{"id":"T","joy":"W","y":"togri","tur":"tramvay"},{"id":"A","joy":"S","y":"togri"}]}},"q":"Teng ahamiyatli yo'llar chorrahasida tramvay harakat yo'nalishidan qat'i nazar relssiz transport vositalaridan oldin o'tadi.","e":"Teng yo'llarda tramvayga o'ng-chap hisobi yo'q: u qayerdan kelsa ham birinchi."},{"id":97,"m":"chorraha","s":"Tartibga solinmagan chorraha. Kim birinchi o'tadi?","v":["A avtomobili","Tramvay, chunki tramvay har doim imtiyozga ega","Tramvay, chunki u to'g'riga harakatlanmoqda"],"j":0,"i":"Tramvay ikkinchi darajali yo'lda (\"Yo'l bering!\" belgisi). Ikkinchi darajali yo'ldagi haydovchi, jumladan tramvay haydovchisi ham, asosiy yo'ldagilarga yo'l beradi. Bunday chorrahada tramvayning imtiyozi faqat teng ahamiyatli yo'lda harakatlanayotgan relssiz transport vositalariga nisbatan amal qiladi (YHQ, 104-band).","r":{"sahna":{"tur":"X","asosiy":["E","W"],"belgi":[{"kod":"2.1","joy":"E"},{"kod":"2.1","joy":"W"},{"kod":"2.4","joy":"N"},{"kod":"2.4","joy":"S"}],"tramvay":"NS","avto":[{"id":"T","joy":"S","y":"togri","tur":"tramvay"},{"id":"A","joy":"E","y":"togri"}]}},"q":"Ikkinchi darajali yo'ldagi tramvay ham asosiy yo'ldagilarga yo'l beradi: uning imtiyozi faqat teng ahamiyatli yo'ldagilarga nisbatan.","e":"Tuzoq: 'tramvay har doim birinchi' — yo'q! 'Yo'l bering!' belgisi tramvayga ham amal qiladi."},{"id":98,"m":"chorraha","s":"Tartibga solinmagan teng ahamiyatli yo'llar chorrahasi (imtiyoz belgilari yo'q, qoplama bir xil). B avtomobilida ko'k va qizil yaltiroq mayoqchalar hamda maxsus tovushli ishora yoqilgan. Kim birinchi o'tadi?","v":["A, chunki B unga nisbatan chap tomondan yaqinlashmoqda","Chorrahaga kim birinchi yetib kelsa","B"],"j":2,"i":"Ko'k (yoki qizil) yaltiroq mayoqchasi va maxsus tovushli ishorasi yoqilgan holda yaqinlashayotgan transport vositasiga barcha haydovchilar yo'l berishi shart (YHQ, 25 va 26-bandlar).","r":{"sahna":{"tur":"X","avto":[{"id":"A","joy":"S","y":"togri"},{"id":"B","joy":"W","y":"togri","tur":"maxsus"}]}},"q":"Ko'k yoki qizil yaltiroq mayoqchasi va maxsus tovushli ishorasi yoqilgan transport vositasiga barcha haydovchilar yo'l berishi shart.","e":"Mayoqcha + sirena = yo'l och: ikkalasi yonib-chalinsa, sen kutasan."},{"id":99,"m":"chorraha","s":"Tartibga solinmagan teng ahamiyatli yo'llar chorrahasi (imtiyoz belgilari yo'q, qoplama bir xil). B avtomobilida ko'k va qizil yaltiroq mayoqchalar yoqilgan, lekin maxsus tovushli ishora o'chiq. Kim birinchi o'tadi?","v":["B, chunki u maxsus xizmat avtomobili","A","B, chunki mayoqcha yoqilgan bo'lsa, yo'l berish shart"],"j":1,"i":"Imtiyozga ega bo'lish uchun mayoqcha bilan birga maxsus tovushli ishora ham yoqilgan bo'lishi shart. Bu holatda B umumiy qoidaga amal qiladi va o'ngdan yaqinlashayotgan A ga yo'l beradi (YHQ, 25, 26 va 105-bandlar).","r":{"sahna":{"tur":"X","avto":[{"id":"A","joy":"W","y":"togri"},{"id":"B","joy":"N","y":"togri","tur":"maxsus"}]}},"q":"Maxsus transport vositasi imtiyozga faqat mayoqcha bilan birga maxsus tovushli ishora ham yoqilganda ega bo'ladi.","e":"Tuzoq: faqat chiroq yonsa-yu, sirena jim bo'lsa — oddiy chorraha qoidasi ishlaydi."},{"id":100,"m":"chorraha","s":"A haydovchisi svetoforning yashil ishorasida o'ngga burilmoqda. U qanday harakat qilishi kerak?","v":["Burilayotgan yo'lning qatnov qismidan o'tayotgan piyodalarga yo'l beradi","Yashil ishorada imtiyozga ega, piyodalardan oldin o'tadi","Tovushli ishora berib, piyodalarni to'xtatadi"],"j":0,"i":"Chapga yoki o'ngga burilayotgan haydovchi kesishayotgan yo'lning qatnov qismidan o'tayotgan piyodalarga yo'l berishi shart (YHQ, 96-band).","r":{"sahna":{"tur":"X","svetofor":{"S":"yashil","N":"yashil","E":"qizil","W":"qizil"},"piyoda":["E"],"avto":[{"id":"A","joy":"S","y":"ong"}]}},"q":"Burilayotgan haydovchi o'zi kirayotgan yo'lning qatnov qismidan o'tayotgan piyodalar va velosipedchilarga yo'l beradi.","e":"Tuzoq: yashil senga ham, piyodaga ham yonadi — burilishda piyoda oldin."},{"id":101,"m":"chorraha","s":"Ikkala avtomobil uchun ham svetoforning yashil ishorasi yonib turibdi. Ular qanday tartibda o'tadi?","v":["Avval A, keyin B","A va B bir vaqtda","Avval B, keyin A"],"j":2,"i":"Ruxsat etuvchi ishorada chapga burilayotgan relssiz transport vositasi haydovchisi qarama-qarshidan to'g'riga va o'ngga ketayotganlarga yo'l beradi (YHQ, 99-band).","r":{"sahna":{"tur":"X","svetofor":{"S":"yashil","N":"yashil","E":"qizil","W":"qizil"},"avto":[{"id":"A","joy":"S","y":"chap"},{"id":"B","joy":"N","y":"togri","tur":"yuk"}]}},"q":"Ruxsat etuvchi ishorada chapga burilayotgan yoki qayrilib olayotgan haydovchi qarama-qarshidan to'g'riga va o'ngga ketayotganga yo'l beradi.","e":"Yashil — 'yur' degani, 'birinchi' degani emas: chapga buriluvchi qarshidagini o'tkazadi."},{"id":102,"m":"chorraha","s":"Svetoforning yashil ishorasi tramvayga ham, A avtomobiliga ham ruxsat bermoqda. Kim birinchi o'tadi?","v":["Tramvay","A avtomobili","Ikkalasi bir vaqtda"],"j":0,"i":"Svetofor tramvay va relssiz transport vositalariga bir vaqtda ruxsat bersa, tramvay oldin o'tadi. Bundan tashqari, chapga burilayotgan A qarama-qarshidan to'g'riga ketayotganlarga yo'l beradi (YHQ, 99 va 101-bandlar).","r":{"sahna":{"tur":"X","tramvay":"NS","svetofor":{"S":"yashil","N":"yashil","E":"qizil","W":"qizil"},"avto":[{"id":"T","joy":"N","y":"togri","tur":"tramvay"},{"id":"A","joy":"S","y":"chap"}]}},"q":"Svetofor tramvay va relssiz transport vositalariga bir vaqtda ruxsat bersa, yo'nalishidan qat'i nazar tramvay oldin o'tadi.","e":"Bitta yashil, ikki da'vogar — tramvay va avtomobil bo'lsa, tramvay birinchi."},{"id":103,"m":"chorraha","s":"Tartibga solinmagan chorraha. A haydovchisi qanday harakat qilishi kerak?","v":["B ga yo'l berib, to'xtamasdan o'tishi mumkin","B dan oldin o'tadi, chunki B unga nisbatan chap tomondan yaqinlashmoqda","To'xtash chizig'i oldida albatta to'xtab, keyin B ga yo'l berishi kerak"],"j":2,"i":"Bu belgi to'xtamasdan harakatlanishni taqiqlaydi: haydovchi to'xtash chizig'i oldida (u bo'lmasa kesib o'tiladigan qatnov qismi chetida) to'xtaydi va asosiy yo'ldagilarga yo'l beradi (1-ilova, 2.5-belgi; YHQ, 104-band).","r":{"sahna":{"tur":"X","asosiy":["E","W"],"belgi":[{"kod":"2.1","joy":"E"},{"kod":"2.1","joy":"W"},{"kod":"2.5","joy":"N"},{"kod":"2.5","joy":"S"}],"avto":[{"id":"A","joy":"S","y":"togri"},{"id":"B","joy":"W","y":"togri"}]}},"q":"2.5 belgisida to'xtash chizig'i oldida (u bo'lmasa, kesib o'tiladigan qatnov qismi chetida) albatta to'xtab, so'ng yo'l beriladi.","e":"2.4 — kerak bo'lsa to'xta; 2.5 — yo'l bo'sh bo'lsa ham har doim to'xta, keyin yo'l ber."},{"id":104,"m":"chorraha","s":"Tartibga solinmagan chorraha. Asosiy yo'l chorrahada yo'nalishini o'zgartiradi: imtiyoz belgilari ostida \"Asosiy yo'lning yo'nalishi\" qo'shimcha belgisi bor (rasmda asosiy yo'l sariq chiziq bilan ko'rsatilgan). Avtomobillar qanday tartibda o'tadi?","v":["A, B, C","B, A, C","C, B, A","B, C, A"],"j":1,"i":"A va B asosiy yo'lda, ular o'zaro teng ahamiyatli yo'llar qoidasiga amal qiladi: A uchun B o'ng tomonda, shuning uchun B birinchi o'tadi. C ikkinchi darajali yo'lda, u ikkalasiga yo'l beradi (YHQ, 104 va 106-bandlar).","r":{"sahna":{"tur":"X","asosiy":["S","E"],"belgi":[{"kod":"2.1","joy":"S"},{"kod":"2.1","joy":"E"},{"kod":"2.4","joy":"N"},{"kod":"2.4","joy":"W"}],"avto":[{"id":"A","joy":"S","y":"togri"},{"id":"B","joy":"E","y":"togri"},{"id":"C","joy":"N","y":"chap"}]}},"q":"Asosiy yo'l chorrahada yo'nalishini o'zgartirsa (7.13), asosiy yo'ldagilar o'zaro teng ahamiyatli yo'llar qoidasiga amal qiladi.","e":"Ikki qavat: avval asosiy yo'ldagilar o'zaro o'ng qoidasi bilan, so'ng ikkinchi darajalilar."},{"id":105,"m":"chorraha","s":"Tartibga solinmagan T-simon chorraha. Asosiy yo'l chorrahada yo'nalishini o'zgartiradi: imtiyoz belgilari ostida \"Asosiy yo'lning yo'nalishi\" qo'shimcha belgisi bor (rasmda asosiy yo'l sariq chiziq bilan ko'rsatilgan). Avtomobillar qanday tartibda o'tadi?","v":["B, A, C","A, C, B","C, A, B","A, B, C"],"j":3,"i":"A va B asosiy yo'lda va o'zaro teng ahamiyatli yo'llar qoidasiga amal qiladi: B uchun A o'ng tomonda, shuning uchun A birinchi o'tadi. C ikkinchi darajali yo'lda, u asosiy yo'ldagi ikkala avtomobilga yo'l beradi (YHQ, 104 va 106-bandlar).","r":{"sahna":{"tur":"T","yoq":"N","asosiy":["S","W"],"belgi":[{"kod":"2.1","joy":"S"},{"kod":"2.1","joy":"W"},{"kod":"2.4","joy":"E"}],"avto":[{"id":"A","joy":"S","y":"chap"},{"id":"B","joy":"W","y":"togri"},{"id":"C","joy":"E","y":"chap"}]}},"q":"7.13 belgisi asosiy yo'lning chorrahadagi yo'nalishini ko'rsatadi; asosiy yo'ldagilar o'zaro o'ngdan kelganga yo'l beradi.","e":"Tuzoq: 'to'g'ri ketayotgan birinchi' emas — asosiy yo'l egilsa, uning ichida ham o'ng qoidasi."},{"id":106,"m":"chorraha","s":"Tartibga solinmagan teng ahamiyatli yo'llar chorrahasi (imtiyoz belgilari yo'q, qoplama bir xil). A haydovchisi qayrilib olmoqchi. Avtomobillar qanday tartibda o'tadi?","v":["Avval A, keyin B","Avval B, keyin A","A chorrahada qayrilib olishi mumkin emas"],"j":1,"i":"Qayrilib olayotgan haydovchi ham chapga burilayotgan kabi qarama-qarshi yo'nalishdan to'g'riga yoki o'ngga ketayotganlarga yo'l beradi (YHQ, 107-band).","r":{"sahna":{"tur":"X","avto":[{"id":"A","joy":"S","y":"qaytish"},{"id":"B","joy":"N","y":"togri"}]}},"q":"Qayrilib olayotgan haydovchi chapga burilayotgan kabi qarama-qarshidan to'g'riga yoki o'ngga ketayotganlarga yo'l beradi.","e":"Qayrilib olish — 'katta chapga burilish': qoidasi ham xuddi chapga burilishniki."},{"id":107,"m":"chorraha","s":"Chorrahadagi svetoforlar ishlamayapti, tartibga soluvchi yo'q. Kim birinchi o'tadi?","v":["B, chunki u A ga nisbatan o'ng tomondan yaqinlashmoqda","Svetofor ishlamasa, chorrahaga kirish taqiqlanadi","A"],"j":2,"i":"Svetofor ishlamasa, chorraha tartibga solinmagan hisoblanadi va haydovchilar imtiyoz belgilariga amal qiladi. B \"Yo'l bering!\" belgisi bo'yicha asosiy yo'ldagi A ga yo'l beradi (YHQ, 98 va 104-bandlar).","r":{"sahna":{"tur":"X","asosiy":["N","S"],"belgi":[{"kod":"2.1","joy":"N"},{"kod":"2.1","joy":"S"},{"kod":"2.4","joy":"E"},{"kod":"2.4","joy":"W"}],"avto":[{"id":"A","joy":"S","y":"togri"},{"id":"B","joy":"E","y":"togri"}]}},"q":"Svetofor ishlamasa va tartibga soluvchi bo'lmasa, chorraha tartibga solinmagan hisoblanadi va imtiyoz belgilariga amal qilinadi.","e":"Svetofor o'chdi — belgilar uyg'ondi: endi 2.1 va 2.4 hal qiladi."},{"id":108,"m":"chorraha","s":"Tartibga solinmagan teng ahamiyatli yo'llar chorrahasi (imtiyoz belgilari yo'q, qoplama bir xil). Avtomobillar qanday tartibda o'tadi?","v":["Avval A, keyin B","Avval B, keyin A","A va B bir vaqtda"],"j":1,"i":"Chapga burilayotgan A qarama-qarshi yo'nalishdan nafaqat to'g'riga, balki o'ngga burilayotgan transport vositalariga ham yo'l beradi (YHQ, 107-band).","r":{"sahna":{"tur":"X","avto":[{"id":"A","joy":"S","y":"chap"},{"id":"B","joy":"N","y":"ong"}]}},"q":"Chapga burilayotgan haydovchi qarama-qarshidan nafaqat to'g'riga, balki o'ngga burilayotganlarga ham yo'l beradi.","e":"Tuzoq: qarshidagi o'ngga burilsa ham, chapga buriluvchi baribir kutadi."},{"id":109,"m":"chorraha","s":"Svetoforning yashil ishorasi yonib turibdi, lekin chorrahadan keyin tirbandlik bor. Chorrahaga kirsangiz, unda to'xtab qolib, ko'ndalang yo'nalishdagi transport vositalariga xalaqit berasiz. Qanday harakat qilasiz?","v":["Yashil ishora ruxsat bergani uchun chorrahaga kiraman","Chorraha o'rtasigacha kirib, o'sha yerda kutaman","Chorrahaga kirmasdan, to'xtash chizig'i oldida kutaman"],"j":2,"i":"Tirbandlik tufayli chorrahada to'xtab qolib, ko'ndalang yo'nalishdagi transport vositalarining harakatiga xalaqit beradigan bo'lsa, haydovchiga chorrahaga kirish taqiqlanadi (YHQ, 97-band).","q":"Tirbandlik tufayli chorrahada to'xtab qolib ko'ndalang harakatga xalaqit beradigan bo'lsa, yashilda ham chorrahaga kirish taqiqlanadi.","e":"Chorrahadan chiqa olmasang — kirma: tirbandlikda to'xtash chizig'i oldida kut."},{"id":110,"m":"chorraha","s":"Hovlidan (yondosh hududdan) yo'lga chiqish joyi chorraha hisoblanadimi va undan chiqayotgan haydovchi kimga yo'l beradi?","v":["Chorraha hisoblanadi; o'ngdan yaqinlashayotganlarga yo'l beradi","Chorraha hisoblanmaydi; yo'ldagi transport vositalari va piyodalarga yo'l beradi","Chorraha hisoblanmaydi; faqat piyodalarga yo'l beradi"],"j":1,"i":"Yondosh hududlardan chiqish joylari chorraha hisoblanmaydi. Yondosh hududdan yo'lga chiqayotgan haydovchi yo'lda harakatlanayotgan piyodalar va transport vositalariga yo'l beradi (YHQ, 6 va 54-bandlar).","q":"Yondosh hududdan chiqish joyi chorraha hisoblanmaydi; undan chiqayotgan haydovchi yo'ldagi transport vositalari va piyodalarga yo'l beradi.","e":"Hovlidan chiqqan — hammaga yo'l beradi: o'ngdagiga ham, chapdagiga ham, piyodaga ham."},{"id":111,"m":"chorraha","s":"Kechasi qor bilan qoplangan yo'lda tartibga solinmagan chorrahaga yaqinlashyapsiz. Imtiyoz belgilari yo'q, yo'l qoplamasi qattiq yoki tuproq ekanini aniqlab bo'lmaydi. Haydovchi o'zini qanday yo'lda deb hisoblaydi?","v":["Ikkinchi darajali yo'lda","Asosiy yo'lda","Teng ahamiyatli yo'lda"],"j":0,"i":"Qoplama turini aniqlab bo'lmasa (qorong'ilik, loy, qor va hokazo) va imtiyoz belgilari bo'lmasa, haydovchi o'zini ikkinchi darajali yo'lda deb hisoblashi kerak (YHQ, 108-band).","q":"Qoplama turini aniqlab bo'lmasa (qorong'ilik, loy, qor) va imtiyoz belgisi yo'q bo'lsa, haydovchi o'zini ikkinchi darajali yo'lda biladi.","e":"Shubha bo'lsa — o'zingni 'ikkinchi' deb bil va yo'l ber."},{"id":112,"m":"chorraha","s":"Aylanma harakatlanish tashkil etilgan chorrahada imtiyoz belgilari yo'q. Kim imtiyozga ega?","v":["Aylanaga kirib kelayotgan transport vositalari, chunki ular o'ng tomondan yaqinlashadi","Kengroq yo'ldan kirib kelayotgan transport vositalari","Aylana bo'ylab harakatlanayotgan transport vositalari"],"j":2,"i":"Aylanma harakatlanish chorrahasida aylana bo'ylab harakatlanayotgan transport vositalari aylanaga kirib kelayotgan transport vositalariga nisbatan imtiyozga ega (YHQ, 98-band).","q":"Aylanma harakatlanish chorrahasida aylana bo'ylab harakatlanayotganlar aylanaga kirib kelayotganlarga nisbatan imtiyozga ega.","e":"Tuzoq: aylanaga kirayotgan o'ngdan kelsa ham, imtiyoz aylanadagida."},{"id":113,"m":"chorraha","s":"Siz uchun svetoforning yashil ishorasi endi yondi. Chorrahada esa ko'ndalang yo'nalishdagi avtomobil o'tishni tugallamoqda. Qanday harakat qilasiz?","v":["Chorrahadan o'tishni tugallayotgan avtomobilga yo'l beraman","Yashil ishora yongani uchun darhol harakatni boshlayman","Tovushli ishora berib, uni shoshiltiraman"],"j":0,"i":"Ruxsat etuvchi ishora yonganda ham haydovchi chorrahadan o'tishni tugallayotgan transport vositalari va piyodalarga yo'l berishi kerak (YHQ, 103-band).","q":"Ruxsat etuvchi ishora yonganda ham haydovchi chorrahadan o'tishni tugallayotgan transport vositalari va piyodalarga yo'l beradi.","e":"Yashil yondi — avval chorraha bo'shasin: kechikkanlar chiqib ketsin, keyin sen."},{"id":114,"m":"ishora","s":"Svetoforning miltillovchi yashil ishorasi nimani bildiradi?","v":["Harakatlanish taqiqlanadi","Faqat o'ngga burilishga ruxsat beriladi","Harakatlanishga ruxsat beradi va ruxsat vaqti tugayotganini bildiradi","Chorraha tartibga solinmaganini bildiradi"],"j":2,"i":"Miltillovchi yashil ishora harakatlanishga ruxsat beradi va uning amal qilish vaqti tugayotgani, tez orada taqiqlovchi ishora yonishi haqida xabar beradi (YHQ, 31-band).","q":"Miltillovchi yashil ishora harakatlanishga ruxsat beradi va ruxsat vaqti tugab, tez orada taqiqlovchi ishora yonishini bildiradi.","e":"Miltillovchi yashil — 'oxirgi soniyalar': hali ruxsat, lekin tez orada taqiq."},{"id":115,"m":"ishora","s":"Yashil ishoradan keyin sariq ishora yondi. A haydovchisi to'xtash chizig'i oldida keskin tormoz bermasdan bemalol to'xtay oladi. U nima qilishi kerak?","v":["To'xtash chizig'i oldida to'xtashi","Tezlikni oshirib, chorrahadan o'tib ketishi","Ehtiyot bo'lib harakatni davom ettirishi"],"j":0,"i":"Sariq ishora harakatlanishni taqiqlaydi. Faqat keskin tormoz bermasdan to'xtay olmaydigan haydovchiga harakatni davom ettirishga ruxsat beriladi (YHQ, 31 va 42-bandlar).","r":{"sahna":{"tur":"X","svetofor":{"S":"sariq","N":"sariq","E":"qizil","W":"qizil"},"avto":[{"id":"A","joy":"S","y":"togri"}]}},"q":"Sariq ishora harakatlanishni taqiqlaydi; faqat keskin tormoz bermasdan to'xtay olmaydigan haydovchi harakatni davom ettirishi mumkin.","e":"Sariq — 'qizilning ukasi': to'xtay olsang, to'xta."},{"id":116,"m":"ishora","s":"Chorrahadagi svetoforda sariq ishora miltillab turibdi. Bu nimani bildiradi?","v":["Harakatlanish taqiqlanadi","Tez orada yashil ishora yonadi, uni kutish kerak","Faqat to'g'riga harakatlanishga ruxsat beriladi","Ehtiyot bo'lib harakatlanishga ruxsat beriladi; chorraha tartibga solinmagan hisoblanadi"],"j":3,"i":"Miltillovchi sariq ishora ehtiyot bo'lib harakatlanishga ruxsat beradi va tartibga solinmagan chorraha haqida xabar beradi. Bunday chorrahada imtiyoz belgilariga amal qilinadi (YHQ, 31 va 98-bandlar).","q":"Miltillovchi sariq ishora ehtiyot bo'lib harakatlanishga ruxsat beradi; bunday chorraha tartibga solinmagan, imtiyoz belgilari amal qiladi.","e":"Sariq miltillasa — svetofor 'dam olmoqda': belgilarga qara."},{"id":117,"m":"ishora","s":"Svetoforda qizil va sariq ishoralar birga yonib turibdi. Bu nimani bildiradi?","v":["Harakatlanishga ruxsat beriladi","Harakatlanish taqiqlanadi, tez orada yashil ishora yonadi","Ehtiyot bo'lib harakatlanish mumkin","Svetofor nosoz, chorraha tartibga solinmagan"],"j":1,"i":"Qizil va sariq ishoralarning birga yonishi harakatlanishni taqiqlaydi va tez orada yashil ishora yonishi haqida xabar beradi (YHQ, 31-band).","q":"Qizil va sariq ishoralar birga yonsa, harakatlanish taqiqlanadi va tez orada yashil ishora yonishini bildiradi.","e":"Qizil+sariq — 'tayyorlan, lekin hali yurma': yashil yonmaguncha joyingdan qo'zg'alma."},{"id":118,"m":"ishora","s":"A haydovchisi svetoforning qo'shimcha tarmog'idagi yashil strelka bo'yicha o'ngga burilmoqda, B uchun esa yashil ishora yonib turibdi. Kim birinchi o'tadi?","v":["A, chunki strelka unga alohida ruxsat bergan","Ikkalasi bir vaqtda, chunki ikkalasiga ham ruxsat berilgan","B"],"j":2,"i":"Qizil yoki sariq ishora bilan birga yongan qo'shimcha tarmoq strelkasi bo'yicha harakatlanayotgan haydovchi boshqa yo'nalishlardan kelayotgan transport vositalariga yo'l beradi (YHQ, 100-band).","r":{"sahna":{"tur":"X","svetofor":{"S":"yashil-o'q","N":"qizil","W":"yashil","E":"yashil"},"avto":[{"id":"A","joy":"S","y":"ong"},{"id":"B","joy":"W","y":"togri"}]}},"q":"Qizil yoki sariq bilan birga yongan qo'shimcha tarmoq strelkasi bo'yicha yurgan haydovchi boshqa yo'nalishlardagilarga yo'l beradi.","e":"Strelka — ruxsatnoma, imtiyoz emas: boshqa yo'nalishdan kelgan har kimga yo'l ber."},{"id":119,"m":"ishora","s":"Svetoforda rasmdagi ishoralar yonib turibdi. A haydovchisi to'g'riga harakatlanmoqchi. Bunga ruxsat beriladimi?","v":["Ha, chunki svetoforda yashil ishora yonib turibdi","Yo'q: asosiy qizil ishora taqiqlaydi, yashil strelka faqat o'ngga burilishga ruxsat beradi","Ha, agar ko'ndalang yo'nalishda transport vositalari bo'lmasa"],"j":1,"i":"Qizil ishora harakatlanishni taqiqlaydi. Strelkali ishora faqat o'zi ko'rsatgan yo'nalishga ta'sir qiladi, shuning uchun qo'shimcha tarmoqning yashil strelkasi faqat o'ngga burilishga ruxsat beradi (YHQ, 31 va 32-bandlar).","r":{"sahna":{"tur":"X","svetofor":{"S":"yashil-o'q","N":"qizil","E":"yashil","W":"yashil"},"avto":[{"id":"A","joy":"S","y":"togri"}]}},"q":"Strelkali ishora faqat o'zi ko'rsatgan yo'nalishga ta'sir qiladi: asosiy qizil yonib tursa, strelka boshqa yo'nalishga ruxsat bermaydi.","e":"Strelka qayoqqa qarasa — faqat o'sha yoqqa yo'l ochiq; qolgani qizilga bo'ysunadi."},{"id":120,"m":"ishora","s":"Tartibga soluvchi qo'llarini yonga uzatgan. Siz unga ko'krak tomonidan yaqinlashyapsiz. Qanday harakat qilasiz?","v":["To'xtayman: harakatlanish taqiqlanadi","To'g'riga va o'ngga harakatlanaman","Faqat o'ngga burilaman"],"j":0,"i":"Qo'llar yonga uzatilgan yoki tushirilgan bo'lsa, ko'krak va orqa tomondan barcha transport vositalari va piyodalarga harakatlanish taqiqlanadi (YHQ, 38-band).","q":"Tartibga soluvchi qo'llarini yonga uzatgan yoki tushirgan bo'lsa, ko'krak va orqa tomondan harakatlanish taqiqlanadi.","e":"Qo'llar yonda: ko'krak va orqa — devor, yonlar — ochiq eshik."},{"id":121,"m":"ishora","s":"Tartibga soluvchi qo'llarini yonga uzatgan, siz esa yengil avtomobilda unga chap yon tomondan yaqinlashyapsiz. Qaysi yo'nalishlarda harakatlanishingiz mumkin?","v":["Faqat to'g'riga","Barcha yo'nalishlarda","Faqat chapga","To'g'riga va o'ngga"],"j":3,"i":"Qo'llar yonga uzatilgan holatda chap va o'ng yon tomondan relssiz transport vositalariga to'g'riga va o'ngga, tramvayga esa faqat to'g'riga harakatlanishga ruxsat beriladi (YHQ, 38-band).","q":"Qo'llar yonga uzatilganda chap va o'ng yon tomondan relssiz transportga to'g'riga va o'ngga, tramvayga faqat to'g'riga ruxsat beriladi.","e":"Tuzoq: yondan kelganga chapga burilish mumkin emas — faqat to'g'ri va o'ngga."},{"id":122,"m":"ishora","s":"Tartibga soluvchi o'ng qo'lini oldinga cho'zgan. Siz yengil avtomobilda unga chap yon tomondan yaqinlashyapsiz. Qaysi yo'nalishlarda harakatlanishingiz mumkin?","v":["Faqat o'ngga","Barcha yo'nalishlarda","Faqat chapga","Harakatlanish taqiqlanadi"],"j":1,"i":"O'ng qo'l oldinga cho'zilganda chap yon tomondan relssiz transport vositalariga barcha yo'nalishlarda, tramvayga faqat chapga harakatlanishga ruxsat beriladi (YHQ, 38-band).","q":"O'ng qo'l oldinga cho'zilganda chap yon tomondan relssiz transportga barcha yo'nalishlarda, tramvayga faqat chapga harakatlanishga ruxsat.","e":"Tayoqcha chap tomoningni ko'rsatsa — relssiz vositaga istalgan yo'nalish ochiq."},{"id":123,"m":"ishora","s":"Tartibga soluvchi o'ng qo'lini oldinga cho'zgan va siz unga ko'krak tomonidan yaqinlashyapsiz. Qayerga harakatlanishingiz mumkin?","v":["To'g'riga va o'ngga","Faqat chapga","Harakatlanish taqiqlanadi","Faqat o'ngga"],"j":3,"i":"O'ng qo'l oldinga cho'zilganda ko'krak tomondan barcha transport vositalariga faqat o'ngga harakatlanishga ruxsat beriladi (YHQ, 38-band).","q":"O'ng qo'l oldinga cho'zilganda ko'krak tomondan barcha transport vositalariga faqat o'ngga harakatlanishga ruxsat beriladi.","e":"Qo'l (tayoqcha) yuzingga qarab tursa — faqat o'ngga buril."},{"id":124,"m":"ishora","s":"Tartibga soluvchi qo'lini yuqoriga ko'tardi. Shu paytda siz chorrahaga juda yaqin kelib qoldingiz va keskin tormoz bermasdan to'xtay olmaysiz. Qanday harakat qilasiz?","v":["Harakatni davom ettirishim mumkin","Keskin tormoz berib, har qanday holatda to'xtayman","Orqaga yurib, to'xtash chizig'i oldiga qaytaman"],"j":0,"i":"Qo'l yuqoriga ko'tarilganda barcha yo'nalishlarda harakatlanish taqiqlanadi. Biroq belgilangan joyda keskin tormoz bermasdan to'xtay olmaydigan haydovchi harakatni davom ettirishi mumkin (YHQ, 38 va 42-bandlar).","q":"Tartibga soluvchi qo'lini yuqoriga ko'tarsa, harakat taqiqlanadi; keskin tormozsiz to'xtay olmaydigan haydovchi harakatni davom ettiradi.","e":"Ko'tarilgan qo'l = sariq ishora: to'xtay olsang to'xta, keskin tormozsiz olmasang — davom et."},{"id":125,"m":"ishora","s":"Chorrahada svetoforning qizil ishorasi yonib turibdi, tartibga soluvchi esa sizga harakatlanishga ruxsat beruvchi ishora bermoqda. Qanday harakat qilasiz?","v":["Svetoforga amal qilib, to'xtab turaman","Tartibga soluvchining ishorasiga amal qilib, harakatlanaman","Yashil ishora yonishini kutaman"],"j":1,"i":"Tartibga soluvchining ishoralari va ko'rsatmalari svetofor ishoralari, yo'l belgilari va chiziqlari talablariga zid bo'lsa, tartibga soluvchiga amal qilinadi (YHQ, 43-band).","q":"Tartibga soluvchining ishoralari svetofor ishoralari, yo'l belgilari va chiziqlar talablariga zid bo'lsa, tartibga soluvchiga amal qilinadi.","e":"Tirik odam svetofordan kuchli: tartibga soluvchi bor joyda u aytganini qil."},{"id":126,"m":"ishora","s":"Chorrahaga kirishda rasmdagi belgi o'rnatilgan, lekin svetofor ishlab turibdi va sizga yashil ishora yonmoqda. Nimaga amal qilasiz?","v":["Belgiga: ko'ndalang yo'ldagilarga yo'l beraman","Svetofor ishorasiga","Ikkalasiga: to'xtab olib, keyin yashil ishorada harakatlanaman"],"j":1,"i":"Svetofor ishoralari imtiyoz belgilari talablariga zid bo'lsa, haydovchilar svetofor ishoralariga amal qiladi (YHQ, 43-band).","r":{"b":"2.4"},"q":"Svetofor ishoralari imtiyoz belgilari talablariga zid bo'lsa, haydovchilar svetofor ishoralariga amal qiladi.","e":"Imtiyoz belgisi — 'zaxira o'yinchi': svetofor o'chsa yoki sariq miltillasa, maydonga chiqadi."},{"id":127,"m":"ishora","s":"Chorrahada svetoforning qizil ishorasi yonib turibdi, to'xtash chizig'i ham, uni bildiruvchi belgi ham yo'q. Haydovchi qayerda to'xtashi kerak?","v":["Kesib o'tiladigan qatnov qismi oldida, piyodalarga xalaqit bermasdan","Svetofor ustuni yonida, chorraha ichida","Svetofordan kamida 10 metr oldin","Piyodalar o'tish joyi ustida"],"j":0,"i":"Taqiqlovchi ishorada to'xtash chizig'i bo'lmasa, chorrahada kesib o'tiladigan qatnov qismi oldida piyodalarga xalaqit bermasdan to'xtaladi (YHQ, 41-band).","q":"Taqiqlovchi ishorada to'xtash chizig'i bo'lmasa, chorrahada kesib o'tiladigan qatnov qismi oldida, piyodalarga xalaqit bermasdan to'xtaladi.","e":"Chiziq bo'lmasa, chegara — kesishayotgan yo'lning cheti; piyoda yo'lini to'sib qo'yma."},{"id":128,"m":"ishora","s":"Siz yashil ishorada chorrahaga kirib, chapga burilish uchun qarama-qarshi oqimni o'tkazib turibsiz. Chorraha ichida to'xtash chizig'i yo'q. Shu payt svetoforda qizil ishora yondi. Qanday harakat qilasiz?","v":["Chorrahada keyingi yashil ishorani kutaman","Orqaga yurib, to'xtash chizig'i oldiga qaytaman","Mo'ljallangan yo'nalishda harakatlanib, chorrahadan chiqaman"],"j":2,"i":"Ruxsat etuvchi ishorada chorrahaga kirgan haydovchi chiqishdagi svetofor ishoralaridan qat'i nazar mo'ljallangan yo'nalishda harakatni davom ettiradi. Boshqalar esa chorrahadan o'tishni tugallayotgan transport vositalariga yo'l beradi (YHQ, 102 va 103-bandlar).","q":"Yashilda chorrahaga kirgan haydovchi (ichkarida to'xtash chizig'i bo'lmasa) qizil yonsa ham mo'ljallangan yo'nalishda chorrahadan chiqadi.","e":"Kirding — chiqib ket: chorrahada keyingi yashilni kutma, orqaga ham yurma."},{"id":129,"m":"manevr","s":"Qatnov qismining o'ng chetida to'xtab turgan avtomobil haydovchisi harakatni boshlamoqchi. U nima qilishi kerak?","v":["O'ng burilish ko'rsatkichini yoqib, darhol harakatni boshlaydi","Tovushli ishora berib, harakatni boshlaydi","Chap burilish ko'rsatkichini yoqadi va manyovr boshqalarga xavf tug'dirmasligiga ishonch hosil qilib harakatlanadi","Ko'rsatkich yoqmasdan, sekin harakatni boshlaydi"],"j":2,"i":"Harakatni boshlashdan oldin tegishli yo'nalishdagi burilish ko'rsatkichi yoqiladi, bajarilayotgan manyovr esa boshqa yo'l harakati ishtirokchilariga xavf tug'dirmasligi kerak (YHQ, 45 va 53-bandlar).","q":"Harakatni boshlashdan oldin tegishli burilish ko'rsatkichi yoqiladi va manyovr boshqalarga xavf tug'dirmasligiga ishonch hosil qilinadi.","e":"O'ng chetdan chiqyapsanmi — chap ko'rsatkich: oqim sening chap tomoningda."},{"id":130,"m":"manevr","s":"Burilish ko'rsatkichlari ishlamayapti. Haydovchi o'ng qo'lini tirsakdan to'g'ri burchak ostida bukib, yuqoriga ko'tardi. Bu ishora nimani bildiradi?","v":["O'ngga burilishni","Chapga burilish yoki qayrilib olishni","To'xtashni","Orqadagilarga quvib o'tishga ruxsatni"],"j":1,"i":"Chapga burilish yoki qayrilib olish ishorasi: chap qo'l yonga uzatiladi yoki o'ng qo'l tirsakdan to'g'ri burchak ostida bukilib yuqoriga ko'tariladi (YHQ, 45-band).","q":"Chapga burilish yoki qayrilib olish ishorasi: chap qo'l yonga uzatiladi yoki o'ng qo'l tirsakdan to'g'ri burchak ostida bukib ko'tariladi.","e":"Bukilgan qo'l — teskari yo'nalish: o'ng qo'l bukilsa chapga, chap qo'l bukilsa o'ngga."},{"id":131,"m":"manevr","s":"Haydovchi qo'l bilan to'xtash ishorasini qanday beradi?","v":["Chap qo'lni yonga uzatadi","O'ng qo'lni tirsakdan bukib, yuqoriga ko'taradi","Chap qo'lni pastga tushirib, orqaga silkitadi","Chap yoki o'ng qo'lni yuqoriga ko'taradi"],"j":3,"i":"To'xtash ishorasi chap yoki o'ng qo'lni yuqoriga ko'tarish bilan beriladi (YHQ, 45-band).","q":"Haydovchi to'xtash ishorasini chap yoki o'ng qo'lini yuqoriga ko'tarib beradi.","e":"Qo'l tik yuqoriga — 'to'xtayman'; yonga uzatilgan yoki bukilgan — burilish."},{"id":132,"m":"manevr","s":"Burilish ko'rsatkichi haqida qaysi fikr to'g'ri?","v":["Ko'rsatkichni yoqqan haydovchi imtiyozga ega bo'ladi","Ko'rsatkich manyovrdan oldinroq yoqiladi va manyovr tugagach darhol o'chiriladi; u imtiyoz bermaydi","Ko'rsatkich manyovr boshlanganidan keyin yoqiladi","Ko'rsatkich keyingi chorrahagacha o'chirilmaydi"],"j":1,"i":"Ishora manyovr boshlanishidan oldinroq beriladi va u tugagach darhol to'xtatiladi. Ishora haydovchiga imtiyoz bermaydi va uni ehtiyot choralarini ko'rishdan ozod qilmaydi (YHQ, 46-band).","q":"Burilish ishorasi manyovrdan oldinroq beriladi, tugagach darhol o'chiriladi va haydovchiga imtiyoz bermaydi.","e":"Ko'rsatkich — iltimos, buyruq emas: uni yoqding deb boshqalar yo'l berishi shart emas."},{"id":133,"m":"manevr","s":"Siz chap tasmaga qayta tizilmoqchisiz. O'sha tasmada orqadan avtomobil yaqinlashmoqda. Nima qilasiz?","v":["Ko'rsatkichni yoqib, darhol qayta tizilaman, u sekinlashishi kerak","Tovushli ishora berib, qayta tizilaman","O'sha tasmada harakatlanayotgan avtomobilga yo'l beraman"],"j":2,"i":"Qayta tizilishda haydovchi harakat yo'nalishini o'zgartirmasdan o'sha tasmada harakatlanayotgan yo'lakay transport vositalariga yo'l berishi kerak (YHQ, 55-band).","q":"Qayta tizilayotgan haydovchi o'tmoqchi bo'lgan tasmada yo'nalishini o'zgartirmay harakatlanayotgan transport vositalariga yo'l beradi.","e":"Begona tasma — begona uy: kirishdan oldin uning egasini o'tkazib yubor."},{"id":134,"m":"manevr","s":"Bir yo'nalishda uch tasmali yo'lda chetki o'ng va chetki chap tasmalardagi ikki avtomobil bir vaqtda o'rta tasmaga qayta tizilmoqda. Kim yo'l beradi?","v":["Chapdagi avtomobil o'ngdagiga","O'ngdagi avtomobil chapdagiga","Tezligi kamroq bo'lgan avtomobil"],"j":0,"i":"Bir yo'nalishda harakatlanayotgan transport vositalari bir vaqtda qayta tizilganda haydovchi o'ng tomondagi transport vositasiga yo'l beradi (YHQ, 55-band).","q":"Bir yo'nalishdagi transport vositalari bir vaqtda qayta tizilganda haydovchi o'ng tomondagi transport vositasiga yo'l beradi.","e":"Bu yerda ham 'o'ng qoidasi': o'ngdagi oldin, chapdagi kutadi."},{"id":135,"m":"manevr","s":"Belgilar yoki chiziqlar boshqa tartib o'rnatmagan. Chapga burilishdan oldin haydovchi qatnov qismida qanday joylashishi kerak?","v":["Istalgan tasmada bo'lishi mumkin","Chetki o'ng tasmada qolib, chorrahada chapga burilishi kerak","Qarama-qarshi yo'nalish tasmasiga chiqib olishi kerak","Shu yo'nalishdagi qatnov qismining chetki chap holatini oldindan egallashi kerak"],"j":3,"i":"O'ngga yoki chapga burilish va qayrilib olishdan oldin haydovchi shu yo'nalishga mo'ljallangan qatnov qismining tegishli chetki holatini oldindan egallashi shart (YHQ, 56-band).","q":"Burilish va qayrilib olishdan oldin haydovchi shu yo'nalishga mo'ljallangan qatnov qismining tegishli chetki holatini oldindan egallaydi.","e":"Chapga — chetki chapdan, o'ngga — chetki o'ngdan: qayerga burilsang, o'sha chetga oldindan o't."},{"id":136,"m":"manevr","s":"Qatnov qismining o'rtasida, u bilan bir sathda bir yo'nalishdagi tramvay izi bor. Tasmalar bo'yicha yo'nalishni ko'rsatuvchi belgi va chiziqlar yo'q. Chapga burilishni qayerdan bajarish mumkin?","v":["Tramvay izidan ham, agar bu tramvay harakatiga xalaqit bermasa","Faqat tramvay izining o'ng tomonidagi tasmadan","Faqat chetki o'ng tasmadan"],"j":0,"i":"5.8.1, 5.8.2 belgilari yoki 1.18 chizig'i boshqa tartib o'rnatmagan bo'lsa, qatnov qismi o'rtasida u bilan bir sathda joylashgan bir yo'nalishdagi tramvay izidan chapga burilish va qayrilib olishga ruxsat etiladi. Bunda tramvay harakatiga xalaqit berilmasligi kerak (YHQ, 56-band).","q":"Belgi/chiziq boshqacha ko'rsatmasa, o'rtadagi bir sathli, bir yo'nalishdagi tramvay izidan tramvayga xalaqit bermay chapga burilish mumkin.","e":"Tramvay izi ham chetki chap holat bo'la oladi, lekin rels egasi — tramvay: unga to'sqinlik qilma."},{"id":137,"m":"manevr","s":"O'ngga burilishni qanday bajarish kerak?","v":["Keng radius bilan, yo'lning o'rtasidan","Imkon qadar qatnov qismining o'ng chetiga yaqin harakatlanib, qarama-qarshi yo'nalish tomoniga chiqmasdan","Burilgandan keyin istalgan tasmani, jumladan qarama-qarshi yo'nalish tasmasini egallab"],"j":1,"i":"Burilish shunday bajariladiki, qatnov qismlari kesishmasidan chiqishda transport vositasi qarama-qarshi yo'nalish tomoniga o'tib qolmaydi; o'ngga burilishda imkon qadar qatnov qismining o'ng chetiga yaqin harakatlaniladi (YHQ, 57-band).","q":"O'ngga burilish imkon qadar qatnov qismining o'ng chetiga yaqin bajariladi; chiqishda qarama-qarshi yo'nalish tomoniga o'tilmaydi.","e":"O'ngga burilish — chetni 'yalab' o'tish: keng aylanib, qarshidagi tasmaga chiqma."},{"id":138,"m":"manevr","s":"Chorrahadan tashqarida qatnov qismining kengligi chetki chap holatdan qayrilib olishga yetmaydi. Haydovchi qayrilib olishni qanday bajaradi?","v":["Qatnov qismining o'ng chetidan qayrilib oladi va bir yo'nalishdagi hamda qarama-qarshi yo'nalishdagi transport vositalariga yo'l beradi","Bunday joyda qayrilib olish taqiqlanadi","O'ng chetdan qayrilib oladi va faqat qarama-qarshi yo'nalishdagilarga yo'l beradi"],"j":0,"i":"Qatnov qismi kengligi chetki chap holatdan qayrilib olishga yetmasa, buni qatnov qismining o'ng chetidan bajarishga ruxsat etiladi. Bunda haydovchi bir yo'nalishdagi va qarama-qarshi yo'nalishdagi transport vositalariga yo'l beradi (YHQ, 59-band).","q":"Qatnov qismi chetki chap holatdan qayrilib olishga tor bo'lsa, o'ng chetdan qayriladi va ikki yo'nalishdagilarga yo'l beriladi.","e":"O'ng chetdan qayrilsang — hamma sendan oldin: yo'ldoshlar ham, qarshidagilar ham."},{"id":139,"m":"manevr","s":"Yo'lning ko'rinishi kamida bir yo'nalishda qancha masofadan kam bo'lsa, qayrilib olish taqiqlanadi?","v":["50 m","100 m","150 m","300 m"],"j":1,"i":"Yo'lning ko'rinishi hech bo'lmaganda bir yo'nalishda 100 metrdan kam bo'lgan joylarda qayrilib olish taqiqlanadi (YHQ, 62-band).","q":"Yo'lning ko'rinishi hech bo'lmaganda bir yo'nalishda 100 m dan kam bo'lgan joylarda qayrilib olish taqiqlanadi.","e":"Yuz metr ko'rinmasa — qayrilish yuz foiz taqiq."},{"id":140,"m":"manevr","s":"Qaysi joyda orqaga harakatlanish taqiqlanadi?","v":["Turar joy dahasida","Yonilg'i quyish shoxobchasi hududida","Hovlida (yondosh hududda)","Chorrahada"],"j":3,"i":"Orqaga harakatlanish chorrahalarda va qayrilib olish taqiqlangan joylarda (piyodalar o'tish joylari, tunnellar, ko'priklar, temir yo'l kesishmalari va boshqalar) taqiqlanadi (YHQ, 63-band).","q":"Orqaga harakatlanish chorrahalarda va qayrilib olish taqiqlangan joylarda taqiqlanadi.","e":"Qayrilib bo'lmaydigan joyda orqaga ham yurilmaydi; chorrahada ham."},{"id":141,"m":"manevr","s":"Yo'lga chiqish joyida tezlashish bo'lagi bor. Haydovchi asosiy oqimga qanday qo'shiladi?","v":["Tezlashish bo'lagiga kirmasdan, darhol asosiy tasmaga chiqadi","Tezlashish bo'lagida harakatlanadi, asosiy tasmadagilar unga yo'l berishi shart","Tezlashish bo'lagida harakatlanib, qo'shni tasmadagi transport vositalariga yo'l berib oqimga qo'shiladi"],"j":2,"i":"Yo'lga chiqish joyida tezlashish bo'lagi bo'lsa, haydovchi shu bo'lakda harakatlanadi va qo'shni tasmadagi transport vositalariga yo'l berib, oqimga qo'shiladi (YHQ, 61-band).","q":"Yo'lga chiqishda tezlashish bo'lagi bo'lsa, haydovchi shu bo'lakda harakatlanib, qo'shni tasmadagilarga yo'l berib oqimga qo'shiladi.","e":"Tezlashish bo'lagi — tezlik olish uchun, imtiyoz olish uchun emas: asosiy tasmadagilar oldin."},{"id":142,"m":"manevr","s":"Ikki tomonlama harakatli, chiziqlar bilan uch tasmaga ajratilgan yo'lda (1.9 chizig'i yo'q) o'rta tasmaga qachon chiqish mumkin?","v":["Faqat quvib o'tish, aylanib o'tish, chapga burilish yoki qayrilib olish uchun","Har doim, agar qarama-qarshi tomonda transport bo'lmasa","Faqat yuk avtomobillari uchun","Faqat quvib o'tish uchun"],"j":0,"i":"Ikki tomonlama harakatli, 1.9 chizig'idan boshqa chiziqlar bilan belgilangan uch tasmali yo'lda o'rta tasmaga faqat quvib o'tish, aylanib o'tish, chapga burilish yoki qayrilib olish uchun chiqiladi; chetki chap tasmani egallash taqiqlanadi (YHQ, 66-band).","q":"Ikki tomonlama uch tasmali yo'lda o'rta tasmaga faqat quvib, aylanib o'tish, chapga burilish yoki qayrilib olish uchun chiqiladi.","e":"O'rta tasma — ikki tomonning umumiy manyovr yo'lagi; chetki chap tasma esa — taqiq."},{"id":143,"m":"manevr","s":"Chap tasmaga qayta tizilish uchun ishora berishdan oldin haydovchi nimaga ishonch hosil qilishi kerak?","v":["Faqat oldindagi avtomobil tormoz bermayotganiga","Orqadan kelayotgan transport vositasi quvib yoki aylanib o'tishni boshlamaganiga","Faqat yo'lda piyodalar yo'qligiga"],"j":1,"i":"Ishora berishdan oldin haydovchi orqadan kelayotgan transport vositasi quvib yoki aylanib o'tishni boshlamaganiga va manyovr boshqalarga xalaqit bermasligiga ishonch hosil qiladi (YHQ, 47-band).","q":"Ishora berishdan oldin haydovchi orqadan kelayotgan transport vositasi quvib yoki aylanib o'tishni boshlamaganiga ishonch hosil qiladi.","e":"Avval ko'zgu, keyin ko'rsatkich, so'ng manyovr."},{"id":144,"m":"umumiy","s":"YHQ bo'yicha to'xtash bilan to'xtab turish bir-biridan nimasi bilan farq qiladi?","v":["To'xtash – harakatni 10 daqiqagacha to'xtatish; to'xtab turish – harakatni 10 daqiqadan ko'p atayin to'xtatish (yo'lovchi yoki yuk bilan bog'liq bo'lmagan maqsadda)","To'xtash – 5 daqiqagacha, to'xtab turish – 5 daqiqadan ko'p","To'xtash – 15 daqiqagacha, to'xtab turish – 15 daqiqadan ko'p","To'xtashda dvigatel ishlab turadi, to'xtab turishda dvigatel o'chiriladi"],"j":0,"i":"To'xtash – harakatni 10 daqiqagacha to'xtatish; to'xtab turish – harakatni 10 daqiqadan ko'proq vaqtga atayin to'xtatish (yo'lovchi chiqarish-tushirish yoki yuk ortish-tushirishdan boshqa maqsadda). (YHQ, 6-band)","q":"To'xtash — harakatni 10 daqiqagacha to'xtatish; to'xtab turish — 10 daqiqadan ko'p (yo'lovchi yoki yuk bilan bog'liq bo'lmagan maqsadda).","e":"10 daqiqa — chegara; yo'lovchi yoki yuk uchun uzoqroq turish ham to'xtab turish emas."},{"id":145,"m":"umumiy","s":"Quyidagi holatlardan qaysi biri majburiy to'xtash hisoblanadi?","v":["Yo'lovchini tushirish uchun 2 daqiqaga to'xtaldi","Dvigatel nosozligi sababli xavf tug'ilib, harakat to'xtatildi","Do'kondan non olish uchun 15 daqiqa to'xtab turildi","Telefonda gaplashish uchun yo'l chetida to'xtaldi"],"j":1,"i":"Majburiy to'xtash – texnik nosozlik, tashilayotgan yuk, haydovchi yoki yo'lovchining holati, to'siq yoki ob-havo sababli xavf tug'ilganda harakatni to'xtatish. (YHQ, 6-band)","q":"Majburiy to'xtash — texnik nosozlik, yuk, haydovchi yoki yo'lovchi holati, to'siq yoki ob-havo sababli xavf tug'ilganda to'xtash.","e":"Majburiy — 'xohlamay' to'xtash: sabab sendan emas, vaziyatdan."},{"id":146,"m":"umumiy","s":"Bir yo'nalishda ikki tasmali yo'lda siz chap tasmada ketyapsiz va o'ng tasmadagi sekin avtomobildan tezroq yurib, uni ortda qoldirdingiz. Qarama-qarshi yo'nalish tasmasiga chiqmadingiz. YHQ bo'yicha bu qanday ataladi?","v":["Quvib o'tish","Qayta tizilish","O'zib ketish","Aylanib o'tish"],"j":2,"i":"O'zib ketish – bir yo'nalishdagi transport vositasidan yuqoriroq tezlikda harakatlanib uni o'tib ketish. Quvib o'tish esa qarama-qarshi yo'nalishga mo'ljallangan tasmaga chiqish bilan bog'liq. (YHQ, 6-band)","q":"O'zib ketish — bir yo'nalishdagi transport vositasidan tezroq yurib uni o'tib ketish; quvib o'tishda qarama-qarshi tasmaga chiqiladi.","e":"Qarshi tasmaga chiqdingmi — quvib o'tish; o'z tomoningda o'tdingmi — o'zib ketish."},{"id":147,"m":"umumiy","s":"Belgilar yo'q tartibga solinmagan chorrahaga yaqinlashyapsiz. Siz ketayotgan tuproqli yo'l chorrahadan 20 m oldin asfaltlangan, kesishayotgan yo'l esa butunlay asfalt. Qaysi yo'l asosiy hisoblanadi?","v":["Ikkala yo'l teng ahamiyatli, chunki chorraha oldida ikkalasi ham asfalt","Siz ketayotgan yo'l, chunki u chorrahaga asfalt bilan kiradi","Belgi bo'lmagani uchun ikkala yo'l ham ikkinchi darajali","Kesishayotgan asfalt yo'l; siz ikkinchi darajali yo'ldasiz"],"j":3,"i":"Tuproqli yoki shag'alli yo'lga nisbatan qattiq qoplamali yo'l asosiy hisoblanadi. Ikkinchi darajali yo'lning chorraha oldidagi qisqa qattiq qoplamali qismi uni asosiy yo'l bilan teng qilmaydi. (YHQ, 6-band)","q":"Tuproqli yo'lga nisbatan qattiq qoplamali yo'l asosiy; ikkinchi darajali yo'lning chorraha oldidagi qisqa qoplamali qismi uni teng qilmaydi.","e":"Tuzoq: chorraha oldidagi qisqa asfalt 'yamoq' tuproq yo'lni asosiyga aylantirmaydi."},{"id":148,"m":"umumiy","s":"Ko'p qavatli uylar hovlisidan chiqadigan yo'lning ko'cha bilan tutashgan joyi YHQ bo'yicha chorraha hisoblanadimi?","v":["Yo'q, yondosh hududlardan chiqish joylari chorraha hisoblanmaydi","Ha, bu uch tomonlama chorraha","Ha, agar hovli yo'li asfaltlangan bo'lsa","Faqat svetofor o'rnatilgan bo'lsa chorraha hisoblanadi"],"j":0,"i":"Chorraha – yo'llarning bir sathda kesishadigan, tutashadigan yoki ayriladigan joyi; yondosh hududlardan chiqish joylari chorraha hisoblanmaydi. Hovlidan chiqayotgan haydovchi yo'ldagi transport vositalari va piyodalarga yo'l beradi. (YHQ, 6, 54-band)","q":"Yondosh hududlardan (hovli, avtomobil to'xtash joyi) chiqish joylari chorraha hisoblanmaydi.","e":"Hovli yo'li — 'darvoza', chorraha emas: darvozadan chiqqan hammaga yo'l beradi."},{"id":149,"m":"umumiy","s":"YHQ bo'yicha \"yo'l berish (to'sqinlik qilmaslik)\" talabi nimani anglatadi?","v":["Imtiyozga ega ishtirokchi ko'rinmasa ham, har doim to'liq to'xtash","Imtiyozga ega ishtirokchini yo'nalishi yoki tezligini o'zgartirishga majbur qiladigan bo'lsa, harakatni boshlamaslik, davom ettirmaslik va manyovr qilmaslik","Ovozli ishora berib, o'zidan oldin o'tishni so'rash","Faqat tezlikni 20 km/soatgacha kamaytirish"],"j":1,"i":"Yo'l berish – haydovchi o'z harakati bilan imtiyozli ishtirokchini yo'nalishi yoki tezligini o'zgartirishga majbur qilsa, harakatni davom ettirmasligi, boshlamasligi yoki manyovr qilmasligi talabi. (YHQ, 6-band)","q":"Yo'l berish: imtiyozli ishtirokchini yo'nalish yoki tezlikni o'zgartirishga majbur qilsang, harakatni boshlamaslik, davom ettirmaslik.","e":"Mezon — uning tormozi: sen tufayli u sekinlasa yoki burilsa, demak yo'l bermading."},{"id":150,"m":"umumiy","s":"YHQ bo'yicha \"yetarlicha ko'rinmaslik\" deganda yomg'ir, qor, tuman yoki g'ira-shira tufayli yo'l ko'rinishi qancha masofadan kam bo'lishi tushuniladi?","v":["50 m","100 m","200 m","300 m"],"j":3,"i":"Yetarlicha ko'rinmaslik – yomg'ir, qor, tuman va shu kabilar yoki g'ira-shira tufayli yo'l ko'rinishi 300 m dan kam bo'lishi. (YHQ, 6-band)","q":"Yetarlicha ko'rinmaslik — yomg'ir, qor, tuman va shu kabilar yoki g'ira-shira tufayli yo'l ko'rinishi 300 m dan kam bo'lishi.","e":"Tuzoq: 100 m (qayrilish taqiqi) bilan adashtirma — yetarlicha ko'rinmaslik 300 m dan kam."},{"id":151,"m":"umumiy","s":"Avtomobil egasi o'z avtomobilini boshqarmoqda. IIO xodimi talab qilganda ko'rsatish uchun uning yonida qaysi hujjatlar bo'lishi shart?","v":["Faqat haydovchilik guvohnomasi","Pasport va haydovchilik guvohnomasi","Tegishli toifadagi haydovchilik guvohnomasi, transport vositasini ro'yxatdan o'tkazish guvohnomasi va majburiy sug'urta polisi","Haydovchilik guvohnomasi va tibbiy ma'lumotnoma"],"j":2,"i":"Haydovchi haydovchilik guvohnomasini, transport vositasini (tirkama bo'lsa uni ham) ro'yxatdan o'tkazish guvohnomasini va fuqarolik javobgarligini majburiy sug'urta qilish polisini (elektron shaklda ham bo'lishi mumkin) olib yuradi. (YHQ, 7-band)","q":"Haydovchi haydovchilik guvohnomasi, transport vositasini ro'yxatdan o'tkazish guvohnomasi va majburiy sug'urta polisini olib yuradi.","e":"Uch hujjat: kim haydaydi (guvohnoma), qaysi mashina (ro'yxat guvohnomasi), zararni kim qoplaydi (polis)."},{"id":152,"m":"umumiy","s":"Yo'l-transport hodisasi sodir bo'ldi. Unga daxldor haydovchi darhol nima qilishi shart?","v":["Harakatga xalaqit bermaslik uchun vositani darhol yo'l chetiga surish","Eng yaqin IIO bo'limiga borib, voqea haqida xabar berish","Vositani ta'mirlash uchun ustaxonaga olib borish","Transport vositasini to'xtatish, avariya yorug'lik ishorasini yoqish, avariya sababli to'xtash belgisini qo'yish, vositani va hodisaga aloqador buyumlarni joyidan siljitmaslik"],"j":3,"i":"YTH sodir bo'lganda haydovchi darhol to'xtaydi, avariya ishoralarini yoqadi, 51-bandga muvofiq belgi qo'yadi va vositani hamda hodisaga aloqador buyumlarni joyidan siljitmaydi. (YHQ, 13-band)","q":"YTHda haydovchi darhol to'xtaydi, avariya chirog'ini yoqadi, avariya belgisini qo'yadi, vosita va aloqador buyumlarni joyidan siljitmaydi.","e":"To'xta — yoq — qo'y — qo'zg'atma: to'rt fe'l, to'rt qadam."},{"id":153,"m":"umumiy","s":"YTHda jabrlangan bor, uni tezda shifoxonaga yetkazish kerak, lekin yo'lda o'tayotgan transport vositasi bilan yuborishning imkoni yo'q. Haydovchi nima qilishi kerak?","v":["Jabrlanuvchini o'z vositasida eng yaqin tibbiyot muassasasiga olib borishi, u yerda ism-familiyasi va davlat raqamini aytib, hujjatlarini ko'rsatishi va voqea joyiga qaytishi","IIO xodimlari kelguncha jabrlanuvchini joyidan qo'zg'atmasligi","Jabrlanuvchini o'z vositasida shifoxonaga olib borib, so'ng uyiga ketishi","Jabrlanuvchini yo'l chetiga yotqizib, voqea joyidan ketishi"],"j":0,"i":"Shoshilinch hollarda jabrlanuvchi yo'lakay transport bilan, bu imkonsiz bo'lsa haydovchining o'z vositasida tibbiyot muassasasiga olib boriladi. Haydovchi u yerda o'z ma'lumotlarini aytadi, hujjatlarini ko'rsatadi va voqea joyiga qaytadi. (YHQ, 13-band)","q":"Yo'lakay transport bo'lmasa, haydovchi jabrlanuvchini o'zi tibbiyot muassasasiga olib boradi, ma'lumotlarini aytib, voqea joyiga qaytadi.","e":"Olib bor — tanishtir — qayt: shifoxona yo'li voqea joyiga qaytish bilan tugaydi."},{"id":154,"m":"umumiy","s":"Transport vositasini boshqarayotgan haydovchiga quyidagilardan qaysi biri ruxsat etiladi?","v":["Ozgina spirtli ichimlik ichgan holda ehtiyot bo'lib boshqarish","Qo'lni ishlatmaydigan quloqchin orqali telefonda gaplashish","Diqqatga ta'sir qiluvchi dori ichgan holda boshqarish","Telefonni qo'lda ushlab, qisqa gaplashish"],"j":1,"i":"Boshqaruv paytida telefondan foydalanish taqiqlanadi, qo'lni ishlatmaydigan quloqchin va shu kabilar orqali gaplashish bundan mustasno. Spirtli ichimlik yoki diqqatga ta'sir qiluvchi dorilar ta'sirida boshqarish taqiqlanadi. (YHQ, 12-band)","q":"Boshqaruv paytida telefondan foydalanish taqiqlanadi; qo'lni ishlatmaydigan quloqchin va shu kabilar orqali gaplashish mumkin.","e":"Qo'llar rulda bo'lsa — gaplash; telefon qo'lda bo'lsa — taqiq."},{"id":155,"m":"umumiy","s":"Qaysi holatda avtomobilda xavfsizlik kamarini taqmaslikka ruxsat etiladi?","v":["Aholi punktida qisqa masofaga ketayotgan haydovchiga","Old o'rindiqda o'tirgan 16 yoshli yo'lovchiga","Orqa o'rindiqda o'tirgan 10 yoshli bolaga","Taksining old o'rindig'idagi yo'lovchiga"],"j":2,"i":"Haydovchi va old o'rindiqdagi yo'lovchilar harakatdan oldin kamar taqishi shart. Orqa o'rindiqdagi 12 yoshgacha bolalar bu talabdan ozod. (YHQ, 9-band)","q":"Haydovchi va old o'rindiqdagi yo'lovchilar kamar taqishi shart; orqa o'rindiqdagi 12 yoshgacha bolalar bu talabdan ozod.","e":"Tuzoq: 'qisqa masofa' yoki 'taksi' — bahona emas; orqadagi 12 yoshgacha bola esa ozod."},{"id":156,"m":"tezlik","s":"Siz aholi punkti qoidalari amal qiladigan qishloqdasiz (u shahar ham, tuman markazi ham emas). Tezlikni cheklovchi belgilar yo'q. Yengil avtomobil uchun ruxsat etilgan eng yuqori tezlik qancha?","v":["60 km/soat","70 km/soat","80 km/soat","90 km/soat"],"j":1,"i":"Aholi punktlarida tezlik 70 km/soatdan oshmasligi kerak; 60 km/soat chegarasi Nukus, Toshkent, viloyat va tuman markazlari hamda shaharlar uchun belgilangan. (YHQ, 78-band)","q":"Aholi punktida tezlik 70 km/soatdan oshmaydi; shaharlarda, Nukus va Toshkentda, viloyat va tuman markazlarida — 60 km/soat.","e":"Qishloq — 70, shahar va markaz — 60: katta joyda tezlik kichik."},{"id":157,"m":"tezlik","s":"Siz ushbu belgidan o'tib shaharga kirdingiz. Tezlikni cheklovchi boshqa belgilar yo'q. Yengil avtomobil uchun ruxsat etilgan eng yuqori tezlik qancha?","v":["60 km/soat","70 km/soat","80 km/soat","90 km/soat"],"j":0,"i":"Nukus va Toshkent shaharlarida, viloyat va tuman markazlarida hamda shaharlar hududlarida tezlik 60 km/soatdan oshmasligi kerak. (YHQ, 78-band)","r":{"b":"5.22"},"q":"Shahar hududida, viloyat va tuman markazlarida tezlikni cheklovchi belgi bo'lmasa, eng yuqori tezlik 60 km/soat.","e":"Tuzoq: 5.22 belgisi tezlikni o'zi belgilamaydi — shaharda 60, oddiy aholi punktida 70."},{"id":158,"m":"tezlik","s":"Aholi punktidan tashqarida, tezlikni cheklovchi belgilar yo'q yo'lda yengil avtomobil uchun ruxsat etilgan eng yuqori tezlik qancha?","v":["80 km/soat","90 km/soat","100 km/soat","110 km/soat"],"j":2,"i":"Aholi punktidan tashqarida yengil avtomobillar va ruxsat etilgan to'liq vazni 3,5 t gacha bo'lgan yuk avtomobillari 100 km/soatdan oshmasdan harakatlanadi. (YHQ, 79-band)","q":"Aholi punktidan tashqarida yengil avtomobil va to'liq vazni 3,5 t gacha yuk avtomobili uchun eng yuqori tezlik 100 km/soat.","e":"Shahar tashqarisida yengil avtomobil — 'yuzlik': 100 km/soat."},{"id":159,"m":"tezlik","s":"Ruxsat etilgan to'liq vazni 12 t bo'lgan yuk avtomobili (tirkamasiz) aholi punktidan tashqarida qanday eng yuqori tezlikda harakatlanishi mumkin?","v":["70 km/soat","80 km/soat","90 km/soat","100 km/soat"],"j":1,"i":"Aholi punktidan tashqarida ruxsat etilgan to'liq vazni 3,5 t dan ortiq yuk avtomobillari uchun eng yuqori tezlik 80 km/soat. (YHQ, 79-band)","q":"Aholi punktidan tashqarida ruxsat etilgan to'liq vazni 3,5 t dan ortiq yuk avtomobili uchun eng yuqori tezlik 80 km/soat.","e":"3,5 t — chegara: undan yengil — 100, og'ir — 80."},{"id":160,"m":"tezlik","s":"Aholi punktidan tashqarida qaysi transport vositasi uchun eng yuqori tezlik 90 km/soat qilib belgilangan?","v":["Tirkamali yengil avtomobil","Mototsikl","Tirkamali yuk avtomobili","Shaharlararo qatnaydigan avtobus"],"j":3,"i":"Aholi punktidan tashqarida shaharlararo avtobus va mikroavtobuslarga 90 km/soat ruxsat etiladi. Tirkamali yengil avtomobil va mototsikl uchun 80 km/soat, tirkamali yuk avtomobili uchun 70 km/soat. (YHQ, 79-band)","q":"Aholi punktidan tashqarida: shaharlararo avtobus — 90, tirkamali yengil avtomobil va mototsikl — 80, tirkamali yuk avtomobili — 70 km/soat.","e":"Zinapoya 100-90-80-70: yengil, shaharlararo avtobus, og'ir yuk/moto, tirkamali yuk."},{"id":161,"m":"tezlik","s":"Boshqa yengil avtomobilni egiluvchan ulagichda shatakka olgan avtomobil aholi punktidan tashqarida qanday eng yuqori tezlikda harakatlanishi mumkin?","v":["50 km/soat","60 km/soat","70 km/soat","80 km/soat"],"j":0,"i":"Mexanik transport vositasini shatakka olgan transport vositasi har qanday yo'lda 50 km/soatdan oshmasdan harakatlanishi kerak. (YHQ, 80-band)","q":"Mexanik transport vositasini shatakka olgan transport vositasi har qanday yo'lda 50 km/soatdan oshmasdan harakatlanadi.","e":"Shatak — 'ellik': har qanday yo'lda, aholi punktidan tashqarida ham 50 dan oshma."},{"id":162,"m":"tezlik","s":"Bolalar guruhini tashkiliy tashiyotgan avtobus aholi punktidan tashqarida qanday eng yuqori tezlikda harakatlanishi mumkin?","v":["40 km/soat","50 km/soat","60 km/soat","70 km/soat"],"j":2,"i":"Bolalar guruhini tashkiliy tashiyotgan transport vositalari, shuningdek yukxonasida odam tashiyotgan yuk avtomobillari 60 km/soatdan oshmasdan harakatlanadi. (YHQ, 80-band)","q":"Bolalar guruhini tashkiliy tashiyotgan vosita va yukxonasida odam tashiyotgan yuk avtomobili har qanday yo'lda 60 km/soatdan oshmaydi.","e":"Bolalar yoki yukxonada odam bo'lsa — 60, shahar tashqarisida ham."},{"id":163,"m":"tezlik","s":"Ushbu belgi bilan belgilangan hududda transport vositalari uchun ruxsat etilgan eng yuqori tezlik qancha?","v":["10 km/soat","20 km/soat","30 km/soat","40 km/soat"],"j":1,"i":"Bu belgi turar joy dahasini bildiradi. Turar joy dahalari va yondosh hududlarda tezlik 20 km/soatdan oshmasligi kerak. (YHQ, 78-band; 1-ilova, 5.38-belgi)","r":{"b":"5.38"},"q":"Turar joy dahalari va yondosh hududlarda (hovlilarda) tezlik 20 km/soatdan oshmasligi kerak.","e":"Hovlida — 20 km/soat, belgili maktab yonida — 30."},{"id":164,"m":"tezlik","s":"Tegishli yo'l belgilari o'rnatilgan maktab yoki maktabgacha ta'lim tashkiloti yaqinida tezlik 30 km/soatdan oshmasligi kerak. Bu talab qaysi masofada amal qiladi?","v":["Tashkilotga yetmasdan va o'tib ketib 300 m dan kam masofada","Tashkilotga yetmasdan va o'tib ketib 100 m dan kam masofada","Tashkilotga yetmasdan va o'tib ketib 500 m dan kam masofada","Faqat tashkilot binosi ro'parasida"],"j":0,"i":"Tegishli yo'l belgilari o'rnatilgan maktab va maktabgacha ta'lim tashkilotlariga yetmasdan va o'tib ketib 300 m dan kam masofada tezlik 30 km/soatdan oshmasligi kerak. (YHQ, 78-band)","q":"Belgi o'rnatilgan maktab va maktabgacha ta'lim tashkilotiga yetmasdan va o'tib ketib 300 m dan kam masofada tezlik 30 km/soatdan oshmaydi.","e":"Maktab qoidasi '3-3': 300 m oraliq, 30 km/soat."},{"id":165,"m":"tezlik","s":"Harakatlanish paytida oldinda xavf paydo bo'ldi. YHQ bo'yicha haydovchi nima qilishi kerak?","v":["Ovozli ishora berib, tezlikni saqlagan holda harakatni davom ettirish","Transport vositasini to'liq to'xtatishgacha tezlikni kamaytirish choralarini ko'rish","Xavfni tezroq aylanib o'tish uchun tezlikni oshirish","Faqat avariya yorug'lik ishorasini yoqish"],"j":1,"i":"Tezlik yo'l, ob-havo va ko'rinish sharoitini hisobga olib tanlanadi; xavf paydo bo'lganda haydovchi transport vositasini to'liq to'xtatishgacha tezlikni kamaytirish choralarini ko'rishi kerak. (YHQ, 77-band)","q":"Xavf paydo bo'lganda haydovchi transport vositasini to'liq to'xtatishgacha tezlikni kamaytirish choralarini ko'rishi kerak.","e":"Tuzoq: tovushli ishora yoki tezlikni oshirish emas — xavf ko'rinsa, to'liq to'xtashgacha sekinla."},{"id":166,"m":"tezlik","s":"YHQ bo'yicha oldinda ketayotgan transport vositasigacha qanday oraliq masofa saqlanishi kerak?","v":["Har qanday tezlikda kamida 10 m","Metrlarda tezlikning yarmiga teng masofa","Oldingi vosita keskin tormoz berganda ham to'qnashmaslikni kafolatlaydigan masofa","Kamida ikki avtomobil uzunligiga teng masofa"],"j":2,"i":"Haydovchi oldingi transport vositasi keskin tormoz berganda ham to'qnashmaslikni kafolatlaydigan oraliq masofani, shuningdek xavfsiz yonlama oraliqni saqlashi kerak; YHQda aniq metr belgilanmagan. (YHQ, 73-band)","q":"Oldingi transport vositasigacha u keskin tormoz berganda ham to'qnashmaslikni kafolatlaydigan oraliq masofa saqlanadi.","e":"Tuzoq: YHQda 'necha metr' yozilmagan — mezon bitta: oldingisi keskin to'xtasa ham urilmaslik."},{"id":167,"m":"tezlik","s":"Temir yo'l kesishmasiga qancha masofadan kam qolganda quvib o'tish taqiqlanadi?","v":["30 m","50 m","100 m","150 m"],"j":2,"i":"Temir yo'l kesishmalarida va ularga 100 m dan kam masofa qolganda quvib o'tish taqiqlanadi. (YHQ, 86-band)","q":"Temir yo'l kesishmalarida va ularga 100 m dan kam masofa qolganda quvib o'tish taqiqlanadi.","e":"Relsga 100 m qoldi — quvib o'tishni unut; to'xtab turish taqiqi esa 50 m."},{"id":168,"m":"tezlik","s":"Quyidagi joylardan qaysi birida quvib o'tish taqiqlanmagan (boshqa belgilar va chiziqlar yo'q, ko'rinish yaxshi)?","v":["Tartibga solingan chorrahada","Ko'prik ustida","Piyodalar o'tish joyida","Tartibga solinmagan chorrahada asosiy yo'lda harakatlanayotganda"],"j":3,"i":"Quvib o'tish tartibga solingan chorrahalarda, ko'priklarda va piyodalar o'tish joylarida taqiqlanadi; tartibga solinmagan chorrahada esa faqat asosiy hisoblanmaydigan yo'lda harakatlanganda taqiqlanadi. (YHQ, 86-band)","q":"Quvib o'tilmaydi: tartibga solingan chorrahada, ko'prikda, piyodalar o'tish joyida, tartibga solinmagan chorrahada asosiy bo'lmagan yo'lda.","e":"Tartibga solinmagan chorrahada: asosiy yo'lda quvib o'tish mumkin, ikkinchi darajali yo'lda — taqiq."},{"id":169,"m":"tezlik","s":"Sizni quvib o'tishmoqda. YHQ bo'yicha sizga nima taqiqlanadi?","v":["Tezlikni oshirish yoki boshqa harakatlar bilan quvib o'tishga to'sqinlik qilish","Tezlikni o'zgartirmasdan harakatni davom ettirish","Tasma ichida o'ng tomonga yaqinroq olish","Tezlikni biroz kamaytirish"],"j":0,"i":"Quvib o'tilayotgan transport vositasining haydovchisiga tezlikni oshirish yoki boshqa harakatlar bilan quvib o'tishga to'sqinlik qilish taqiqlanadi. (YHQ, 84-band)","q":"Quvib o'tilayotgan haydovchiga tezlikni oshirish yoki boshqa harakatlar bilan quvib o'tishga to'sqinlik qilish taqiqlanadi.","e":"Seni quvib o'tishyapti — poyga emas: tezlikni oshirma, xalaqit berma."},{"id":170,"m":"tezlik","s":"Ushbu belgi ta'sir oralig'ida qaysi transport vositasini quvib o'tish mumkin?","v":["80 km/soat tezlikda ketayotgan yengil avtomobilni","30 km/soat tezlikda ketayotgan yakka traktorni","60 km/soat tezlikda ketayotgan yakka yuk avtomobilini","Hech qanday transport vositasini"],"j":1,"i":"Bu belgi tezligi 40 km/soatdan kam bo'lgan yakka transport vositasidan boshqa barcha transport vositalarini quvib o'tishni taqiqlaydi. (1-ilova, 3.20-belgi)","r":{"b":"3.20"},"q":"3.20 belgisi tezligi 40 km/soatdan kam bo'lgan yakka transport vositasidan boshqa barcha transport vositalarini quvib o'tishni taqiqlaydi.","e":"3.20 da istisno bitta: 40 km/soatdan sekin yurayotgan yakka vosita (masalan, traktor)."},{"id":171,"m":"toxtash","s":"Ushbu belgi bilan belgilangan joyda va uning yaqinida to'xtash qayerda taqiqlanadi?","v":["Faqat o'tish joyining o'zida","O'tish joyida, undan oldin va keyin 5 m dan kam masofada","O'tish joyida va undan oldin 10 m dan kam masofada","O'tish joyida va undan oldin 20 m dan kam masofada"],"j":2,"i":"Piyodalar o'tish joylarida va ulardan oldin 10 metrdan kam masofa qolganda to'xtash taqiqlanadi. (YHQ, 91-band)","r":{"b":"5.16.2"},"q":"Piyodalar o'tish joylarida va ulardan oldin 10 m dan kam masofa qolganda to'xtash taqiqlanadi.","e":"Zebra oldidagi 10 m — piyodani ko'rish uchun 'oyna': uni mashinang bilan to'sma."},{"id":172,"m":"toxtash","s":"Qatnov qismlari kesishmasida va kesishayotgan qatnov qismi chetiga qancha masofadan kam joyda to'xtash taqiqlanadi (uch tomonlama chorrahadagi istisnoni hisobga olmang)?","v":["5 m","10 m","15 m","30 m"],"j":3,"i":"Qatnov qismlari kesishmalarida va kesishayotgan qatnov qismi chetiga 30 metrdan kam masofada to'xtash taqiqlanadi. (YHQ, 91-band)","q":"Qatnov qismlari kesishmasida va kesishayotgan qatnov qismi chetiga 30 m dan kam masofada to'xtash taqiqlanadi.","e":"To'xtash taqiqlari '30-10-15': chorraha — 30 m, piyodalar o'tish joyi — 10 m, bekat — 15 m."},{"id":173,"m":"toxtash","s":"Bekatda maxsus maydoncha va 1.17 chizig'i yo'q, faqat ushbu belgi o'rnatilgan. Siz bekat yonidagi do'konga kirib chiqmoqchisiz. Belgidan oldin va keyin qancha masofadan kam joyda to'xtash taqiqlanadi?","v":["10 m","15 m","20 m","30 m"],"j":1,"i":"Bekat maydonchasi va 1.17 chizig'i bo'lmasa, to'xtash joyi belgisidan yetmasdan va o'tib ketib 15 metrdan kam masofada to'xtash taqiqlanadi (yo'nalishli transportga xalaqit bermay yo'lovchi chiqarish-tushirish bundan mustasno). (YHQ, 91-band)","r":{"b":"5.12"},"q":"Bekat maydonchasi va 1.17 chizig'i bo'lmasa, to'xtash joyi belgisidan yetmasdan va o'tib ketib 15 m dan kam masofada to'xtash taqiqlanadi.","e":"Tuzoq: yo'lovchi tushirish mumkin (avtobusga xalaqit bermasa), do'konga kirish — yo'q."},{"id":174,"m":"toxtash","s":"Temir yo'l kesishmasining har ikkala tomonida qancha masofa yaqinida to'xtab turish taqiqlanadi?","v":["50 m","100 m","150 m","200 m"],"j":0,"i":"Temir yo'l kesishmalarining har ikkala tomonida 50 metr yaqinida to'xtab turish taqiqlanadi; kesishmaning o'zida esa to'xtash ham taqiqlanadi. (YHQ, 91, 92-band)","q":"Temir yo'l kesishmasining har ikkala tomonida 50 m yaqinida to'xtab turish, kesishmaning o'zida esa to'xtash ham taqiqlanadi.","e":"'50 turish, 100 quvish': relsdan 50 m — to'xtab turma, 100 m — quvib o'tma."},{"id":175,"m":"toxtash","s":"To'xtagan avtomobil bilan bo'ylama sidirg'a chiziq (chetni belgilovchi chiziq emas) orasida qancha masofadan kam joy qolsa, u yerda to'xtash taqiqlanadi?","v":["1 m","2 m","3 m","5 m"],"j":2,"i":"To'xtagan transport vositasi bilan bo'ylama sidirg'a chiziq, ajratuvchi mintaqa yoki qatnov qismining qarama-qarshi cheti orasida 3 metrdan kam masofa qoladigan joylarda to'xtash taqiqlanadi. (YHQ, 91-band)","q":"To'xtagan vosita bilan bo'ylama sidirg'a chiziq, ajratuvchi mintaqa yoki qarama-qarshi chet orasida 3 m dan kam qolsa, to'xtash taqiqlanadi.","e":"Tuzoq: chetni belgilovchi chiziq hisobga kirmaydi — 3 m sidirg'a chiziqdan o'lchanadi."},{"id":176,"m":"toxtash","s":"Ushbu belgi ko'rsatgan qayrilib olish joyida, shuningdek unga qancha masofa yetmasdan yoki o'tib to'xtash taqiqlanadi?","v":["10 m","15 m","30 m","50 m"],"j":2,"i":"Transport vositalarining qayrilib olish joylarida va unga 30 metr yetmasdan yoki o'tib to'xtash taqiqlanadi. (YHQ, 91-band)","r":{"b":"5.11.1"},"q":"Qayrilib olish joylarida va ularga 30 m yetmasdan yoki o'tib to'xtash taqiqlanadi.","e":"Qayrilish joyi va chorraha — ikkalasida ham '30 m qoidasi'."},{"id":177,"m":"toxtash","s":"Belgilar yo'q. Har bir yo'nalishda ikkitadan tasmasi bor ko'prik ustida yo'lovchini tushirish uchun bir daqiqaga to'xtash mumkinmi?","v":["Mumkin, chunki bu to'xtab turish emas, balki to'xtash","Mumkin, agar avariya yorug'lik ishorasi yoqilgan bo'lsa","Faqat chetki o'ng tasmada mumkin","Mumkin emas, bunday ko'prik ustida to'xtash taqiqlanadi"],"j":3,"i":"Bir yo'nalishda uchtadan kam tasmasi bor ko'prik, yo'l o'tkazgich va estakadalarning ustida to'xtash taqiqlanadi; yo'lovchi tushirish ham to'xtash hisoblanadi. (YHQ, 91-band)","q":"Bir yo'nalishda uchtadan kam tasmasi bor ko'prik, yo'l o'tkazgich va estakada ustida va ostida (belgilangan joydan tashqari) to'xtash taqiq.","e":"Tuzoq: yo'lovchi tushirish ham to'xtash — tor ko'prikda bir daqiqa ham mumkin emas."},{"id":178,"m":"toxtash","s":"Ushbu belgi ta'sir oralig'ida yo'lovchini tushirish uchun 3 daqiqaga to'xtash mumkinmi?","v":["Mumkin emas, belgi har qanday to'xtashni taqiqlaydi","Faqat taksilarga mumkin","Mumkin, belgi faqat to'xtab turishni taqiqlaydi"],"j":2,"i":"Bu belgi faqat to'xtab turishni taqiqlaydi, shuning uchun 10 daqiqagacha to'xtash, jumladan yo'lovchi tushirish mumkin. (1-ilova, 3.28-belgi; YHQ, 6-band)","r":{"b":"3.28"},"q":"3.28 belgisi faqat to'xtab turishni taqiqlaydi: uning ta'sir oralig'ida 10 daqiqagacha to'xtash, jumladan yo'lovchi tushirish mumkin.","e":"Bitta qizil chiziq (3.28) — turish mumkin emas, ikkita X (3.27) — to'xtash ham mumkin emas."},{"id":179,"m":"toxtash","s":"Ushbu belgilar qatnov qismining qarama-qarshi tomonlarida bir vaqtda o'rnatilgan. Qaysi vaqtda qatnov qismining har ikkala tomonida to'xtab turishga ruxsat etiladi?","v":["Hech qachon","07:00 dan 09:00 gacha","13:00 dan 15:00 gacha","19:00 dan 21:00 gacha"],"j":3,"i":"3.29 va 3.30 belgilari qatnov qismining qarama-qarshi tomonlarida bir vaqtda o'rnatilganda, har ikkala tomonda soat 19:00 dan 21:00 gacha to'xtab turishga ruxsat etiladi. (1-ilova, 3.29, 3.30-belgilar)","r":{"b":["3.29","3.30"]},"q":"3.29 va 3.30 belgilari qarama-qarshi tomonlarda birga o'rnatilsa, har ikkala tomonda 19:00 dan 21:00 gacha to'xtab turishga ruxsat.","e":"Toq-juft almashinuvi kechqurun: 19:00–21:00 da ikkala tomon ham ochiq."},{"id":180,"m":"toxtash","s":"Aholi punktidagi keng ikki tomonlama ko'chada har bir yo'nalishda bittadan tasma bor, o'rtasida tramvay yo'li yo'q. Yo'l belgilari va chiziqlari yo'q. Yengil avtomobil chap tomonda to'xtashi mumkinmi?","v":["Mumkin emas, chap tomonda faqat bir tomonlama yo'lda to'xtash mumkin","Mumkin","Faqat yuk ortish yoki tushirish uchun mumkin","Faqat sutkaning yorug' vaqtida mumkin"],"j":1,"i":"Aholi punktlarida o'rtasida tramvay yo'li bo'lmagan, har yo'nalishda bittadan tasmasi bor yo'llarda hamda bir tomonlama yo'llarda chap tomonda to'xtash va to'xtab turishga ruxsat etiladi. (YHQ, 88-band)","q":"Aholi punktida tramvay yo'li yo'q, har yo'nalishda bitta tasmali yo'lda va bir tomonlama yo'lda chap tomonda to'xtash mumkin.","e":"Chapda to'xtash — ikki holatda: 'bir tomonlama' yoki 'bir tasmali, tramvaysiz' yo'l (aholi punktida)."},{"id":181,"m":"toxtash","s":"Belgilar va chiziqlar boshqacha tartib ko'rsatmagan bo'lsa, yengil avtomobillar qatnov qismida qanday to'xtab turadi?","v":["Qatnov qismi chetiga parallel holda, ikki qator bo'lib","Qatnov qismi chetiga perpendikulyar holda","Qatnov qismi chetiga parallel holda, bir qator bo'lib","Ikki g'ildiragi bilan trotuarga chiqib"],"j":2,"i":"Transport vositalari qatnov qismida chetga parallel holda bir qator bo'lib turadi; trotuar chetida faqat 5.15 belgisi tegishli 7.6 qo'shimcha belgisi bilan o'rnatilgan joyda to'xtash mumkin. (YHQ, 89-band)","q":"Belgi va chiziqlar boshqacha ko'rsatmasa, transport vositalari qatnov qismida chetga parallel holda bir qator bo'lib to'xtab turadi.","e":"Parallel va bir qator; ikki qator faqat kajavasiz ikki g'ildiraklilarga."},{"id":182,"m":"toxtash","s":"Aholi punktidagi bir tomonlama yo'lda ruxsat etilgan to'liq vazni 8 t bo'lgan yuk avtomobili chap tomonda qachon to'xtashi mumkin?","v":["Hech qachon","Istalgan maqsadda","Faqat haydovchi dam olishi uchun","Faqat yuk ortish yoki tushirish uchun"],"j":3,"i":"Ruxsat etilgan to'liq vazni 3,5 t dan ortiq yuk avtomobillari chap tomonda faqat yuk ortish yoki tushirish uchun to'xtashi mumkin. (YHQ, 88-band)","q":"Ruxsat etilgan to'liq vazni 3,5 t dan ortiq yuk avtomobili chap tomonda faqat yuk ortish yoki tushirish uchun to'xtashi mumkin.","e":"Og'ir yuk mashinasi chapda faqat 'ish bilan': yuk ortadi, tushiradi, xolos."},{"id":183,"m":"toxtash","s":"Haydovchi o'z joyini tashlab ketishi yoki transport vositasini qoldirib ketishidan oldin nima qilishi shart?","v":["Vositaning o'z-o'zidan yurib ketmasligi va undan begona shaxs foydalanmasligi choralarini ko'rish","Faqat avariya yorug'lik ishorasini yoqish","Faqat gabarit chiroqlarni yoqish","Hech narsa, agar 10 daqiqadan kam qolsa"],"j":0,"i":"Haydovchi vositaning o'z-o'zidan harakatlanib ketishi yoki u yo'qligida undan foydalanilishining oldini olish choralarini ko'rgandan keyingina joyini tashlab ketishi mumkin. (YHQ, 95-band)","q":"Haydovchi joyini tark etishdan oldin vositaning o'z-o'zidan yurib ketmasligi va undan begona foydalanmasligi choralarini ko'radi.","e":"Ikki xavf — ikki chora: o'zi yurib ketmasin, begona minib ketmasin."},{"id":184,"m":"toxtash","s":"Avtomobil to'xtash taqiqlangan joyda nosozlik sababli majburan to'xtadi. Haydovchi nima qilishi shart?","v":["Hech narsa, majburiy to'xtash qoidabuzarlik emas","Avariya yorug'lik ishorasini yoqish, vositani yo'l chetiga olib chiqish va u joydan olib ketish choralarini ko'rish","IIO xodimlari kelguncha vositani joyidan qo'zg'atmaslik","Vositani qoldirib, yordam chaqirish uchun ketish"],"j":1,"i":"To'xtash taqiqlangan joyda majburiy to'xtaganda avariya yorug'lik ishorasi yoqiladi, haydovchi vositani yo'l chetiga olib chiqish va u joydan olib ketishning barcha choralarini ko'radi. (YHQ, 50, 93-band)","q":"Taqiqlangan joyda majburan to'xtagan haydovchi avariya chirog'ini yoqadi va vositani u joydan olib ketish choralarini ko'radi.","e":"Majburiy to'xtash — kechirim, ruxsat emas: chiroqni yoq va imkon qadar tez joyni bo'shat."},{"id":185,"m":"toxtash","s":"Aholi punktidan tashqarida ko'rinish cheklangan joyda avtomobil majburan to'xtadi, avariya yorug'lik ishorasi ishlamayapti. Avariya sababli to'xtash belgisi vositadan kamida qancha masofaga qo'yiladi?","v":["15 m","30 m","50 m","100 m"],"j":1,"i":"Avariya sababli to'xtash belgisi aholi punktlarida vositadan kamida 15 m, aholi punktidan tashqarida kamida 30 m masofaga qo'yiladi. (YHQ, 51-band)","q":"Avariya sababli to'xtash belgisi aholi punktida vositadan kamida 15 m, aholi punktidan tashqarida kamida 30 m masofaga qo'yiladi.","e":"Aholi punktida 15, tashqarida ikki barobar — 30: tezlik katta joyda ogohlantirish ham uzoqroq."},{"id":186,"m":"maxsus","s":"Ushbu belgi bilan belgilangan, tartibga solinmagan joyda piyoda qatnov qismini kesib o'tmoqda. Haydovchi nima qilishi shart?","v":["Ovozli ishora berib, piyodani to'xtatish","Piyoda o'tib bo'lmasdan uning orqasidan aylanib o'tish","Piyodaga yo'l berish uchun tezlikni kamaytirish yoki to'xtash","Faqat piyoda o'z tasmasiga chiqqanda to'xtash"],"j":2,"i":"Tartibga solinmagan piyodalar o'tish joyida haydovchi qatnov qismini kesib o'tayotgan piyodalarga yo'l berish uchun tezlikni kamaytirishi yoki to'xtashi kerak. (YHQ, 109-band)","r":{"b":"5.16.1"},"q":"Tartibga solinmagan piyodalar o'tish joyida haydovchi kesib o'tayotgan piyodalarga yo'l berish uchun tezlikni kamaytiradi yoki to'xtaydi.","e":"Tuzoq: piyoda sening tasmangga yetishini kutma — u qatnov qismini kesib o'tyaptimi, yo'l ber."},{"id":187,"m":"maxsus","s":"Bir yo'nalishda ikki tasmali yo'lda tartibga solinmagan piyodalar o'tish joyi oldida yon tasmadagi avtomobil sekinlab to'xtadi. Siz qo'shni tasmada ketyapsiz. Nima qilasiz?","v":["Oldinda piyoda yo'qligiga ishonch hosil qilgandan keyingina harakatni davom ettiraman","Tezlikni saqlab o'tib ketaman, chunki mening tasmamda piyoda ko'rinmayapti","Ovozli ishora berib, ehtiyot bo'lib o'tib ketaman"],"j":0,"i":"O'tish joyi oldida sekinlagan yoki to'xtagan vosita bilan yonma-yon tasmadagi haydovchilar oldinda piyoda yo'qligiga ishonch hosil qilgandan keyingina harakatni davom ettirishi mumkin. (YHQ, 110-band)","q":"O'tish joyi oldida sekinlagan yoki to'xtagan vosita yonidagi tasmada haydovchi oldinda piyoda yo'qligiga ishonch hosil qilib yuradi.","e":"Yondagi mashina zebra oldida to'xtadimi — demak, uning ortida piyoda bo'lishi mumkin."},{"id":188,"m":"maxsus","s":"Tartibga solingan piyodalar o'tish joyida sizga yashil ishora yondi, lekin bir piyoda qatnov qismini kesib o'tishni hali tugatmagan. Nima qilasiz?","v":["Piyodaning o'tishni tugatishiga imkon beraman","Ovozli ishora berib, harakatni boshlayman","Yashil yongani uchun piyodadan oldin o'taman","Piyodani orqasidan aylanib o'taman"],"j":0,"i":"Tartibga solingan o'tish joyida ruxsat etuvchi ishora yonganda ham haydovchi piyodalarga qatnov qismini kesib o'tishni tugallashiga imkon berishi kerak. (YHQ, 111-band)","q":"Tartibga solingan o'tish joyida ruxsat etuvchi ishora yonganda ham haydovchi piyodalarga kesib o'tishni tugallashiga imkon beradi.","e":"Senga yashil yondi — piyoda esa hali yo'lda: avval u yetib olsin."},{"id":189,"m":"maxsus","s":"Piyodalar o'tish joyi bo'lmagan joyda oq hassa bilan ishora berayotgan ko'zi ojiz piyoda qatnov qismini kesib o'tmoqda. Haydovchi nima qilishi kerak?","v":["O'tish joyi bo'lmagani uchun yo'l bermasligi mumkin","Uni o'tkazib yuborishi kerak","Ovozli ishora berib, uni ogohlantirib o'tishi kerak","Faqat aholi punktida yo'l berishi kerak"],"j":1,"i":"Oq hassa bilan ishora berayotgan ko'zi ojiz piyodani haydovchi har qanday joyda o'tkazib yuborishi kerak. (YHQ, 113-band)","q":"Oq hassa bilan ishora berayotgan ko'zi ojiz piyodani haydovchi har qanday joyda o'tkazib yuborishi kerak.","e":"Oq hassa — 'ko'chma zebra': o'tish joyi bo'lmasa ham, unga yo'l ber."},{"id":190,"m":"maxsus","s":"Qatnov qismi o'rtasidagi tramvay yo'lida qo'nish maydonchasi bo'lmagan bekat bor. Tramvay to'xtadi va yo'lovchilar trotuardan uning eshiklari tomon qatnov qismini kesib o'tmoqda. Siz tramvay bilan bir yo'nalishda ketyapsiz. Nima qilasiz?","v":["Piyodalarga yo'l beraman","Ovozli ishora berib, tezlikni oshirib o'tib ketaman","Tramvayni chap tomondan aylanib o'taman"],"j":0,"i":"Bekatda turgan yo'nalishli transport vositasining eshiklari tomon borayotgan yoki undan kelayotgan piyodalarga haydovchi yo'l berishi kerak. (YHQ, 114-band)","q":"Bekatda turgan yo'nalishli transport vositasi eshiklari tomon borayotgan yoki undan kelayotgan piyodalarga haydovchi yo'l beradi.","e":"Tramvay eshigi ochildi — yo'l piyodaniki: ular o'tmaguncha kut."},{"id":191,"m":"maxsus","s":"Oldinda \"Bolalar guruhini tashish\" taniqlik belgisi o'rnatilgan avtobus avariya yorug'lik ishorasini yoqib to'xtab turibdi. Unga yaqinlashayotgan haydovchi nima qilishi shart?","v":["Ovozli ishora berib, tezlikni o'zgartirmasdan o'tishi","Avtobusni tezroq quvib o'tib ketishi","Faqat yaqinni yorituvchi farani yoqishi","Tezlikni kamaytirishi, zarur bo'lsa to'xtab, bolalarni o'tkazib yuborishi"],"j":3,"i":"\"Bolalar guruhini tashish\" belgisi o'rnatilgan va avariya yorug'lik ishorasi yoqilgan transport vositasiga yaqinlashganda haydovchi tezlikni kamaytirishi, zarur bo'lsa to'xtab, bolalarni o'tkazib yuborishi shart. (YHQ, 115-band)","q":"'Bolalar guruhini tashish' belgili, avariya chirog'i yoqilgan vositaga yaqinlashganda sekinla, kerak bo'lsa to'xtab, bolalarni o'tkaz.","e":"'Bolalar' belgisi + avariya chirog'i = yaqinda bola yugurib chiqishi mumkin: sekinla."},{"id":192,"m":"maxsus","s":"Aholi punktida ushbu belgi yonidagi bekatda turgan avtobus chap burilish ishorasini yoqib, harakatni boshlamoqda. Siz shu tasmada orqadan yaqinlashyapsiz. Nima qilasiz?","v":["Avtobus menga yo'l berishi kerak, chunki u manyovr qilmoqda","Ovozli ishora berib, avtobusni o'tib ketaman","Avtobusga yo'l beraman"],"j":2,"i":"Aholi punktlarida haydovchilar bekatdan harakatlanishni boshlayotgan avtobus va trolleybuslarga yo'l berishi kerak. (YHQ, 133-band)","r":{"b":"5.12"},"q":"Aholi punktida haydovchilar bekatdan harakatlanishni boshlayotgan avtobus va trolleybuslarga yo'l berishi kerak.","e":"Aholi punktidagi bekat: avtobus yoki trolleybus jo'nasa — sen kutasan, u ketadi."},{"id":193,"m":"maxsus","s":"Ushbu belgi o'rnatilgan shlagbaumsiz temir yo'l kesishmasiga poyezd yaqinlashmoqda. To'xtash chizig'i, 2.5 belgisi va svetofor yo'q. Haydovchi birinchi relsdan kamida qancha masofada to'xtashi kerak?","v":["5 m","10 m","15 m","20 m"],"j":1,"i":"To'xtash chizig'i, 2.5 belgisi va svetofor bo'lmasa, shlagbaum yo'q kesishmada haydovchi birinchi temir yo'l izidan kamida 10 m oldin to'xtaydi. (YHQ, 119-band)","r":{"b":"1.3.1"},"q":"Shlagbaumsiz kesishmada to'xtash chizig'i, 2.5 belgisi va svetofor bo'lmasa, birinchi relsdan kamida 10 m oldin to'xtaladi.","e":"Shlagbaum bo'lsa — 5 m, bo'lmasa — 10 m: to'siq yo'q joyda masofa ikki barobar."},{"id":194,"m":"maxsus","s":"Shlagbaumli temir yo'l kesishmasida shlagbaum yopila boshladi. To'xtash chizig'i, 2.5 belgisi va svetofor yo'q. Haydovchi shlagbaumdan kamida qancha masofada to'xtashi kerak?","v":["5 m","10 m","15 m","20 m"],"j":0,"i":"Shlagbaum yopila boshlaganda kesishmaga kirish taqiqlanadi. To'xtash chizig'i, 2.5 belgisi yoki svetofor bo'lmasa, haydovchi shlagbaumdan kamida 5 m oldin to'xtaydi. (YHQ, 118, 119-band)","q":"To'xtash chizig'i, 2.5 belgisi va svetofor bo'lmasa, haydovchi shlagbaumdan kamida 5 m oldin to'xtaydi.","e":"Shlagbaum yopila boshladimi — bu ham 'yopiq' degani: 5 m oldin to'xta."},{"id":195,"m":"maxsus","s":"Temir yo'l kesishmasida quyidagilardan qaysi biri taqiqlanadi?","v":["Kesishma oldidagi navbatni qarama-qarshi harakat bo'lagiga chiqib aylanib o'tish","Svetoforda miltillovchi oq-oy rang ishora yonganda kesishmadan o'tish","Svetoforning qizil va oq-oy rang ishoralari o'chiq bo'lganda, poyezd yo'qligiga ishonch hosil qilib o'tish"],"j":0,"i":"Kesishma oldida turgan vositalarni qarama-qarshi harakat bo'lagiga chiqib aylanib o'tish taqiqlanadi. Miltillovchi oq-oy rang ishora harakatga ruxsat beradi; ishoralar o'chiq bo'lsa, poyezd yo'qligiga ishonch hosil qilib o'tish mumkin. (YHQ, 37, 118-band)","q":"Temir yo'l kesishmasi oldidagi navbatni qarama-qarshi harakat bo'lagiga chiqib aylanib o'tish taqiqlanadi.","e":"Miltillovchi oq-oy rang — yur, miltillovchi qizil — to'xta; navbatni aylanib o'tish — har doim taqiq."},{"id":196,"m":"maxsus","s":"Avtomobilingiz temir yo'l kesishmasida o'chib qoldi va uni yurgizib bo'lmayapti. Haydovchi birinchi navbatda nima qilishi kerak?","v":["Avtomobil ichida qolib, yordam kutishi","Avariya sababli to'xtash belgisini avtomobildan 15 m ga qo'yishi","Darhol odamlarni tushirib, kesishmani bo'shatish choralarini ko'rishi","IIOga qo'ng'iroq qilib, xodimlarni kutishi"],"j":2,"i":"Kesishmada majburan to'xtab qolganda haydovchi darhol odamlarni tushiradi va kesishmani bo'shatish choralarini ko'radi; imkoni bo'lsa poyezdni to'xtatish uchun ikki tomonga 1000 m ga odam yuboradi. (YHQ, 120-band)","q":"Kesishmada majburan to'xtab qolganda haydovchi darhol odamlarni tushiradi va kesishmani bo'shatish choralarini ko'radi.","e":"Avval odamlar, keyin mashina: relsda qolgan avtomobil — temir, odam — hayot."},{"id":197,"m":"maxsus","s":"Ushbu belgi bilan belgilangan yo'lda quyidagilardan qaysi biri taqiqlanadi?","v":["Yengil avtomobilda chetki chap tasmada harakatlanib, boshqa vositalarni o'zib ketish","6.11 belgisi bilan belgilangan dam olish maydonchasida to'xtash","Yuk avtomobilida chetki o'ng tasmada harakatlanish","Ajratuvchi mintaqa uzilgan joydan qayrilib olish"],"j":3,"i":"Bu belgi avtomagistralni bildiradi. Unda ajratuvchi mintaqa uzilgan joylarga kirish va qayrilib olish, orqaga harakatlanish va o'quv haydash taqiqlanadi; to'xtash faqat 5.15 yoki 6.11 belgili maydonchalarda mumkin. (YHQ, 121-band)","r":{"b":"5.1"},"q":"Avtomagistralda ajratuvchi mintaqa uzilgan joyga kirish va qayrilib olish, orqaga harakatlanish va o'quv haydash taqiqlanadi.","e":"Avtomagistral — bir tomonga oqar daryo: qayrilish ham, orqaga yurish ham yo'q."},{"id":198,"m":"maxsus","s":"Ushbu belgi bilan belgilangan yo'lda qaysi transport vositasining harakatlanishi taqiqlanadi?","v":["Moped","Tirkamali yengil avtomobil","Shaharlararo avtobus","Ruxsat etilgan to'liq vazni 10 t bo'lgan yuk avtomobili"],"j":0,"i":"Avtomagistralda piyodalar, velosipedlar, mopedlar, skuterlar, traktorlar va tezligi 40 km/soatdan kam bo'lgan vositalarning harakatlanishi taqiqlanadi. (YHQ, 121-band)","r":{"b":"5.1"},"q":"Avtomagistralda piyoda, velosiped, moped, skuter, traktor va tezligi 40 km/soatdan kam vositalarning harakatlanishi taqiqlanadi.","e":"Tuzoq: tirkamali yengil va og'ir yuk mumkin, moped esa tezligidan qat'i nazar — taqiq."},{"id":199,"m":"maxsus","s":"Ushbu belgi bilan belgilangan hududda piyodalar qayerda harakatlanishi mumkin?","v":["Faqat trotuarda","Trotuarda ham, qatnov qismida ham; ular imtiyozga ega, lekin transportga asossiz xalaqit bermasligi kerak","Faqat piyodalar o'tish joyida","Qatnov qismida ham, lekin transport vositalariga yo'l berishi shart"],"j":1,"i":"Turar joy dahasida piyodalar trotuarda ham, qatnov qismida ham harakatlanishi mumkin va imtiyozga ega, lekin transport vositalariga asossiz xalaqit bermasliklari kerak. (YHQ, 123-band)","r":{"b":"5.38"},"q":"Turar joy dahasida piyodalar trotuarda ham, qatnov qismida ham yurishi mumkin va imtiyozga ega, lekin transportga asossiz xalaqit bermaydi.","e":"Turar joy dahasi — piyoda hovlisi: u qatnov qismida ham yuradi, sen 20 km/soatda ehtiyot bo'l."},{"id":200,"m":"maxsus","s":"Turar joy dahasida quyidagilardan qaysi biri taqiqlanadi?","v":["15 km/soat tezlikda harakatlanish","Yengil avtomobilni dvigatelini o'chirib, boshqalarga xalaqit bermaydigan joyda to'xtatib qo'yish","Mexanik transport vositasini boshqarishni o'rgatish","Piyodaga yo'l berish uchun to'xtash"],"j":2,"i":"Turar joy dahasida haydashni o'rgatish, dvigatel ishlab turgan holda to'xtab turish va to'liq vazni 3,5 t dan ortiq yuk avtomobillarini maxsus joydan tashqarida to'xtatib qo'yish taqiqlanadi. (YHQ, 124-band)","q":"Turar joy dahasida taqiq: haydashni o'rgatish, motor ishlagan holda to'xtab turish, 3,5 t dan og'ir yuk mashinasini maxsus joysiz qoldirish.","e":"Hovlida uch 'yo'q': o'quv haydash, o'chirilmagan motor, maxsus joydan tashqaridagi og'ir yuk mashinasi."}],"oltin":{"belgilar":[{"q":"Ogohlantiruvchi belgilar aholi punktida xavfli joydan 50–100 m, aholi punktidan tashqarida 150–300 m oldin o'rnatiladi.","e":"Tashqarida masofa uch baravar: 50–100 m o'rniga 150–300 m."},{"q":"2.4 belgisida kesib o'tilayotgan yo'ldagilarga yo'l beriladi; 2.5 belgisida esa har doim to'xtab, so'ng yo'l beriladi.","e":"2.4 – qara va yo'l ber; 2.5 \"STOP\" – yo'l bo'sh bo'lsa ham to'xta."},{"q":"3.27 to'xtashni ham, to'xtab turishni ham taqiqlaydi; 3.28 faqat to'xtab turishni taqiqlaydi.","e":"Bitta qizil chiziq – turish mumkin emas, ikkita X – to'xtash ham mumkin emas."},{"q":"3.20 belgisi ta'sir oralig'ida faqat soatiga 40 km dan sekin ketayotgan yakka transport vositasini quvib o'tish mumkin.","e":"\"Yakka va 40 dan sekin\" – ikkala shart birga bo'lishi kerak."},{"q":"3.16, 3.20, 3.22, 3.24, 3.26–3.30 belgilari eng yaqin chorrahagacha, u bo'lmasa aholi punktining oxirigacha amal qiladi.","e":"Tuzoq: hovlidan chiqish joyi chorraha emas – belgi ta'siri davom etadi."},{"q":"4.1.1–4.1.6 belgilari faqat ko'rsatilgan yo'nalishga ruxsat beradi; chapga ruxsat beruvchisi qayrilishga ham ruxsat beradi.","e":"Chap strelka ikkalasini ochadi: chapga burilish ham, qayrilish ham."}],"chiziq":[{"q":"1.1 va 1.3 chiziqlarini bosib o'tish taqiqlanadi (qatnov qismi chetidagi 1.1 mustasno); 1.2, 1.5–1.8 ni istalgan tomondan bosish mumkin.","e":"Sidirg'a chiziq – devor, uzuq chiziq – eshik."},{"q":"1.11 chizig'ini uzuq tomondan bosib o'tish mumkin, sidirg'a tomondan faqat quvib yoki aylanib o'tishni tugatayotganda.","e":"Sidirg'a tomonda – faqat \"uyga qaytish\": o'z tasmangizga qaytish uchun."},{"q":"Belgilar va yotiq chiziqlar zid kelsa – belgilarga, vaqtinchalik va doimiy chiziqlar zid kelsa – vaqtinchalik chiziqlarga amal qilinadi.","e":"Belgi chiziqdan ustun, vaqtinchalik chiziq doimiysidan ustun."},{"q":"Yotiq chiziqlar oq rangda bo'ladi, faqat 1.4, 1.10 va 1.17 chiziqlari sariq rangda.","e":"Sariq – to'xtash mavzusi: 1.4 to'xtash yo'q, 1.10 to'xtab turish yo'q, 1.17 bekat."},{"q":"1.3 qo'sh chiziq to'rt va undan ortiq tasmali, 1.5 uzuq chiziq ikki yoki uch tasmali yo'llarda qarama-qarshi oqimlarni ajratadi.","e":"Qo'sh chiziq – katta yo'l (4+ tasma), uzuq chiziq – kichik yo'l (2–3 tasma)."},{"q":"1.6 yaqinlashish chizig'i 1.1 yoki 1.11 chizig'iga yaqinlashayotganlik haqida ogohlantiradi.","e":"Bo'laklar uzayadi, oraliqlar qisqaradi – oldinda sidirg'a chiziq."}],"yoritish":[{"q":"Uzoqni yorituvchi faradan yaqinni yorituvchiga qarama-qarshi transport vositasiga kamida 150 m qolganda o'tiladi.","e":"Tuzoq: 300 m – ko'rinish chegarasi, 150 m – faralarni almashtirish masofasi."},{"q":"Kunduzi yaqinni yorituvchi fara shatakka olgan vositada, tashkiliy jamlanmada, yo'lovchili avtobusda va kuchli yog'ingarchilikda yoqiladi.","e":"Tuzoq: oddiy yengil avtomobilga kunduzi fara yoqish majburiy emas."},{"q":"Ko'zi qamashgan haydovchi avariya ishorasini yoqib, harakatlanish bo'lagini o'zgartirmasdan tezlikni kamaytirishi va to'xtashi kerak.","e":"Ko'z qamashdi: avariya chirog'i – tasma o'zgarmaydi – sekinla – to'xta."},{"q":"Avariya sababli to'xtash belgisi aholi punktida transport vositasidan kamida 15 m, tashqarida kamida 30 m masofaga qo'yiladi.","e":"Tashqarida ikki baravar: 15 m o'rniga 30 m."},{"q":"Tovushli ishora faqat YTHning oldini olish uchun va aholi punktidan tashqarida quvib o'tishdan ogohlantirish uchun beriladi.","e":"Shaharda signal – faqat xavf uchun."},{"q":"Ko'k yoki qizil mayoqcha va maxsus tovushli ishora yoqilgan vositaga yo'l beriladi; sariq mayoqcha imtiyoz bermaydi.","e":"Sariq – \"ehtiyot bo'l\", ko'k yoki qizil + sirena – \"yo'l ber\"."}],"tashish":[{"q":"Shatakka olishda vositalar orasidagi masofa egiluvchan ulagichda 4–6 m, qattiq ulagichda ko'pi bilan 4 m bo'ladi.","e":"Juftlik: tros – 4–6 m, qattiq ulagich – ko'pi bilan 4 m."},{"q":"Mexanik transport vositasini shatakka olgan transport vositasi har qanday yo'lda 50 km/soatdan oshmasdan harakatlanadi.","e":"Shatakda shahar ham, trassa ham bir xil – 50 km/soat."},{"q":"Yo'l yaxmalak yoki sirpanchiq bo'lsa, egiluvchan ulagich bilan shatakka olish taqiqlanadi.","e":"Muz + tros = taqiq."},{"q":"Haydovchi va old o'rindiqdagi yo'lovchilar kamar taqishi shart; orqa o'rindiqdagi 12 yoshgacha bolalar bundan mustasno.","e":"Orqada VA 12 dan kichik – ikkala shart birga bo'lsagina kamarsiz."},{"q":"Yuk gabaritdan oldi yoki orqaga 1 m dan, yon tomonga 0,4 m dan ortiq chiqsa, \"Katta o'lchamli yuk\" belgisi qo'yiladi.","e":"Tuzoq: yon tomonga chegara atigi 0,4 m – oldi-orqadagi 1 m bilan adashtirmang."},{"q":"Bolalarni yuk avtomobilining yukxonasida tashish taqiqlanadi, yukxona odam tashishga jihozlangan bo'lsa ham.","e":"Tuzoq: o'rindiq va bort bor bo'lsa ham – bolalar yukxonaga chiqmaydi."}],"texnik":[{"q":"Protektor qoldiq balandligi chegarasi: mototsikl va moped – 0,8 mm, N2, N3 – 1,0 mm, M1, N1 – 1,6 mm, M2, M3 – 2,0 mm.","e":"Shina zinapoyasi: 0,8 – 1,0 – 1,6 – 2,0 mm; avtobusda eng qattiq talab."},{"q":"Rul lyufti yig'indisi M1 uchun 10°, M2, M3, N1 uchun 20°, N2, N3 uchun 25° dan oshsa, foydalanish taqiqlanadi.","e":"Rul zinapoyasi: yengil – 10°, avtobus va N1 – 20°, og'ir yuk – 25°."},{"q":"Old oyna va old yon oynalarning yorug'lik o'tkazuvchanligi 70% dan kam bo'lsa, foydalanish taqiqlanadi (ruxsatnoma bo'lmasa).","e":"Tuzoq: 50% emas – kamida 70% yorug'lik o'tishi kerak."},{"q":"M1 avtomobilda tibbiyot qutichasi, o't o'chirgich, avariya sababli to'xtash belgisi va nur qaytargichli kamzul bo'lishi shart.","e":"Yengil mashina to'rtligi: aptechka, o't o'chirgich, uchburchak, kamzul."},{"q":"Yomg'ir yoki qor yog'ayotganda oyna tozalagich ishlamaydigan transport vositasini boshqarish taqiqlanadi.","e":"Tuzoq: magnitola yoki soat – mayda gap; yomg'irda oyna tozalagich – xavfsizlik."},{"q":"Tormoz yuritmasi nosoz bo'lib, uni joyida tuzatib bo'lmasa, avtomobil evakuator yoki shatakka olish orqali olib boriladi.","e":"Tormoz nosoz – o'zingiz haydamaysiz."}],"tibbiy":[{"q":"YTHda haydovchi darhol to'xtab, avariya chirog'ini yoqadi va belgi qo'yadi, so'ng jabrlanganga yordam berib, tez yordam chaqiradi.","e":"Avval o'zingni va yo'lni himoya qil, keyin jabrlanganni."},{"q":"Tez yordamga qo'ng'iroq qilganda voqea joyining aniq manzili, jabrlanganlar soni va ahvoli aytiladi.","e":"\"Qayerda, nechta, qanday\" – uchta javob bering."},{"q":"Hushsiz, lekin normal nafas olayotgan jabrlangan (umurtqa shikasti belgisi bo'lmasa) barqaror yon holatga yotqiziladi.","e":"Nafas bor – yonga: til va qusuq nafas yo'lini to'smaydi."},{"q":"Qon ketganda avval yarani toza mato bilan qattiq bosib turiladi; jgut faqat qo'l-oyoqdan xavfli qon ketishida, vaqti yozilib qo'yiladi.","e":"Avval kaft, oxirida jgut – va soatni yozing."},{"q":"Umurtqa shikasti gumon qilinsa va xavf bo'lmasa, jabrlangan joyidan qo'zg'atilmaydi, boshi harakatsiz ushlab turiladi.","e":"Bo'yin yoki bel shikastida: \"qimirlatma – kut\"."},{"q":"Kuygan joy toza, salqin suv bilan sovutiladi va toza bog'lam bilan yopiladi; yog' surtilmaydi, pufakcha yorilmaydi.","e":"Kuyishga faqat suv: yog' yo'q, pufak yorish yo'q."}],"chorraha":[{"q":"Teng ahamiyatli yo'llar chorrahasida o'ngdan yaqinlashayotganga yo'l beriladi; tramvay yo'nalishidan qat'i nazar oldin o'tadi.","e":"O'ngdan kelgan — mehmon: unga yo'l ber. Teng yo'lda tramvay — eng hurmatli mehmon."},{"q":"Ikkinchi darajali yo'ldagi haydovchi asosiy yo'ldagilarga, ular qayerga burilishidan qat'i nazar, yo'l beradi.","e":"2.4 yoki 2.5 ko'rdingmi — o'ng-chap hisobini unut, asosiy yo'ldagini o'tkaz."},{"q":"Chapga burilayotgan yoki qayrilib olayotgan haydovchi qarama-qarshidan to'g'riga va o'ngga ketayotganlarga yo'l beradi.","e":"Chapga burilsang — qarshidagi oqimni kesasan: avval ular o'tadi."},{"q":"Svetofor ishlamasa yoki sariq ishora miltillasa, chorraha tartibga solinmagan hisoblanadi va imtiyoz belgilariga amal qilinadi.","e":"Svetofor o'chdi — belgilar uyg'ondi."},{"q":"Svetofor tramvay va relssiz transport vositalariga bir vaqtda ruxsat bersa, tramvay oldin o'tadi.","e":"Bitta yashil, ikki da'vogar — tramvay birinchi."},{"q":"Aylanma harakatlanish chorrahasida aylana bo'ylab harakatlanayotganlar aylanaga kirib kelayotganlarga nisbatan imtiyozga ega.","e":"Tuzoq: aylanaga kirayotgan o'ngdan kelsa ham, imtiyoz aylanadagida."}],"ishora":[{"q":"Sariq ishora harakatlanishni taqiqlaydi; keskin tormozsiz to'xtay olmaydigan haydovchi harakatni davom ettirishi mumkin.","e":"Sariq — 'qizilning ukasi': to'xtay olsang, to'xta."},{"q":"Miltillovchi sariq ishora ehtiyot bo'lib harakatlanishga ruxsat beradi va tartibga solinmagan chorraha haqida xabar beradi.","e":"Sariq miltillasa — svetofor 'dam olmoqda': belgilarga qara."},{"q":"Qizil yoki sariq bilan birga yongan qo'shimcha strelka bo'yicha harakatlanayotgan haydovchi boshqa yo'nalishlardagilarga yo'l beradi.","e":"Strelka — ruxsatnoma, imtiyoz emas."},{"q":"Tartibga soluvchi qo'llarini yonga uzatsa: ko'krak va orqa tomondan — taqiq, yon tomondan relssizlarga — to'g'riga va o'ngga.","e":"Qo'llar yonda: ko'krak va orqa — devor, yonlar — ochiq eshik."},{"q":"O'ng qo'l oldinga cho'zilsa: chap yondan relssizlarga — barcha yo'nalish, ko'krak tomondan — faqat o'ngga, o'ng yon va orqadan — taqiq.","e":"Tayoqcha yuzingga qarasa — faqat o'ngga; chap tomoningni ko'rsatsa — istalgan tomonga."},{"q":"Tartibga soluvchining ishoralari svetofor, belgilar va chiziqlardan ustun; svetofor ishoralari esa imtiyoz belgilaridan ustun.","e":"Tartibga soluvchi > svetofor > imtiyoz belgisi."}],"manevr":[{"q":"Burilish ishorasi manyovrdan oldinroq beriladi, tugagach darhol o'chiriladi va haydovchiga imtiyoz bermaydi.","e":"Ko'rsatkich — iltimos, buyruq emas."},{"q":"Qayta tizilishda o'sha tasmadagilarga, bir vaqtda qayta tizilishda esa o'ng tomondagi transport vositasiga yo'l beriladi.","e":"Begona tasma — begona uy; ikkovlon bir vaqtda kirsa — o'ngdagi oldin."},{"q":"Burilish va qayrilib olishdan oldin qatnov qismining tegishli chetki holati oldindan egallanadi.","e":"Qayerga burilsang — o'sha chetga oldindan o't."},{"q":"Qayrilib olish taqiq: piyodalar o'tish joyida, tunnelda, ko'prik ustida va ostida, temir yo'l kesishmasida, ko'rinish 100 m dan kam joyda.","e":"Yuz metr ko'rinmasa — qayrilish yuz foiz taqiq."},{"q":"Orqaga harakatlanish chorrahalarda va qayrilib olish taqiqlangan joylarda taqiqlanadi.","e":"Qayrilib bo'lmaydigan joyda orqaga ham yurilmaydi."},{"q":"Chap qo'l yonga yoki o'ng qo'l tirsakdan bukib yuqoriga — chapga burilish; istalgan qo'l tik yuqoriga — to'xtash.","e":"Bukilgan qo'l — teskari yo'nalish: o'ng qo'l bukilsa chapga, chap qo'l bukilsa o'ngga."}],"umumiy":[{"q":"To'xtash — harakatni 10 daqiqagacha to'xtatish; to'xtab turish — 10 daqiqadan ko'p (yo'lovchi yoki yuk bilan bog'liq bo'lmagan maqsadda).","e":"10 daqiqa — chegara; yuk ortish va yo'lovchi tushirish esa doim to'xtash."},{"q":"Quvib o'tishda qarama-qarshi yo'nalish tasmasiga chiqiladi; o'zib ketish — bir yo'nalishdagi vositadan tezroq yurib o'tib ketish.","e":"Qarshi tasmaga chiqdingmi — quvib o'tish; o'z tomoningda — o'zib ketish."},{"q":"Yo'l berish — imtiyozli ishtirokchini yo'nalish yoki tezlikni o'zgartirishga majbur qiladigan harakat va manyovrni qilmaslik.","e":"Mezon — uning tormozi: sen tufayli u sekinlasa, yo'l bermading."},{"q":"Yondosh hududdan chiqish joyi chorraha emas; undan chiqqan haydovchi yo'ldagi transport vositalari va piyodalarga yo'l beradi.","e":"Hovlidan chiqqan — hammaga yo'l beradi."},{"q":"Yetarlicha ko'rinmaslik — yomg'ir, qor, tuman yoki g'ira-shira tufayli yo'l ko'rinishi 300 m dan kam bo'lishi.","e":"Tuzoq: 100 m — qayrilish taqiqi, 300 m — yetarlicha ko'rinmaslik."},{"q":"Haydovchi va old o'rindiqdagi yo'lovchilar kamar taqishi shart; orqa o'rindiqdagi 12 yoshgacha bolalar bundan ozod.","e":"Tuzoq: 'qisqa masofa' bahona emas; orqadagi 12 yoshgacha bola esa ozod."}],"tezlik":[{"q":"Aholi punktida 70 km/soat; shaharlarda, Nukus va Toshkentda, viloyat va tuman markazlarida 60 km/soat.","e":"Qishloq — 70, shahar va markaz — 60."},{"q":"Aholi punktidan tashqarida: yengil va 3,5 t gacha yuk — 100, shaharlararo avtobus — 90, og'ir yuk, moto — 80, tirkamali yuk — 70 km/soat.","e":"Zinapoya 100-90-80-70."},{"q":"Turar joy dahasi va hovlilarda 20 km/soat; belgili maktab yaqinida 300 m dan kam masofada 30 km/soat.","e":"Hovli — 20; maktab '3-3': 300 m, 30 km/soat."},{"q":"Har qanday yo'lda: shatakka olgan vosita — 50, bolalar guruhini yoki yukxonada odam tashiyotgan vosita — 60 km/soat.","e":"Shatak — 50, bolalar — 60: yo'l qanday bo'lmasin."},{"q":"Quvib o'tish taqiq: tartibga solingan chorrahada, ko'prikda, piyodalar o'tish joyida, temir yo'l kesishmasiga 100 m dan kam qolganda.","e":"Relsga 100 m qoldi — quvib o'tishni unut."},{"q":"Quvib o'tilayotgan haydovchiga tezlikni oshirish yoki boshqa harakatlar bilan to'sqinlik qilish taqiqlanadi.","e":"Seni quvib o'tishyapti — poyga emas."}],"toxtash":[{"q":"To'xtash taqiq: piyodalar o'tish joyiga 10 m, kesishayotgan qatnov qismi chetiga 30 m, maydonchasiz bekat belgisiga 15 m dan kam qolganda.","e":"'10-30-15': zebra, chorraha, bekat."},{"q":"Temir yo'l kesishmasida to'xtash, uning har ikkala tomonida 50 m yaqinida to'xtab turish taqiqlanadi.","e":"'50 turish, 100 quvish': relsdan 50 m — to'xtab turma, 100 m — quvib o'tma."},{"q":"3.27 belgisi to'xtashni ham, to'xtab turishni ham taqiqlaydi; 3.28 faqat to'xtab turishni taqiqlaydi.","e":"Bitta qizil chiziq — turish mumkin emas, ikkita X — to'xtash ham mumkin emas."},{"q":"Aholi punktida chap tomonda to'xtash faqat bir tomonlama yo'lda va har yo'nalishda bitta tasmali, tramvaysiz yo'lda mumkin.","e":"Chapda to'xtash — ikki holatda: bir tomonlama yoki bir tasmali tramvaysiz yo'l."},{"q":"Avariya sababli to'xtash belgisi aholi punktida kamida 15 m, aholi punktidan tashqarida kamida 30 m masofaga qo'yiladi.","e":"Shaharda 15, tashqarida ikki barobar — 30."},{"q":"Bir yo'nalishda uchtadan kam tasmali ko'prik, yo'l o'tkazgich va estakada ustida va ostida to'xtash taqiqlanadi.","e":"Tuzoq: yo'lovchi tushirish ham to'xtash hisoblanadi."}],"maxsus":[{"q":"Tartibga solinmagan piyodalar o'tish joyida haydovchi o'tayotgan piyodalarga yo'l berish uchun tezlikni kamaytiradi yoki to'xtaydi.","e":"Piyoda qatnov qismini kesib o'tyaptimi — u birinchi."},{"q":"Oq hassa bilan ishora berayotgan ko'zi ojiz piyoda har qanday joyda o'tkazib yuboriladi.","e":"Oq hassa — 'ko'chma zebra'."},{"q":"Temir yo'l kesishmasida to'xtash joyi belgilanmagan bo'lsa: shlagbaumdan kamida 5 m, shlagbaum bo'lmasa birinchi relsdan kamida 10 m oldin.","e":"Shlagbaum — 5, shlagbaumsiz — 10."},{"q":"Kesishmada majburan to'xtab qolganda haydovchi darhol odamlarni tushiradi va kesishmani bo'shatish choralarini ko'radi.","e":"Avval odamlar, keyin mashina."},{"q":"Avtomagistralda qayrilib olish, orqaga yurish, o'quv haydash taqiq; moped, velosiped, traktor va 40 km/soatdan sekin vositalar kirmaydi.","e":"Avtomagistral — bir tomonga oqar daryo: qayrilish ham, orqaga yurish ham yo'q."},{"q":"Turar joy dahasida tezlik 20 km/soat; piyodalar qatnov qismida ham yurishi mumkin va imtiyozga ega.","e":"Turar joy dahasida piyoda birinchi, mashina ikkinchi."}]},"biletlar":[[59,131,40,101,177,195,72,16,130,173,17,96,125,103,47,165,70,152,76,25],[107,136,151,79,67,113,104,58,176,143,193,23,41,169,29,19,180,22,127,64],[186,18,99,178,32,31,121,140,138,181,150,45,63,156,30,81,57,105,144,100],[158,183,27,37,174,109,50,6,142,145,52,82,35,119,93,198,147,71,137,91],[56,15,146,24,106,118,92,135,172,110,87,75,48,179,132,189,161,66,34,28],[44,62,7,114,200,89,39,191,84,184,108,12,10,154,167,139,157,123,77,53],[163,188,60,73,83,197,124,128,5,9,171,65,149,97,90,4,129,166,42,38],[187,199,61,153,13,94,3,115,78,85,175,98,55,134,160,49,33,162,26,122],[54,21,36,164,148,120,20,69,112,80,116,86,14,95,192,159,190,141,43,185],[155,102,8,46,111,126,194,68,196,170,1,11,182,88,133,117,168,51,2,74]]};
